using DanaProcessing.Reels;

// @reel title: Ep 01 · Hello, Canvas
// @reel subtitle: Creative coding in C#, from zero
// @reel result: 6 caption="Two methods. Infinite possibilities."
// @reel outro: Next · Ep 02: Shapes & Color

// @reel scene "What if code could paint?"

// @reel scene "Setup() runs once: it makes the canvas" effect=type
public class HelloCanvas : Sketch
{
    public override void Setup()
    {
        Size(600, 600);   // @mark
        NoStroke();
    }

    // @reel scene "Draw() runs 60 times every second" effect=type transition=slide
    public override void Draw()
    {
        Background(24, 20, 18);
        // @reel caption: FrameCount goes up by one every frame...
        float t = FrameCount * 0.03f;
        float x = Width / 2 + Cos(t) * 180;
        float y = Height / 2 + Sin(t) * 180;
        // @reel caption: ...so the circle never stands still
        Fill(255, 176, 140);
        Circle(x, y, 80);   // @mark
    }
}

using DanaProcessing.Reels;

// @reel title: Ep 02 · Shapes & Color
// @reel subtitle: A sunset made of rectangles and one circle
// @reel result: 6 caption="A few shapes. One whole mood."
// @reel outro: Next · Ep 03: Motion

// @reel scene "Every picture is just shapes + color"

// @reel scene "The sky: thin stripes, each one a new hue" effect=type
public class Sunset : Sketch
{
    public override void Setup()
    {
        Size(600, 600);
        NoStroke();
    }

    public override void Draw()
    {
        for (int y = 0; y < Height; y += 10)
        {
            float hue = Map(y, 0, Height, 260, 20);
            FillHSB(hue, 60, 90);   // @mark
            Rect(0, y, Width, 10);
        }
        // @reel scene "The sun: a circle that slowly breathes" effect=type keep
        float sunY = 330 + Sin(FrameCount * 0.03f) * 20;
        Fill(255, 200, 120);
        Circle(Width / 2, sunY, 180);
        // @reel caption: Drawn last, the sea covers the sun
        Fill(30, 40, 80);
        Rect(0, 400, Width, 200);   // @mark
    }
}

using DanaProcessing.Reels;

// @reel title: Ep 03 · Motion
// @reel subtitle: Position, velocity, gravity. That's physics.
// @reel result: 7 caption="Three numbers per axis. It feels alive."
// @reel outro: Next · Ep 04: The Mouse

// @reel scene "Motion is just numbers that change"

// @reel scene "Where the ball is, and where it's going" effect=lines
public class Bounce : Sketch
{
    float x = 300, y = 120;
    float vx = 5, vy = 0;

    public override void Setup()
    {
        Size(600, 600);
        Background(20);
        NoStroke();
    }

    // @reel scene "Every frame: gravity pulls, velocity moves" effect=type transition=slide
    public override void Draw()
    {
        Fill(20, 20, 24, 40);        // see-through = trails
        Rect(0, 0, Width, Height);
        vy += 0.4f;                  // @mark
        x += vx;
        y += vy;
        // @reel caption: Hit a wall? Flip the direction.
        if (x < 30 || x > Width - 30) vx = -vx;
        if (y > Height - 30)
        {
            y = Height - 30;
            vy *= -0.9f;             // @mark
        }
        FillHSB(FrameCount % 360, 70, 100);
        Circle(x, y, 60);
    }
}

using DanaProcessing.Reels;

// @reel title: Ep 04 · The Mouse
// @reel subtitle: A brush that chases your cursor
// @reel result: 8 caption="It follows you... but lazily."
// @reel outro: Next · Ep 05: Loops & Patterns

// @reel scene "Now the sketch listens to you"

// @reel scene "Two numbers: where the brush is" effect=type
public class LazyBrush : Sketch
{
    float x = 300, y = 300;

    public override void Setup()
    {
        Size(600, 600);
        Background(16, 14, 22);
        NoStroke();
    }

    // @reel scene "Lerp: move 8% of the way, every frame" effect=type transition=slide
    public override void Draw()
    {
        x = Lerp(x, MouseX, 0.08f);   // @mark
        y = Lerp(y, MouseY, 0.08f);
        // @reel caption: Far from the mouse? Paint a bigger dot.
        float gap = Dist(x, y, MouseX, MouseY);
        FillHSB((200 + gap) % 360, 60, 100, 150);
        Circle(x, y, 10 + gap * 0.5f);   // @mark
    }
}

using DanaProcessing.Reels;

// @reel title: Ep 05 · Loops & Patterns
// @reel subtitle: 144 circles, one line of math
// @reel result: 7 caption="Distance + time = a ripple."
// @reel outro: Next · Ep 06: Random vs Noise

// @reel scene "Why draw one circle when a loop can draw 144?"

// @reel scene "Two loops make a grid" effect=type
public class Ripple : Sketch
{
    public override void Setup()
    {
        Size(600, 600);
        NoStroke();
    }

    public override void Draw()
    {
        Background(14, 16, 24);
        for (int i = 0; i < 12; i++)
        for (int j = 0; j < 12; j++)
        {
            float x = 25 + i * 50;
            float y = 25 + j * 50;
            // @reel scene "Distance from the center, shifted by time" effect=type keep
            float d = Dist(x, y, 300, 300);
            float wave = d * 0.04f - FrameCount * 0.08f;
            float s = Sin(wave);   // @mark
            // @reel caption: The wave picks both the color and the size
            FillHSB(180 + s * 60, 70, 100);
            Circle(x, y, 20 + s * 18);   // @mark
        }
    }
}

using DanaProcessing.Reels;

// @reel title: Ep 06 · Random vs Noise
// @reel subtitle: Two kinds of "unpredictable"
// @reel result: 7 caption="Top: chaos. Bottom: nature."
// @reel outro: Next · Ep 07: Sin & Cos

// @reel scene "Not all randomness looks the same"

// @reel scene "Random(): each value forgets the last one" effect=type
public class RandomVsNoise : Sketch
{
    float t;

    public override void Setup()
    {
        Size(600, 600);
        StrokeWeight(3);
        TextSize(24);
    }

    public override void Draw()
    {
        Background(18, 18, 22);
        NoFill();
        Stroke(255, 130, 130);
        BeginShape();
        for (int x = 0; x <= Width; x += 10)
            Vertex(x, 170 + Random(-60, 60));   // @mark
        EndShape();

        // @reel scene "Noise(): each value remembers its neighbor" effect=type keep
        Stroke(130, 220, 255);
        BeginShape();
        for (int x = 0; x <= Width; x += 10)
        {
            float n = Noise(x * 0.01f, t) - 0.5f;   // @mark
            Vertex(x, 430 + n * 240);
        }
        EndShape();
        t += 0.01f;

        // @reel hide
        NoStroke();
        Fill(255, 130, 130);
        Text("Random()", 20, 50);
        Fill(130, 220, 255);
        Text("Noise()", 20, 320);
        // @reel show
    }
}

using DanaProcessing.Reels;

// @reel title: Ep 07 · Sin & Cos
// @reel subtitle: The two functions behind every circle
// @reel result: 8 caption="Orbit an orbit and it blooms."
// @reel outro: Next · Ep 08: Fireworks

// @reel scene "Trigonometry, but make it pretty"

// @reel scene "A dark canvas that slowly forgets" effect=lines
public class Bloom : Sketch
{
    public override void Setup()
    {
        Size(600, 600);
        Background(12, 10, 20);
        NoStroke();
    }

    // @reel scene "Cos gives x, Sin gives y: a circle" effect=type transition=zoom
    public override void Draw()
    {
        Fill(12, 10, 20, 12);
        Rect(0, 0, Width, Height);
        float t = FrameCount * 0.02f;
        float x = 300 + Cos(t) * 170;
        float y = 300 + Sin(t) * 170;   // @mark
        // @reel caption: Now add a faster, smaller circle on top...
        x += Cos(t * 7) * 70;
        y += Sin(t * 7) * 70;           // @mark
        FillHSB((t * 40) % 360, 70, 100);
        Circle(x, y, 9);
    }
}

using DanaProcessing.Reels;

// @reel title: Ep 08 · Fireworks
// @reel subtitle: Your first class: a spark
// @reel result: 7 caption="Click anywhere. Boom."
// @reel click 190,230 at=0.4
// @reel click 420,170 at=1.6
// @reel click 300,330 at=2.9
// @reel click 160,410 at=4.1
// @reel click 450,400 at=5.0

// @reel scene "One spark is easy. A thousand needs a class."

// @reel scene "A spark knows where it is, and how long it lives" effect=type
class Spark
{
    public PVector Pos, Vel;
    public float Hue, Life = 255;
}

// @reel scene "Every frame: fall, move, fade" effect=type transition=slide
public class Fireworks : Sketch
{
    readonly List<Spark> sparks = new();

    public override void Setup()
    {
        Size(600, 600);
        NoStroke();
    }

    public override void Draw()
    {
        Background(10, 10, 20);
        foreach (var s in sparks)
        {
            s.Vel.Y += 0.08f;
            s.Pos.Add(s.Vel);
            s.Life -= 3;   // @mark
            FillHSB(s.Hue, 60, 100, (byte)Max(0, s.Life));
            Circle(s.Pos.X, s.Pos.Y, 5);
        }
        sparks.RemoveAll(s => s.Life <= 0);
    }

    // @reel scene "A click spawns 120 sparks" effect=type keep
    public override void MousePressed()
    {
        float hue = Random(360);
        for (int i = 0; i < 120; i++)
            sparks.Add(new Spark
            {
                Pos = new PVector(MouseX, MouseY),
                Vel = PVector.FromAngle(Random(TWO_PI))
                             .Mult(Random(1, 6)),
                Hue = hue,
            });
    }
}

using DanaProcessing.Reels;

// @reel title: Ep 09 · Recursion
// @reel subtitle: A function that calls itself grows a tree
// @reel result: 8 caption="Move the mouse: the tree bends."
// @reel move 80,300 -> 520,300 -> 300,300 at=0.3 dur=6

// @reel scene "A tree is a branch... made of smaller trees"

// @reel scene "Start at the bottom; the mouse sets the angle" effect=type
public class Tree : Sketch
{
    public override void Setup() => Size(600, 600);

    public override void Draw()
    {
        Background(16, 18, 14);
        Stroke(230, 220, 200);
        float angle = Radians(Map(MouseX, 0, Width, 10, 50));
        Translate(300, 580);
        Branch(140, angle);
    }

    // @reel scene "Draw a line, then call yourself twice" effect=type transition=slide
    void Branch(float len, float angle)
    {
        StrokeWeight(len * 0.08f);
        Line(0, 0, 0, -len);
        Translate(0, -len);
        // @reel caption: Too small? Stop. Otherwise it never ends.
        if (len < 8) return;   // @mark
        PushMatrix();
        Rotate(angle);
        Branch(len * 0.7f, angle);   // @mark
        PopMatrix();
        PushMatrix();
        Rotate(-angle);
        Branch(len * 0.7f, angle);
        PopMatrix();
    }
}

using DanaProcessing.Reels;

// @reel title: Ep 10 · Flow Field
// @reel subtitle: Everything from this series, in one piece of art
// @reel result: 10 caption="800 dots, following invisible wind."
// @reel outro: That's the intro series. Now go make something.

// @reel scene "Remember Noise()? Let's turn it into wind."

// @reel scene "800 dots, scattered at random" effect=lines
public class FlowField : Sketch
{
    readonly List<PVector> dots = new();

    public override void Setup()
    {
        Size(600, 600);
        Background(12, 12, 16);
        NoStroke();
        for (int i = 0; i < 800; i++)
            dots.Add(Spot());
    }

    PVector Spot() => new PVector(Random(Width), Random(Height));

    // @reel scene "Noise picks a direction for every spot" effect=type transition=wipe
    public override void Draw()
    {
        for (int i = 0; i < dots.Count; i++)
        {
            var p = dots[i];
            float n = Noise(p.X * 0.005f, p.Y * 0.005f);
            float a = n * TWO_PI * 2;   // @mark
            p.X += Cos(a);
            p.Y += Sin(a);   // @mark
            // @reel caption: Each dot leaves a faint trail of color
            FillHSB(Map(n, 0, 1, 180, 330), 60, 100, 18);
            Circle(p.X, p.Y, 2);
            bool gone = p.X < 0 || p.X > Width
                     || p.Y < 0 || p.Y > Height;
            if (gone)
                p = Spot();
            dots[i] = p;
        }
    }
}

using DanaProcessing.Reels;
// @reel hide   (everything below is the sketch, not typed on screen)

// DanaProcessing's 60-second promo -- picture AND music -- in one sketch.
//
//   Sketch > Create reel > Export   ->  a 1920x1080 MP4 with sound, ready
//   for YouTube, X or Reddit. (The preview in that window is slow on the
//   shader parts; the export renders every frame, so the video is smooth.)
//
// How it's built: one bar of 120 BPM = 2 seconds, and every shot starts on a
// bar, so the cuts land on the music. The music is the [LiveLoop]s at the end;
// Seconds() reads the same clock the music plays on, so picture and sound stay
// together. Change a caption, a color or a riff and export again.
//
// @reel format: landscape
// @reel result: 61 full
// @reel outro: off
// @reel mouse: off
// @reel audio: on
public class DanaPromo : Sketch
{
    // ------------------------------------------------------------ palette & type
    static readonly Color Ink = new(0x13, 0x20, 0x2A), Ink2 = new(0x1C, 0x2E, 0x3B), OnInk = new(0xF4, 0xEB, 0xDD),
                          Muted = new(0xB9, 0xC7, 0xD2), Gold = new(0xE7, 0xB6, 0x6B), Coral = new(0xFF, 0x8A, 0x6B),
                          Mint = new(0x8F, 0xD3, 0xB6), Sky = new(0x9D, 0xB8, 0xF2);

    PFont heavy = null!, display = null!, body = null!, bodyBold = null!, mono = null!;

    /// <summary>The first font file that exists: Windows, then macOS, then Linux; the system font otherwise.</summary>
    PFont FontFrom(params string[] files)
    {
        foreach (var f in files)
            if (File.Exists(f))
                return LoadFont(f, 48);
        return CreateFont("sans-serif", 48);
    }

    // Video time in seconds, on the music's clock (2 beats = 1 second at 120 BPM).
    // When live loops start from silence, their first downbeat lands on the next
    // bar line, so Beat() is 4 (not 0) when the music starts: the first note we
    // hear marks that bar, and time counts from there. With no sound (the
    // preview in the Create reel window) no note arrives and Beat() starts at 0.
    double musicStart = -1;
    bool heardMusic;

    public override void OnNote(NoteEvent e) => heardMusic = true;

    float Seconds()
    {
        double b = Beat();
        if (heardMusic && musicStart < 0)
            musicStart = Math.Floor(b / 4 + 1e-6) * 4;
        return (float)Math.Max(0, b - Math.Max(0, musicStart)) / 2f;
    }

    float T;                                   // Seconds() for this frame

    public override void Setup()
    {
        Size(1920, 1080);
        Bpm = 120;
        heavy = FontFrom(@"C:\Windows\Fonts\seguibl.ttf", "/System/Library/Fonts/Supplemental/Arial Black.ttf",
                         "/usr/share/fonts/opentype/inter/InterDisplay-Black.otf");
        display = FontFrom(@"C:\Windows\Fonts\segoeuib.ttf", "/System/Library/Fonts/Supplemental/Arial Bold.ttf",
                           "/usr/share/fonts/opentype/inter/InterDisplay-ExtraBold.otf");
        body = FontFrom(@"C:\Windows\Fonts\segoeui.ttf", "/System/Library/Fonts/Supplemental/Arial.ttf",
                        "/usr/share/fonts/opentype/inter/Inter-Regular.otf");
        bodyBold = FontFrom(@"C:\Windows\Fonts\seguisb.ttf", "/System/Library/Fonts/Supplemental/Arial Bold.ttf",
                            "/usr/share/fonts/opentype/inter/Inter-SemiBold.otf");
        mono = FontFrom(@"C:\Windows\Fonts\CascadiaMono.ttf", @"C:\Windows\Fonts\consola.ttf", "/System/Library/Fonts/Menlo.ttc",
                        "/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf");
        plasma = CreateShader2D(PlasmaSource);
        rings = CreateShader2D(RingsSource);
        PrepareLife();
    }

    public override void Draw()
    {
        T = Seconds();
        if (T < 6) Hook(T);
        else if (T < 10) TypedCode(T - 6, ParticleCode, "Particles.cs", "Write a sketch in C#", markLine: 11);
        else if (T < 18) Particles(T - 10);
        else if (T < 22) TypedCode(T - 18, MusicCode, "Music.cs", "The music in this video is this code", markLine: 14);
        else if (T < 30) BeatScene(T - 22);
        else if (T < 42) Stage(T - 30);
        else if (T < 52) Montage(T - 42);
        else Outro(T - 52);
    }

    // ------------------------------------------------------------ helpers
    static float Smooth(float a, float b, float t)
    {
        float x = Math.Clamp((t - a) / (b - a), 0f, 1f);
        return x * x * (3 - 2 * x);
    }

    void FillC(Color c, float alpha = 255) => Fill(c.R, c.G, c.B, alpha);

    /// <summary>A rounded rectangle as one shape (a see-through fill stays even).</summary>
    void RoundRect(float x, float y, float w, float h, float r)
    {
        r = Math.Min(r, Math.Min(w, h) / 2);
        (float cx, float cy, float from)[] corners =
            { (x + w - r, y + r, -HALF_PI), (x + w - r, y + h - r, 0), (x + r, y + h - r, HALF_PI), (x + r, y + r, PI) };
        BeginShape();
        foreach (var (cx, cy, from) in corners)
            for (int i = 0; i <= 8; i++)
                Vertex(cx + Cos(from + HALF_PI * i / 8) * r, cy + Sin(from + HALF_PI * i / 8) * r);
        EndShape(true);
    }

    /// <summary>The caption card, bottom-left; <paramref name="t"/> is the shot's own time.</summary>
    void Caption(string title, string sub, float t, float start, float end)
    {
        float a = Smooth(start, start + 0.35f, t) * (1 - Smooth(end - 0.35f, end, t));
        if (a <= 0) return;
        float rise = (1 - Smooth(start, start + 0.5f, t)) * 24;
        PushStyle();
        TextFont(display, 54);
        float tw = TextWidth(title);
        TextFont(body, 30);
        float sw = TextWidth(sub);
        float w = Max(tw, sw) + 120, h = 150, x = 72, y = Height - 72 - h + rise;
        NoStroke();
        FillC(Ink, 225 * a);
        RoundRect(x, y, w, h, 28);
        FillC(Gold, 255 * a);
        Circle(x + 44, y + 52, 18);
        TextAlign(TextAlignH.Left, TextAlignV.Baseline);
        FillC(OnInk, 255 * a);
        TextFont(display, 54);
        Text(title, x + 76, y + 70);
        FillC(Muted, 255 * a);
        TextFont(body, 30);
        Text(sub, x + 76, y + 114);
        PopStyle();
    }

    /// <summary>The DanaProcessing mark, top-left (dark ink on light pictures).</summary>
    void Mark(bool onLight = false)
    {
        var line = onLight ? Ink : OnInk;
        PushStyle();
        NoFill();
        Stroke(line.R, line.G, line.B, 230);
        StrokeWeight(3);
        Circle(96, 84, 40);
        NoStroke();
        FillC(Gold);
        Circle(96, 84, 18);
        FillC(Coral);
        Circle(109, 70, 7);
        FillC(line, 235);
        TextFont(bodyBold, 30);
        TextAlign(TextAlignH.Left, TextAlignV.Center);
        Text("DanaProcessing", 132, 82);
        PopStyle();
    }

    void FadeTo(Color c, float t, float from, float to)
    {
        float a = Smooth(from, to, t);
        if (a <= 0) return;
        NoStroke();
        FillC(c, 255 * a);
        Rect(0, 0, Width, Height);
    }

    static readonly HashSet<string> Keywords = new()
        { "public", "class", "override", "void", "float", "var", "new", "foreach", "in", "readonly", "async", "await", "int", "string" };

    /// <summary>A tiny C# highlighter: keywords gold, numbers coral, strings mint, calls sky, types mint.</summary>
    void DrawCode(string line, float x, float y, float alpha = 245)
    {
        int i = 0;
        while (i < line.Length)
        {
            int j = i;
            Color c = OnInk;
            if (line[i] == '"') { j = line.IndexOf('"', i + 1); j = j < 0 ? line.Length : j + 1; c = Mint; }
            else if (line[i] == '/' && i + 1 < line.Length && line[i + 1] == '/') { j = line.Length; c = Muted; }
            else if (char.IsDigit(line[i])) { while (j < line.Length && (char.IsDigit(line[j]) || line[j] == '.' || line[j] == 'f')) j++; c = Coral; }
            else if (char.IsLetter(line[i]) || line[i] == '_')
            {
                while (j < line.Length && (char.IsLetterOrDigit(line[j]) || line[j] == '_')) j++;
                string word = line[i..j];
                if (Keywords.Contains(word)) c = Gold;
                else if (j < line.Length && line[j] == '(') c = Sky;
                else if (char.IsUpper(word[0]) && word is "Sketch" or "List" or "Particle" or "PVector" or "Task" or "Synth" or "LiveLoop") c = Mint;
            }
            else j = i + 1;
            string token = line[i..j];
            FillC(c, alpha);
            Text(token, x, y);
            x += TextWidth(token);
            i = j;
        }
    }

    // ------------------------------------------------------------ 0-6 s: the hook
    const string PlasmaSource = @"
uniform float iTime;
uniform float2 iResolution;
uniform float uPulse;
uniform float uLight;
half4 main(float2 fragCoord) {
    float2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    float d = length(uv);
    float v = (sin(10.0 * d - iTime * 2.2 + uPulse * 1.6) + sin(5.0 * uv.x + iTime * 0.7) + sin(4.0 * (uv.x + uv.y) - iTime * 0.9)) / 3.0;
    float3 ink = float3(0.075, 0.125, 0.165), gold = float3(0.906, 0.714, 0.420);
    float3 coral = float3(1.0, 0.541, 0.420), sky = float3(0.616, 0.722, 0.949);
    float3 col = mix(ink, sky, smoothstep(-0.6, 0.9, v) * 0.55);
    col = mix(col, coral, smoothstep(0.35, 1.0, v) * 0.65);
    col = mix(col, gold, smoothstep(0.75, 1.0, v));
    col += uPulse * 0.10 * exp(-d * 2.5);
    col *= uLight * (1.0 - 0.55 * smoothstep(0.2, 1.1, d));
    return half4(half3(col), 1.0);
}";
    PShader2D plasma = null!;

    void Hook(float t)
    {
        float pulse = t >= 4 ? Pulse(1, sharpness: 4) : 0;        // the kick comes in on bar 2
        plasma.Set("uPulse", pulse);
        plasma.Set("uLight", 0.35f + 0.65f * Smooth(0, 1.2f, t));
        Shade(plasma);

        NoStroke();
        float band = 130 * Smooth(0, 0.6f, t);
        for (int y = 250; y < 830; y += 4)
        {
            FillC(Ink, band * Math.Min(Smooth(250, 330, y), 1 - Smooth(750, 830, y)));
            Rect(0, y, Width, 4);
        }

        string[] words = { "Draw.", "Play.", "Perform." };
        float[] at = { 0.25f, 1.25f, 2.25f };
        TextFont(heavy, 150);
        float gap = 48, total = gap * 2;
        foreach (var w in words) total += TextWidth(w);
        float x = (Width - total) / 2;
        TextAlign(TextAlignH.Left, TextAlignV.Baseline);
        for (int i = 0; i < words.Length; i++)
        {
            float k = Smooth(at[i], at[i] + 0.45f, t);
            FillC(i == 2 ? Gold : OnInk, 255 * k);
            Text(words[i], x, 560 + (1 - k) * 40 - pulse * 6);
            x += TextWidth(words[i]) + gap;
        }
        float s = Smooth(3.2f, 3.8f, t);
        TextFont(body, 44);
        TextAlign(TextAlignH.Center, TextAlignV.Baseline);
        FillC(OnInk, 235 * s);
        Text("Creative coding in C#: visuals, music and live code.", Width / 2f, 660 + (1 - s) * 20);
        if (t > 0.5f) Mark();
        FadeTo(Ink, t, 5.7f, 6f);
    }

    // ------------------------------------------------------------ typed code (6-10 s, 18-22 s)
    static readonly string[] ParticleCode =
