using System;
using System.Collections.Generic;
using NAudio.Midi;
// Dana has its own MidiMessage (OnMidi): NAudio's is written out in full, NAudio.Midi.MidiMessage,
// or the compiler can't tell which one you mean.

// Balls bouncing in a box -- every wall they hit plays a note through MIDI
// output 0, from a minor pentatonic scale (so it always sounds good). On
// Windows output 0 is the built-in "Microsoft GS Wavetable Synth", so it plays
// with no setup at all; with a virtual port (loopMIDI) or a USB synth it plays
// your DAW or hardware instead. NAudio's MIDI is Windows-only.
//
// Click to add a ball, right-click to remove one. The [Tweak] panel changes
// gravity, the root note, the instrument and how long notes ring -- live.
// OnStop() silences anything still sounding and releases the MIDI port.
public class MySketch : Sketch
{
    private static readonly int[] Pentatonic = { 0, 3, 5, 7, 10, 12, 15, 17 };

    [Tweak(0, 0.6f)] float gravity = 0.18f;
    [Tweak(36, 72)] int rootNote = 48;
    [Tweak(0, 127, Label = "instrument (GM)")] int program = 11; // 11 = vibraphone
    [Tweak(50, 2000, Label = "note ms")] int noteLength = 450;

    private MidiOut? _midi;
    private string _status = "";
    private int _sentProgram = -1;
    private readonly List<Ball> _balls = new List<Ball>();
    private readonly List<(int Note, long OffAt)> _sounding = new List<(int Note, long OffAt)>();

    private sealed class Ball
    {
        public float X, Y, VX, VY, Radius, Flash;
        public int Degree;
    }

    public override void Setup()
    {
        Size(820, 560);
        try
        {
            if (MidiOut.NumberOfDevices > 0)
            {
                _midi = new MidiOut(0);
                _status = "MIDI out: " + MidiOut.DeviceInfo(0).ProductName;
            }
            else
            {
                _status = "No MIDI output found -- silent";
            }
        }
        catch (Exception ex)
        {
            _status = "MIDI unavailable (" + ex.GetType().Name + ") -- silent";
        }

        for (int i = 0; i < 4; i++)
            AddBall(Random(100, Width - 100), Random(80, Height / 2f));
    }

    private void AddBall(float x, float y)
    {
        _balls.Add(new Ball
        {
            X = x,
            Y = y,
            VX = Random(-5, 5),
            VY = Random(-2, 2),
            Radius = Random(14, 30),
            Degree = _balls.Count % Pentatonic.Length,
        });
    }

    public override void Draw()
    {
        Background(14, 16, 24, 90); // translucent: leaves trails

        if (program != _sentProgram)
        {
            Send(NAudio.Midi.MidiMessage.ChangePatch(Constrain(program, 0, 127), 1));
            _sentProgram = program;
        }

        foreach (var ball in _balls)
        {
            ball.VY += gravity;
            ball.X += ball.VX;
            ball.Y += ball.VY;

            bool hit = false;
            if (ball.X < ball.Radius || ball.X > Width - ball.Radius)
            {
                ball.VX = -ball.VX;
                ball.X = Constrain(ball.X, ball.Radius, Width - ball.Radius);
                hit = true;
            }
            if (ball.Y > Height - ball.Radius)
            {
                ball.VY = -Math.Abs(ball.VY) * 0.98f;
                ball.Y = Height - ball.Radius;
                hit = true;
            }
            if (ball.Y < ball.Radius)
            {
                ball.VY = Math.Abs(ball.VY);
                ball.Y = ball.Radius;
                hit = true;
            }

            if (hit)
            {
                // Higher on screen = higher note; bigger ball = louder.
                int degree = (ball.Degree + (int)Map(ball.Y, Height, 0, 0, 4)) % Pentatonic.Length;
                PlayNote(rootNote + Pentatonic[degree], (int)Map(ball.Radius, 14, 30, 60, 120));
                ball.Flash = 1;
            }

            ball.Flash *= 0.9f;
            NoStroke();
            FillHSB(ball.Degree * 45 % 360, 60, 60 + ball.Flash * 40); // h 0-360, s and b 0-100
            Circle(ball.X, ball.Y, ball.Radius * 2 * (1 + ball.Flash * 0.3f));
        }

        ReleaseFinishedNotes();

        Fill(170);
        TextSize(13);
        Text($"{_status}   |   {_balls.Count} balls   |   click: add   right-click: remove", 16, Height - 16);
    }

    private void PlayNote(int note, int velocity)
    {
        note = Constrain(note, 0, 127);
        Send(NAudio.Midi.MidiMessage.StartNote(note, Constrain(velocity, 1, 127), 1));
        _sounding.Add((note, Millis() + noteLength));
    }

    private void ReleaseFinishedNotes()
    {
        long now = Millis();
        for (int i = _sounding.Count - 1; i >= 0; i--)
        {
            if (_sounding[i].OffAt > now)
                continue;
            Send(NAudio.Midi.MidiMessage.StopNote(_sounding[i].Note, 0, 1));
            _sounding.RemoveAt(i);
        }
    }

    private void Send(NAudio.Midi.MidiMessage message)
    {
        try { _midi?.Send(message.RawData); }
        catch { /* device unplugged: keep drawing, just silently */ }
    }

    public override void MousePressed()
    {
        if (MouseButton == MouseButtonKind.Right)
        {
            if (_balls.Count > 0)
                _balls.RemoveAt(_balls.Count - 1);
        }
        else
        {
            AddBall(MouseX, MouseY);
        }
    }

    public override void OnStop()
    {
        foreach (var (note, _) in _sounding)
            Send(NAudio.Midi.MidiMessage.StopNote(note, 0, 1));
        _sounding.Clear();
        _midi?.Dispose();
        _midi = null;
    }
}

// Live shaders, Shadertoy-style -- a fragment shader in SkSL (Skia's GLSL:
// half4/float2 instead of vec4/vec2) painting every pixel, fed by the sound
// engine. Shade(source) compiles it once and caches it by its text, so:
//
//   change a number inside the shader below and press ⚡ Hot Reload (or save)
//   -> the new shader takes over instantly, time and music keep going.
//   A typo doesn't crash anything: the last good shader keeps running and the
//   compiler's message shows bottom-left.
//
// Uniforms filled in for you when declared: iTime, iResolution, iMouse
// (x, y, pressed), iFrame, iAmplitude and iSpectrum[8/16/32/64] -- here the
// bass of the beat below pushes the rings and the loudness lights the center.
// Runs on the CPU in the 2D renderer, every OS: keep the canvas modest (and
// try a lower supersampling in Settings if it gets heavy).
public class MySketch : Sketch
{
    const string Plasma = @"
uniform float iTime;
uniform float2 iResolution;
uniform float4 iMouse;
uniform float iAmplitude;
uniform float iSpectrum[16];

half4 main(float2 fragCoord) {
    float2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    float2 m = (iMouse.xy - 0.5 * iResolution) / iResolution.y;
    float d = length(uv - m * 0.6);
    float bass = iSpectrum[1] + iSpectrum[2];

    float v = sin(12.0 * d - iTime * 3.0 + bass * 5.0)
            + sin(7.0 * uv.x + iTime)
            + sin(6.0 * (uv.x + uv.y) - iTime * 1.3);
    v /= 3.0;

    float3 col = 0.5 + 0.5 * cos(6.2831 * (v + float3(0.0, 0.33, 0.67)) + iTime * 0.2);
    col += iAmplitude * 0.8 * exp(-d * 5.0);
    return half4(half3(col), 1.0);
}";

    public override void Setup()
    {
        Size(720, 450);
    }

    public override void Draw()
    {
        Shade(Plasma);
    }

    [LiveLoop]
    async Task Beat()
    {
        Sample("kick");
        await Sleep(0.5);
        Sample("hat");
        await Sleep(0.5);
        Sample("snare");
        await Sleep(0.5);
        Sample("hat");
        await Sleep(0.5);
    }

    [LiveLoop]
    async Task Bass()
    {
        UseSynth(Synth.Saw);
        foreach (var note in new[] { "E2", "E2", "G2", "D2" })
        {
            Play(note, release: 0.4, cutoff: 70);
            await Sleep(1);
        }
    }
}

// A neural network learns to write a word, live, and you watch it think in
// ASCII.
//
// No download and no library: the whole network is the Brain class at the
// bottom, plain C#. It only knows one thing: given a point (x, y) on the
// screen, how much ink goes there? It starts with random weights, so the
// screen is noise. Every frame it looks at a few hundred random points of the
// word, sees how wrong it was, and nudges its ~2,300 weights a little
// (backpropagation + Adam). In a few seconds the letters come out of the noise.
//
// Each character on screen is one question to the network: the more ink it
// answers, the denser the glyph. Where its answer is still changing -- where
// it's learning right now -- the glyph glows.
//
// - Type: a new word. The network doesn't start over: it unlearns the old
//   word while it learns the new one, so one melts into the other.
// - Enter: forget everything (new random weights) and learn from zero.
// - Mouse: swirls the network's input around the pointer. The letters bend,
//   because the network doesn't store a picture -- it's a function of (x, y).
// - Wheel: zoom out to see what it imagines outside the word.
// - Tab: other glyphs.  Space: pause the learning.
public class AsciiMind : Sketch
{
    const int Cols = 96, Rows = 30;                  // the ASCII screen
    const float CellW = 10, CellH = 18;
    const int SubX = 3, SubY = 5;                    // the word is learned a bit finer than it's shown
    const int StepsPerFrame = 4, BatchSize = 128;    // how much it practices per frame

    readonly string[] glyphSets = { " .:-=+*#%@", " .oO0@", " 01", " .,;!|I#", " ·•●" };
    int glyphSet;

    Brain brain;
    readonly System.Random rng = new System.Random(7);
    float[] target;                                  // the word as ink, 0..1, tw x th
    int tw = Cols * SubX, th = Rows * SubY;
    string word = "HOLA";
    PFont mono, heavy;

    readonly float[] ink = new float[Cols * Rows];   // the network's last answer for each character
    readonly float[] glow = new float[Cols * Rows];  // how much that answer moved lately
    float zoom = 1, shownZoom = 1;
    bool paused;
    readonly float[] lossHistory = new float[120];
    int lossCount;

    // For the HUD (and the tests).
    public float Loss { get; private set; } = 0.25f;
    public int Steps { get; private set; }
    public string Word => word;
    public float InkAt(int col, int row) => ink[row * Cols + col];

    public override void Setup()
    {
        Size(960, 640);
        mono = CreateFont("Consolas", 16);
        heavy = CreateFont("Arial Black", 100);
        brain = new Brain(rng);
        Learn(word);
    }

    /// <summary>Paints the word offscreen and keeps its pixels: that's what the network has to match.</summary>
    public void Learn(string newWord)
    {
        word = newWord.ToUpperInvariant();
        string text = word.Length == 0 ? "?" : word;
        var pg = CreateGraphics(tw, th);
        pg.BeginDraw();
        pg.Background(0);
        pg.NoStroke();
        pg.Fill(255);
        pg.TextFont(heavy);
        pg.TextAlign(TextAlignH.Center, TextAlignV.Center);
        // This canvas is squashed like the screen (a character is SubX x SubY
        // pixels here, CellW x CellH there), so draw the letters stretched to match.
        float stretch = (SubY / (float)SubX) / (CellH / CellW);
        pg.TextSize(100);
        float size = Min(100 * tw * 0.86f / Max(1, pg.TextWidth(text)), th * 0.7f / stretch);
        pg.TextSize(size);
        pg.PushMatrix();
        pg.Translate(tw / 2f, th / 2f);
        pg.Scale(1, stretch);
        pg.Text(text, 0, 0);
        pg.PopMatrix();
        pg.LoadPixels();
        target = new float[tw * th];
        for (int i = 0; i < target.Length; i++)
            target[i] = pg.Pixels[i].R / 255f;
        pg.EndDraw();
        pg.Dispose();
        // Soft edges: a light blur, so the borders of the letters come out as . : - =
        Blur(target, tw, th, 2);
        Blur(target, tw, th, 2);
    }

    public override void Draw()
    {
        Background(8, 9, 20);
        if (!paused)
            for (int s = 0; s < StepsPerFrame; s++)
                Train();

        // Ask the network about half the characters each frame (alternate rows):
        // the screen still updates 30 times a second and it costs half.
        shownZoom = Lerp(shownZoom, zoom, 0.12f);
        bool bend = MouseY > 0 && MouseY < Rows * CellH;
        float t = Millis() / 1000f;
        float left = (Width - Cols * CellW) / 2;
        for (int r = FrameCount % 2; r < Rows; r += 2)
            for (int c = 0; c < Cols; c++)
            {
                float x = (c + 0.5f) / Cols, y = (r + 0.5f) / Rows;
                if (bend)
                {
                    float dx = left + (c + 0.5f) * CellW - MouseX, dy = (r + 0.5f) * CellH - MouseY;
                    float a = 1.6f * Exp(-(dx * dx + dy * dy) / (2 * 110f * 110f)) * Sin(t * 1.7f);
                    x += (dx * Cos(a) - dy * Sin(a) - dx) / (Cols * CellW);
                    y += (dx * Sin(a) + dy * Cos(a) - dy) / (Rows * CellH);
                }
                float answer = brain.Think(0.5f + (x - 0.5f) * shownZoom, 0.5f + (y - 0.5f) * shownZoom);
                int i = r * Cols + c;
                glow[i] = Max(glow[i] * 0.9f, Abs(answer - ink[i]) * 12);
                ink[i] = answer;
            }

        TextFont(mono, 16);
        TextAlign(TextAlignH.Center, TextAlignV.Center);
        string glyphs = glyphSets[glyphSet];
        for (int r = 0; r < Rows; r++)
            for (int c = 0; c < Cols; c++)
            {
                int i = r * Cols + c;
                float v = ink[i], hot = Min(glow[i], 1);
                int g = (int)Constrain(v * glyphs.Length, 0, glyphs.Length - 1);
                if (g == 0 && hot < 0.25f)
                    continue;
                if (g == 0) g = 1;
                // Violet to pink across the screen; where it's learning, it warms up
                // through red to amber (400 = 40 degrees, one turn later).
                float hue = 245 + c * 0.8f + 12 * Sin(t * 0.5f + r * 0.15f);
                FillHSB(Lerp(hue, 400, hot * 0.85f) % 360, 65 - 20 * hot, 28 + 72 * Max(v, hot));
                Text(glyphs[g].ToString(), left + (c + 0.5f) * CellW, (r + 0.5f) * CellH);
            }

        DrawHud();
    }

    /// <summary>One lesson: a batch of random pixels of the word -- guess, compare, nudge every weight.</summary>
    void Train()
    {
        brain.BeginBatch();
        float sum = 0;
        for (int b = 0; b < BatchSize; b++)
        {
            int px = rng.Next(tw), py = rng.Next(th);
            sum += brain.Practice((px + 0.5f) / tw, (py + 0.5f) / th, target[py * tw + px]);
        }
        brain.EndBatch(BatchSize);
        Steps++;
        Loss = Lerp(Loss, sum / BatchSize, 0.05f);
        if (Steps % 8 == 0)
            lossHistory[lossCount++ % lossHistory.Length] = Loss;
    }

    void DrawHud()
    {
        float top = Rows * CellH + 20;
        NoStroke();
        Fill(255, 255, 255, 10);
        Rect(0, top - 10, Width, Height - top + 10);

        TextFont(mono, 15);
        TextAlign(TextAlignH.Left, TextAlignV.Top);
        Fill(235, 225, 255);
        Text(word + (FrameCount / 30 % 2 == 0 ? "_" : ""), 28, top + 4);
        Fill(140, 145, 180);
        Text($"network {Brain.Inputs} → {Brain.Hidden} → {Brain.Hidden} → 1 · {brain.WeightCount:N0} weights · lesson {Steps:N0} · error {Loss:0.0000}{(paused ? " · paused" : "")}", 28, top + 28);
        Fill(95, 100, 135);
        Text("type: new word · Enter: forget · mouse: bend · wheel: zoom · Tab: glyphs · Space: pause", 28, top + 52);

        // The error, lesson after lesson: it falls as the network learns.
        float gx = Width - 210, gy = top + 4, gw = 180, gh = 62;
        NoFill();
        Stroke(255, 255, 255, 30);
        StrokeWeight(1);
        Rect(gx, gy, gw, gh);
        Stroke(255, 170, 110);
        StrokeWeight(1.5f);
        BeginShape();
        int n = Min(lossCount, lossHistory.Length);
        for (int k = 0; k < n; k++)
        {
            float v = lossHistory[(lossCount - n + k) % lossHistory.Length];
            Vertex(gx + gw * k / (lossHistory.Length - 1f), gy + gh - Constrain(Sqrt(v / 0.12f), 0, 1) * (gh - 4) - 2);
        }
        EndShape();
        NoStroke();
    }

    public override void KeyTyped()
    {
        if (Key == BACKSPACE)
        {
            if (word.Length > 0) Learn(word[..^1]);
        }
        else if (Key == ENTER || Key == RETURN)
        {
            brain = new Brain(rng);
            Steps = 0;
            lossCount = 0;
        }
        else if (Key == TAB)
            glyphSet = (glyphSet + 1) % glyphSets.Length;
        else if (Key == ' ')
            paused = !paused;
        else if (!char.IsControl(Key) && word.Length < 10)
            Learn(word + Key);
    }

    public override void MouseWheel(float delta) => zoom = Constrain(zoom * (delta > 0 ? 1.2f : 1 / 1.2f), 0.6f, 8);

    static void Blur(float[] img, int w, int h, int radius)
    {
        var tmp = new float[img.Length];
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                float s = 0; int n = 0;
                for (int k = -radius; k <= radius; k++)
                    if (x + k >= 0 && x + k < w) { s += img[y * w + x + k]; n++; }
                tmp[y * w + x] = s / n;
            }
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                float s = 0; int n = 0;
                for (int k = -radius; k <= radius; k++)
                    if (y + k >= 0 && y + k < h) { s += tmp[(y + k) * w + x]; n++; }
                img[y * w + x] = s / n;
            }
    }

    /// <summary>
    /// The whole "AI": a small multilayer perceptron, (x, y) -> ink.
    /// The point first becomes 32 sine waves of random directions and sizes
    /// ("Fourier features": a plain network is bad at sharp edges, waves give
    /// it something to build them with). Then two layers of 24 neurons (tanh)
    /// and one output (sigmoid, 0..1). Learns by backpropagation, with Adam.
    /// </summary>
    public class Brain
    {
        public const int Waves = 32, Inputs = Waves * 2, Hidden = 24;
        readonly float[] waveX = new float[Waves], waveY = new float[Waves];
        readonly float[] w1 = new float[Inputs * Hidden], b1 = new float[Hidden];   // w1[j * Inputs + i]: input i -> neuron j
        readonly float[] w2 = new float[Hidden * Hidden], b2 = new float[Hidden];
        readonly float[] w3 = new float[Hidden];
        float b3;
        readonly float[] input = new float[Inputs], h1 = new float[Hidden], h2 = new float[Hidden], d2 = new float[Hidden];
        // Gradients and Adam's memory, for all the weights in one row: w1 b1 w2 b2 w3 b3.
        readonly float[] grad, m, v;
        int lessons;

        public int WeightCount => grad.Length;

        public Brain(System.Random rng)
        {
            float Gauss() => (float)(System.Math.Sqrt(-2 * System.Math.Log(1 - rng.NextDouble())) * System.Math.Cos(2 * System.Math.PI * rng.NextDouble()));
            // Mostly gentle waves, some fast ones (letters are wide but their edges are sharp).
            // y is squeezed: on screen 1.0 of height is 0.56 of the width.
            for (int k = 0; k < Waves; k++) { waveX[k] = Gauss() * 10; waveY[k] = Gauss() * 10 * 0.5625f; }
            for (int k = 0; k < w1.Length; k++) w1[k] = Gauss() / MathF.Sqrt(Inputs);
            for (int k = 0; k < w2.Length; k++) w2[k] = Gauss() / MathF.Sqrt(Hidden);
            for (int k = 0; k < w3.Length; k++) w3[k] = Gauss() / MathF.Sqrt(Hidden);
            int n = w1.Length + Hidden + w2.Length + Hidden + Hidden + 1;
            grad = new float[n]; m = new float[n]; v = new float[n];
        }

        float Forward(float x, float y)
        {
            x = x * 2 - 1; y = y * 2 - 1;
            for (int k = 0; k < Waves; k++)
            {
                float a = waveX[k] * x + waveY[k] * y;
                input[2 * k] = MathF.Sin(a);
                input[2 * k + 1] = MathF.Cos(a);
            }
            for (int j = 0; j < Hidden; j++)
            {
                float s = b1[j];
                int row = j * Inputs;
                for (int i = 0; i < Inputs; i++) s += w1[row + i] * input[i];
                h1[j] = MathF.Tanh(s);
            }
            for (int j = 0; j < Hidden; j++)
            {
                float s = b2[j];
                int row = j * Hidden;
                for (int i = 0; i < Hidden; i++) s += w2[row + i] * h1[i];
                h2[j] = MathF.Tanh(s);
            }
            float o = b3;
            for (int i = 0; i < Hidden; i++) o += w3[i] * h2[i];
            return 1 / (1 + MathF.Exp(-o));
        }

        /// <summary>How much ink the network thinks is at (x, y), both 0..1 across the screen.</summary>
        public float Think(float x, float y) => Forward(x, y);

        public void BeginBatch() => System.Array.Clear(grad);

        /// <summary>Guesses one point, adds to every weight's gradient how it should move, returns the squared error.</summary>
        public float Practice(float x, float y, float want)
        {
            float got = Forward(x, y);
            float err = got - want;
            float dOut = err * got * (1 - got);          // through the sigmoid
            int gw1 = 0, gb1 = w1.Length, gw2 = gb1 + Hidden, gb2 = gw2 + w2.Length, gw3 = gb2 + Hidden, gb3 = gw3 + Hidden;
            grad[gb3] += dOut;
            for (int j = 0; j < Hidden; j++)
            {
                grad[gw3 + j] += dOut * h2[j];
                d2[j] = dOut * w3[j] * (1 - h2[j] * h2[j]);
            }
            for (int j = 0; j < Hidden; j++)
            {
                float d = d2[j];
                grad[gb2 + j] += d;
                int row = j * Hidden;
                for (int i = 0; i < Hidden; i++) grad[gw2 + row + i] += d * h1[i];
            }
            for (int i = 0; i < Hidden; i++)
            {
                float s = 0;
                for (int j = 0; j < Hidden; j++) s += d2[j] * w2[j * Hidden + i];
                float d = s * (1 - h1[i] * h1[i]);
                grad[gb1 + i] += d;
                int row = i * Inputs;
                for (int k = 0; k < Inputs; k++) grad[gw1 + row + k] += d * input[k];
            }
            return err * err;
        }

        /// <summary>Adam: every weight steps against its average gradient, scaled by how noisy that gradient has been.</summary>
        public void EndBatch(int batchSize, float rate = 0.003f)
        {
            lessons++;
            float c1 = 1 - MathF.Pow(0.9f, lessons), c2 = 1 - MathF.Pow(0.999f, lessons);
            int at = 0;
            Step(w1); Step(b1); Step(w2); Step(b2); Step(w3);
            float[] last = { b3 };
            Step(last);
            b3 = last[0];

            void Step(float[] weights)
            {
                for (int i = 0; i < weights.Length; i++, at++)
                {
                    float g = grad[at] / batchSize;
                    m[at] = 0.9f * m[at] + 0.1f * g;
                    v[at] = 0.999f * v[at] + 0.001f * g * g;
                    weights[i] -= rate * (m[at] / c1) / (MathF.Sqrt(v[at] / c2) + 1e-7f);
                }
            }
        }
    }
}

// A disco in 3D, built only from ASCII characters, and you start INSIDE the dancer.
//
// Every character has its own X, Y and Z:
// - the dancer is a statue of glyphs, 20 units tall, standing in the middle of
//   the room. Its body is thicker than its arms (more layers in Z), so from the
//   side you see it has volume;
// - the floor is a grid of glyph tiles on the ground; the lit ones rise up with
//   the kick, and a ripple runs out from the dancer's feet;
// - two spotlights are beams of dots hanging in the air, a mirror ball of glyphs
//   turns above, and dust floats everywhere at every height.
// The camera starts inside the statue's chest -- just glyphs all around -- looks
// around, walks out, and only when it backs away do you see what you were in.
// Then it circles the dancer and dives back in.
//
// Everything is DanaProcessing and code:
// - the dancer is drawn each frame on an offscreen PGraphics (lines and circles
//   posed from Beat()), plus a second one in grays that says how thick each part is;
// - the 3D is a tiny camera in plain math: every glyph is projected, sorted far
//   to near and drawn with Text() at the size its distance gives it;
// - the music is five [LiveLoop]s (pad, bass, lead, drums, hats) at 116 BPM,
//   32 bars that loop; the camera path is timed in beats of that song.
//
// Space: freeze the camera (the music goes on).  H: hide the labels.
public class AsciiDisco : Sketch
{
    // ---- the dancer: pictures -> statue -------------------------------------------------
    const int GW = 96, GH = 54;                 // statue cells across and up (from 2x2 pixels each)
    const int PicW = GW * 2, PicH = GH * 2;
    const float Cell = 0.42f;                   // world size of one statue cell
    const string Glyphs = " .:-=+*#%@";
    PGraphics pic, thick;
    readonly float[] lum = new float[GW * GH], body = new float[GW * GH];
    readonly Color[] tint = new Color[GW * GH];

    // ---- the room ----------------------------------------------------------------------
    const int FloorW = 64, FloorD = 44;         // floor glyphs, 1 unit apart
    const float FloorZ = 4;                     // the floor's center is a bit behind the dancer
    readonly PVector[] dust = new PVector[260];
    readonly PVector[] ball = new PVector[150];
    static readonly PVector BallAt = new PVector(0, 27, 6);

    // ---- what gets drawn this frame: one entry per glyph ------------------------------
    const int MaxItems = 16000;
    readonly float[] ix = new float[MaxItems], iy = new float[MaxItems], iz = new float[MaxItems];
    readonly int[] icolor = new int[MaxItems];  // packed RGB
    readonly float[] ialpha = new float[MaxItems];
    readonly char[] iglyph = new char[MaxItems];
    readonly float[] depth = new float[MaxItems], sx = new float[MaxItems], sy = new float[MaxItems], ss = new float[MaxItems];
    readonly int[] order = new int[MaxItems];
    int items;
    PFont mono;

    // ---- the camera -----------------------------------------------------------------------
    const float FovY = 60;
    const int SongBeats = 128;                  // 32 bars, then it all loops
    float frozenFor;                            // beats the camera spent frozen
    bool frozen, labels = true;
    double lastBeat;

    // Where the camera is and what it looks at, at a beat of the song (Catmull-Rom through
    // these: smooth, no stops). The dancer stands at x = 0, z = 0, facing -z, chest at y = 9.
    static readonly (float Beat, PVector Pos, PVector Look)[] Path =
    {
        (0,   new PVector(0, 9.5f, 0.2f),    new PVector(0, 9.5f, 10)),    // inside the chest
        (12,  new PVector(0.5f, 9.5f, 0.2f), new PVector(10, 8, 2)),       // look around in there
        (22,  new PVector(0, 7, -1.5f),      new PVector(-4, 14, 6)),      // ...and up
        (32,  new PVector(-5, 4, -9),        new PVector(0, 9, 0)),        // step out, still too close to tell
        (44,  new PVector(6, 4, -20),        new PVector(0, 9, 0)),        // backing away
        (56,  new PVector(0, 8, -34),        new PVector(0, 9.5f, 0)),     // there it is
        (72,  new PVector(-24, 11, -24),     new PVector(0, 9, 0)),        // around to its side: it has depth
        (88,  new PVector(-30, 18, 8),       new PVector(0, 8, 2)),
        (100, new PVector(14, 24, -30),      new PVector(0, 8, 0)),        // up high, the whole room
        (112, new PVector(1, 10.5f, -15),    new PVector(0, 9.5f, 0)),     // and straight back in, through the chest
        (122, new PVector(0, 9.5f, -2.5f),   new PVector(0, 9.5f, 8)),
        (128, new PVector(0, 9.5f, 0.2f),    new PVector(0, 9.5f, 10)),    // = beat 0: the loop closes
    };

    // ---- the song ---------------------------------------------------------------------------
    double musicStart = -1;
    bool heardMusic;
    int padBar, bassBar, leadBar, drumBar, hatBar;

    static readonly string[][] Chords =
    {
        new[] { "F3", "A3", "C4", "E4" },   // Fmaj7
        new[] { "E3", "G3", "B3", "D4" },   // Em7
        new[] { "D3", "F3", "A3", "C4" },   // Dm7
        new[] { "C3", "E3", "G3", "B3" },   // Cmaj7
    };
    static readonly string[] Roots = { "F2", "E2", "D2", "C2" };

    // Sections, in bars of the 32-bar song.
    static bool Drums(int bar) => bar >= 4 && bar < 28;
    static bool Full(int bar) => bar >= 12 && bar < 28;
    static bool Lead(int bar) => bar >= 16 && bar < 28;

    public override void Setup()
    {
        Size(960, 540);
        Bpm = 116;
        mono = CreateFont("Consolas", 32);
        pic = CreateGraphics(PicW, PicH);
        thick = CreateGraphics(PicW, PicH);
        for (int k = 0; k < dust.Length; k++)
            dust[k] = new PVector((Hash(k) - 0.5f) * 60, 1 + Hash(k + 500) * 26, (Hash(k + 900) - 0.5f) * 44 + FloorZ);
        // The mirror ball: points spread evenly over a sphere (a Fibonacci spiral).
        for (int k = 0; k < ball.Length; k++)
        {
            float y = 1 - 2 * (k + 0.5f) / ball.Length, r = Sqrt(1 - y * y), a = k * 2.39996f;
            ball[k] = new PVector(Cos(a) * r, y, Sin(a) * r);
        }
    }

    public override void OnNote(NoteEvent e) => heardMusic = true;

    /// <summary>Beats since the song started (the loops wait for the next bar to start; no sound at all: since Run).</summary>
    double SongBeat()
    {
        double b = Beat();
        if (heardMusic && musicStart < 0)
            musicStart = Math.Floor(b / 4 + 1e-6) * 4;
        if (musicStart < 0)
            return Millis() > 2500 ? b : 0;
        return Math.Max(0, b - musicStart);
    }

    public override void Draw()
    {
        double song = SongBeat();
        if (frozen) frozenFor += (float)(song - lastBeat);
        lastBeat = song;
        float beat = (float)song;
        int bar = (int)(beat / 4) % 32;
        float kick = Drums(bar) ? Pulse(1, 5) : 0;

        items = 0;
        PoseDancer(beat);
        AddStatue(kick);
        AddFloor(beat, bar, kick);
        AddBeams(beat, kick);
        AddBall(beat, kick);
        AddDust(beat);

        Background(6, 4, 14);
        Render((float)(song - frozenFor));
        if (labels) DrawLabels(song);
    }

    // =========================================================================================
    // The dancer: drawn flat, twice (its colors, and how thick each part is), then stood up.
    // =========================================================================================
    void PoseDancer(float beat)
    {
        float step = Sin(beat * PI);                    // a side step every beat
        float bounce = Abs(Sin(beat * PI)) * 3;
        float hipX = step * 5, hipY = -26 + bounce;
        float neckX = hipX - step * 2, neckY = hipY - 26;
        int move = (int)(beat / 8) % 4;
        float ph = beat * PI;

        // Arms: (shoulder angle, elbow angle) per side; radians, 0 = pointing right, up = -PI/2.
        (float s, float e) left, right;
        switch (move)
        {
            case 0:  // pump: fists go up one at a time
                left = (-PI * 0.75f - Max(0, Sin(ph)) * 0.9f, -PI * 0.5f);
                right = (-PI * 0.25f - Max(0, -Sin(ph)) * 0.9f, -PI * 0.5f);
                break;
            case 1:  // point: one arm up to the corner, then down across
                bool up = Sin(ph / 2) > 0;
                right = up ? (-PI * 0.3f, -PI * 0.35f) : (PI * 0.25f, PI * 0.35f);
                left = (PI * 0.7f, PI * 0.6f);
                break;
            case 2:  // wave: both arms up, swaying
                left = (-PI * 0.62f + Sin(ph) * 0.25f, -PI * 0.55f + Sin(ph) * 0.3f);
                right = (-PI * 0.38f + Sin(ph) * 0.25f, -PI * 0.45f + Sin(ph) * 0.3f);
                break;
            default: // roll: forearms circling in front of the chest
                left = (PI * 0.85f, -PI * 0.1f + Sin(ph * 2) * 0.8f);
                right = (PI * 0.15f, PI * 1.1f + Cos(ph * 2) * 0.8f);
                break;
        }

        // Same figure on both canvases: `pic` in color, `thick` in grays (white = thickest).
        foreach (var g in new[] { pic, thick })
        {
            bool colors = g == pic;
            g.BeginDraw();
            g.Background(0);
            g.PushMatrix();
            g.Translate(PicW / 2f, PicH - 2);
            g.Scale(1.4f);
            g.StrokeCap(StrokeCapKind.Round);
            // Legs: knees bend in turn.
            if (colors) g.Stroke(90, 200, 255); else g.Stroke(150);
            g.StrokeWeight(5);
            for (int side = -1; side <= 1; side += 2)
            {
                float bend = Max(0, side * step) * 6;
                float kneeX = hipX + side * 6 + side * bend * 0.4f, kneeY = hipY + 12 - bend * 0.3f;
                g.Line(hipX + side * 3, hipY, kneeX, kneeY);
                g.Line(kneeX, kneeY, hipX + side * 9, -1);
            }
            // Body.
            if (colors) g.Stroke(255, 120, 190); else g.Stroke(255);
            g.StrokeWeight(9);
            g.Line(hipX, hipY - 2, neckX, neckY + 4);
            // Arms.
            if (colors) g.Stroke(255, 200, 150); else g.Stroke(110);
            g.StrokeWeight(4);
            Arm(g, neckX - 4, neckY + 3, left);
            Arm(g, neckX + 4, neckY + 3, right);
            // Head, with shades.
            g.NoStroke();
            if (colors) g.Fill(255, 215, 170); else g.Fill(220);
            g.Circle(neckX, neckY - 6, 13);
            if (colors) { g.Fill(40, 230, 255); g.Rect(neckX - 6, neckY - 8, 12, 3); }
            g.PopMatrix();
            g.LoadPixels();
            var px = g.Pixels;
            for (int r = 0; r < GH; r++)
                for (int c = 0; c < GW; c++)
                {
                    int R = 0, G = 0, B = 0;
                    for (int dy = 0; dy < 2; dy++)
                        for (int dx = 0; dx < 2; dx++)
                        {
                            var p = px[(r * 2 + dy) * PicW + c * 2 + dx];
                            R += p.R; G += p.G; B += p.B;
                        }
                    int i = r * GW + c;
                    if (colors)
                    {
                        lum[i] = (0.3f * R + 0.55f * G + 0.15f * B) / (4 * 255f);
                        tint[i] = Color(R / 4, G / 4, B / 4);
                    }
                    else
                        body[i] = R / (4 * 255f);
                }
            g.EndDraw();
        }
        // Blurred, the thickness is greatest along the middle of each limb and fades
        // towards its edges: so the statue comes out rounded, not cut from a flat sheet.
        // (A small box blur by hand, on the 96 x 54 grid: much cheaper than Filter(Blur).)
        BoxBlur(body, GW, GH);
        BoxBlur(body, GW, GH);
    }

    readonly float[] blurTmp = new float[GW * GH];

    void BoxBlur(float[] a, int w, int h)
    {
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                float s = 0; int n = 0;
                for (int k = -1; k <= 1; k++)
                    if (x + k >= 0 && x + k < w) { s += a[y * w + x + k]; n++; }
                blurTmp[y * w + x] = s / n;
            }
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                float s = 0; int n = 0;
                for (int k = -1; k <= 1; k++)
                    if (y + k >= 0 && y + k < h) { s += blurTmp[(y + k) * w + x]; n++; }
                a[y * w + x] = s / n;
            }
    }

    static void Arm(PGraphics g, float x, float y, (float s, float e) a)
    {
        const float upper = 11, fore = 10;
        float ex = x + MathF.Cos(a.s) * upper, ey = y + MathF.Sin(a.s) * upper;
        g.Line(x, y, ex, ey);
        g.Line(ex, ey, ex + MathF.Cos(a.e) * fore, ey + MathF.Sin(a.e) * fore);
    }

    /// <summary>Every cell the dancer covers becomes a short row of glyphs in Z: 1 to 5 deep.</summary>
    void AddStatue(float kick)
    {
        for (int r = 0; r < GH; r++)
            for (int c = 0; c < GW; c++)
            {
                int i = r * GW + c;
                float v = lum[i];
                if (v < 0.08f) continue;
                float x = (GW / 2f - c - 0.5f) * Cell;                  // mirrored: it faces the camera at -z
                float y = (GH - r - 0.5f) * Cell;
                int layers = 1 + (int)MathF.Round(body[i] * 9);         // up to 10 deep in the torso, 2-4 in the arms
                var col = tint[i];
                float glow = 1.15f + 0.4f * kick;
                int rgb = Pack(col.R * glow + 20, col.G * glow + 15, col.B * glow + 25);
                int g = (int)Constrain(Sqrt(v) * Glyphs.Length, 2, Glyphs.Length - 1);
                for (int k = 0; k < layers; k++)
                {
                    float z = (k - (layers - 1) / 2f) * Cell * 1.1f;
                    bool face = k == 0 || k == layers - 1;
                    // The surfaces get the dense glyphs, the inside lighter ones.
                    Add(x, y, z, face ? Glyphs[g] : Glyphs[Math.Max(2, g - 3)], rgb, face ? 1 : 0.55f);
                }
            }
    }

    /// <summary>The dance floor: tiles of glyphs; lit tiles rise with the kick, a ripple runs from the feet.</summary>
    void AddFloor(float beat, int bar, float kick)
    {
        for (int fz = 0; fz < FloorD; fz++)
            for (int fx = 0; fx < FloorW; fx++)
            {
                float x = fx - FloorW / 2f + 0.5f, z = fz - FloorD / 2f + 0.5f + FloorZ;
                int tx = (int)Math.Floor(x / 5), tz = (int)Math.Floor(z / 5);
                bool lit = Drums(bar) && (((tx + tz + (int)beat) % 3 + 3) % 3 == 0);
                bool edge = ((fx + 1000) % 5 == 0) || ((fz + 1000) % 5 == 0);
                float dist = Sqrt(x * x + z * z);
                float ripple = Max(0, Sin(dist * 0.45f - beat * PI)) * (0.15f + 0.5f * kick) * Exp(-dist * 0.04f);
                if (lit)
                {
                    float hue = ((bar * 47 + tx * 20 + tz * 60) % 360 + 360) % 360;
                    var c = HsbRgb(hue, 75, 100);
                    float h = 0.2f + 1.4f * kick + ripple;
                    Add(x, h, z, edge ? '=' : '#', c, 0.95f);
                    if (h > 0.8f) Add(x, h - 0.7f, z, '+', c, 0.5f);           // lit tiles are blocks, not decals
                }
                else
                    Add(x, ripple, z, edge ? '-' : '.', Pack(70, 55, 120), edge ? 0.6f : 0.35f);
            }
    }

    /// <summary>Two spotlights: dotted beams from the ceiling, sweeping across the floor.</summary>
    void AddBeams(float beat, float kick)
    {
        for (int s = 0; s < 2; s++)
        {
            var from = new PVector(s == 0 ? -22 : 22, 30, 14);
            float a = beat * PI / 8 + s * PI;
            var to = new PVector(Sin(a) * 14, 0, Cos(a * 0.7f) * 9 + 2);
            int rgb = s == 0 ? Pack(255, 110, 210) : Pack(120, 210, 255);
            for (int k = 0; k < 46; k++)
            {
                float t = k / 45f;
                // A cone: the beam widens towards the floor.
                float spread = t * 2.2f, ang = k * 2.39996f;
                Add(Lerp(from.X, to.X, t) + Cos(ang) * spread, Lerp(from.Y, to.Y, t), Lerp(from.Z, to.Z, t) + Sin(ang) * spread,
                    k % 3 == 0 ? ':' : '.', rgb, 0.25f + 0.35f * kick);
            }
        }
    }

    /// <summary>The mirror ball: a sphere of glyphs turning, its facets catching the light.</summary>
    void AddBall(float beat, float kick)
    {
        float spin = beat * 0.4f, cs = Cos(spin), sn = Sin(spin);
        for (int k = 0; k < ball.Length; k++)
        {
            var p = ball[k];
            float x = p.X * cs - p.Z * sn, z = p.X * sn + p.Z * cs;
            bool flash = Hash(k + (int)(beat * 4) * 131) > 0.9f;
            Add(BallAt.X + x * 2.4f, BallAt.Y + p.Y * 2.4f, BallAt.Z + z * 2.4f, flash ? '@' : '#',
                flash ? Pack(255, 255, 255) : Pack(170, 175, 200), flash ? 1 : 0.7f);
        }
    }

    /// <summary>Dust in the air, at every height, drifting round the dancer.</summary>
    void AddDust(float beat)
    {
        float turn = beat * 0.03f;
        for (int k = 0; k < dust.Length; k++)
        {
            var p = dust[k];
            float a = turn * (0.5f + Hash(k + 77));
            float x = p.X * Cos(a) - (p.Z - FloorZ) * Sin(a), z = p.X * Sin(a) + (p.Z - FloorZ) * Cos(a) + FloorZ;
            float y = p.Y + Sin(beat * 0.5f + k) * 0.6f;
            Add(x, y, z, k % 7 == 0 ? '*' : k % 3 == 0 ? '+' : '.', HsbRgb((k * 37) % 360, 35, 100), 0.55f);
        }
    }

    void Add(float x, float y, float z, char glyph, int rgb, float alpha)
    {
        if (items >= MaxItems) return;
        ix[items] = x; iy[items] = y; iz[items] = z;
        iglyph[items] = glyph; icolor[items] = rgb; ialpha[items] = alpha;
        items++;
    }

    static int Pack(float r, float g, float b) =>
        ((int)Math.Clamp(r, 0, 255) << 16) | ((int)Math.Clamp(g, 0, 255) << 8) | (int)Math.Clamp(b, 0, 255);

    static int HsbRgb(float h, float s, float v)
    {
        s /= 100; v /= 100;
        float c = v * s, hp = h / 60 % 6, x = c * (1 - MathF.Abs(hp % 2 - 1)), m = v - c;
        (float r, float g, float b) = hp < 1 ? (c, x, 0f) : hp < 2 ? (x, c, 0f) : hp < 3 ? (0f, c, x) : hp < 4 ? (0f, x, c) : hp < 5 ? (x, 0f, c) : (c, 0f, x);
        return Pack((r + m) * 255, (g + m) * 255, (b + m) * 255);
    }

    static float Hash(int n)
    {
        unchecked
        {
            uint x = (uint)n;
            x ^= x >> 16; x *= 0x7feb352d; x ^= x >> 15; x *= 0x846ca68b; x ^= x >> 16;
            return (x & 0xFFFFFF) / 16777215f;
        }
    }

    // =========================================================================================
    // The camera: project every glyph, sort far to near, draw.
    // =========================================================================================
    void Render(float camBeat)
    {
        var (eye, look) = CameraAt(camBeat);
        var f = PVector.Sub(look, eye).Normalize();
        var r = f.Cross(new PVector(0, 1, 0)).Normalize();
        var u = r.Cross(f);
        float focal = Height / 2f / Tan(Radians(FovY) / 2);

        int n = 0;
        for (int k = 0; k < items; k++)
        {
            float dx = ix[k] - eye.X, dy = iy[k] - eye.Y, dz = iz[k] - eye.Z;
            float zc = dx * f.X + dy * f.Y + dz * f.Z;
            if (zc < 0.3f) continue;                                  // behind us, or in our face
            float xc = dx * r.X + dy * r.Y + dz * r.Z;
            float yc = dx * u.X + dy * u.Y + dz * u.Z;
            float size = focal * 0.6f / zc;
            float x = Width / 2f + focal * xc / zc, y = Height / 2f - focal * yc / zc;
            if (size < 2.5f || x < -size || x > Width + size || y < -size || y > Height + size) continue;
            sx[k] = x; sy[k] = y; ss[k] = Min(size, 120);
            depth[n] = -zc;                                           // far first
            order[n] = k;
            n++;
        }
        System.Array.Sort(depth, order, 0, n);

        TextFont(mono, 32);
        TextAlign(TextAlignH.Center, TextAlignV.Center);
        for (int q = 0; q < n; q++)
        {
            int k = order[q];
            float z = -depth[q];
            // Close glyphs fade in (no wall of characters on the lens); far ones fade into the dark.
            float alpha = 255 * ialpha[k] * Constrain((z - 0.3f) / 2f, 0, 1) * Constrain(1.25f - z / 90, 0.35f, 1);
            int c = icolor[k];
            Fill((c >> 16) & 255, (c >> 8) & 255, c & 255, alpha);
            // Whole-pixel sizes (steps of 6 when big): Skia caches each glyph per
            // size, so a few sizes draw ~5x faster than thousands of slightly different ones.
            TextSize(ss[k] < 24 ? MathF.Round(ss[k]) : MathF.Round(ss[k] / 6) * 6);
            Text(iglyph[k].ToString(), sx[k], sy[k]);
        }
    }

    (PVector Eye, PVector Look) CameraAt(float beat)
    {
        float b = ((beat % SongBeats) + SongBeats) % SongBeats;
        int k = 0;
        while (k < Path.Length - 2 && Path[k + 1].Beat <= b) k++;
        float t = (b - Path[k].Beat) / (Path[k + 1].Beat - Path[k].Beat);
        int k0 = Math.Max(0, k - 1), k3 = Math.Min(Path.Length - 1, k + 2);
        var eye = CatmullRom(Path[k0].Pos, Path[k].Pos, Path[k + 1].Pos, Path[k3].Pos, t);
        var look = CatmullRom(Path[k0].Look, Path[k].Look, Path[k + 1].Look, Path[k3].Look, t);
        return (eye, look);
    }

    static PVector CatmullRom(PVector p0, PVector p1, PVector p2, PVector p3, float t)
    {
        float t2 = t * t, t3 = t2 * t;
        float F(float a, float b, float c, float d) =>
            0.5f * (2 * b + (-a + c) * t + (2 * a - 5 * b + 4 * c - d) * t2 + (-a + 3 * b - 3 * c + d) * t3);
        return new PVector(F(p0.X, p1.X, p2.X, p3.X), F(p0.Y, p1.Y, p2.Y, p3.Y), F(p0.Z, p1.Z, p2.Z, p3.Z));
    }

    void DrawLabels(double song)
    {
        int bar = (int)(song / 4) % 32;
        string part = bar < 4 ? "intro" : bar < 12 ? "groove" : bar < 16 ? "build" : bar < 28 ? "chorus" : "breakdown";
        TextFont(mono, 13);
        TextSize(13);
        TextAlign(TextAlignH.Left, TextAlignV.Bottom);
        Fill(255, 255, 255, 110);
        Text($"bar {bar + 1}/32 · {part} · {items:N0} glyphs in 3D{(frozen ? " · camera frozen" : "")}", 16, Height - 30);
        Fill(255, 255, 255, 60);
        Text("Space: freeze camera · H: hide labels", 16, Height - 12);
    }

    public override void KeyPressed()
    {
        if (Key == ' ') frozen = !frozen;
        else if (Key == 'h' || Key == 'H') labels = !labels;
    }

    // ===========================================================================
    // The song: 116 BPM, 32 bars, looping. Fmaj7 - Em7 - Dm7 - Cmaj7.
    // ===========================================================================
    [LiveLoop]
    async Task Pad()
    {
        int bar = padBar++ % 32;
        foreach (var note in Chords[bar % 4])
            Play(note, amp: Full(bar) ? 0.06 : 0.09, attack: 0.4, sustain: 2.6, release: 1.0,
                 cutoff: Full(bar) ? 90 : 80, pan: 0, synth: Synth.Saw);
        await Sleep(4);
    }

    [LiveLoop]
    async Task Bass()
    {
        int bar = bassBar++ % 32;
        double root = Notes.Parse(Roots[bar % 4]);
        for (int i = 0; i < 8; i++)
        {
            // Disco octaves: low, high, low, high...
            if (Drums(bar))
                Play(root + (i % 2 == 1 ? 12 : 0), amp: 0.26, release: 0.22, cutoff: 76, res: 0.3, synth: Synth.Saw);
            else if (i == 0)
                Play(root, amp: 0.18, release: 1.6, cutoff: 64, synth: Synth.Triangle);
            await Sleep(0.5);
        }
    }

    [LiveLoop]
    async Task Lead()
    {
        int bar = leadBar++ % 32;
        // A two-bar hook: the first bar climbs, the second one comes home.
        (string Note, double Beats)[] climb = { ("E5", 0.5), ("G5", 0.5), ("A5", 1), ("G5", 0.5), ("E5", 0.5), ("D5", 1) };
        (string Note, double Beats)[] home = { ("C5", 0.5), ("D5", 0.5), ("E5", 1.5), ("", 0.5), ("G4", 0.5), ("A4", 0.5) };
        var phrase = bar % 2 == 0 ? climb : home;
        // Every fourth bar answers an octave lower, for variety.
        int shift = bar % 8 == 7 ? -12 : 0;
        foreach (var (note, beats) in phrase)
        {
            if (Lead(bar) && note != "")
            {
                double n = Notes.Parse(note) + shift;
                Play(n, amp: 0.10, attack: 0.01, release: beats * 0.45, cutoff: 96, pan: -0.15, synth: Synth.Square);
                Play(n + 12, amp: 0.035, release: beats * 0.6, pan: 0.25, synth: Synth.Triangle);   // a soft octave on top
            }
            await Sleep(beats);
        }
    }

    [LiveLoop]
    async Task Kit()
    {
        int bar = drumBar++ % 32;
        for (int beat = 0; beat < 4; beat++)
        {
            if (Drums(bar))
                Sample("kick", amp: 0.9);
            if (Full(bar) && beat % 2 == 1)
                Sample("snare", amp: 0.55);
            // The build: snare rolls getting faster in the last bar before the chorus.
            if (bar == 15)
            {
                int hits = beat < 2 ? 2 : 4;
                for (int h = 0; h < hits; h++)
                {
                    Sample("snare", amp: 0.25 + 0.1 * beat);
                    await Sleep(1.0 / hits);
                }
                continue;
            }
            await Sleep(1);
        }
    }

    [LiveLoop]
    async Task Hats()
    {
        int bar = hatBar++ % 32;
        for (int i = 0; i < 8; i++)
        {
            if (Drums(bar))
                Sample("hat", amp: i % 2 == 1 ? (Full(bar) ? 0.32 : 0.22) : 0.1, pan: 0.25);
            await Sleep(0.5);
        }
    }
}

// A black hole in ASCII, ray traced in 3D, with a slow cinematic score.
//
// Every character on screen is a ray of light traced backwards from the
// camera. Near the black hole the rays bend: in Schwarzschild's geometry a
// light ray's path obeys  p'' = -1.5 h² p / |p|^5  (h = how much it swings
// around the hole), so we just step that equation. Then, for each ray:
// - it falls in (r < 1, the event horizon): black, no character;
// - it crosses the disk of hot gas around the hole: that glow, brighter on
//   the side spinning towards us (Doppler beaming), hotter near the middle;
// - it escapes: whatever star lies in the direction it ended up going.
// The bending is why you see the disk's far side arching OVER and UNDER the
// shadow: light from behind the hole is bent around it towards you.
//
// The camera drifts in from far away, sinks to the plane of the disk and
// circles it, while an orchestra made of synths plays: strings, cellos, a
// piano figure chasing its own echo, choir, pipe organ, timpani and a clock
// that never stops ticking -- eight [LiveLoop]s, 32 bars at 76 BPM, looping.
// The disk glows brighter as the music grows.
//
// Space: freeze the camera.  H: hide the labels.  Wheel: closer / farther.
public class AsciiBlackHole : Sketch
{
    // ---- the screen -------------------------------------------------------------
    const int Cols = 120, Rows = 36;
    const float CellW = 8, CellH = 15;
    const string Ramp = " .,:;-~=+*xX#%&@$";       // the gas, faint to blazing
    const string StarGlyphs = ".+*";

    PFont mono;
    readonly float[] glow = new float[Cols * Rows];   // 0..1 brightness of each ray
    readonly float[] heat = new float[Cols * Rows];   // 0 = star / cool gas, 1 = hottest gas
    readonly float[] blue = new float[Cols * Rows];   // Doppler: >0 coming at us, <0 going away

    // ---- the physics (units: the event horizon has radius 1) ------------------------
    const float DiskIn = 3, DiskOut = 11;             // the disk, from the innermost stable orbit outward
    float[,] swirl;                                   // the gas texture: [radius bin, angle bin]
    const int SwirlR = 64, SwirlA = 256;

    // ---- the camera ---------------------------------------------------------------------
    double musicStart = -1;
    bool heardMusic, frozen, labels = true;
    float frozenFor, zoomOut = 1;
    double lastBeat;

    public override void Setup()
    {
        Size(960, 540);
        Bpm = 76;
        mono = CreateFont("Consolas", 15);

        // Gas: arcs of brighter and darker gas. Noise sampled around circles, so it wraps
        // seamlessly; the angle is stretched so the clumps come out as long streaks.
        swirl = new float[SwirlR, SwirlA];
        for (int ri = 0; ri < SwirlR; ri++)
            for (int ai = 0; ai < SwirlA; ai++)
            {
                float a = ai * TWO_PI / SwirlA, r = ri / (float)SwirlR;
                float n = Noise(r * 14 + Cos(a) * 1.6f, Sin(a) * 1.6f + r * 3) * 0.7f
                        + Noise(r * 40 + Cos(a) * 4, Sin(a) * 4) * 0.3f;
                swirl[ri, ai] = Constrain((n - 0.3f) * 2.2f, 0, 1);
            }
    }

    public override void OnNote(NoteEvent e) => heardMusic = true;

    double SongBeat()
    {
        double b = Beat();
        if (heardMusic && musicStart < 0)
            musicStart = Math.Floor(b / 4 + 1e-6) * 4;
        if (musicStart < 0)
            return Millis() > 2500 ? b : 0;
        return Math.Max(0, b - musicStart);
    }

    public override void Draw()
    {
        double song = SongBeat();
        if (frozen) frozenFor += (float)(song - lastBeat);
        lastBeat = song;
        float camBeat = (float)song - frozenFor;
        float t = Millis() / 1000f;

        var (eye, look) = Camera(camBeat);
        Trace(eye, look, t, FrameCount % 2);             // half the rows each frame: 30 full pictures a second

        Background(0);
        TextFont(mono, 15);
        TextAlign(TextAlignH.Center, TextAlignV.Center);
        float swell = Swell((float)song);
        for (int r = 0; r < Rows; r++)
            for (int c = 0; c < Cols; c++)
            {
                int i = r * Cols + c;
                float v = glow[i];
                if (v < 0.03f) continue;
                float h = heat[i];
                char glyph;
                if (h <= 0)
                {
                    glyph = StarGlyphs[(int)Constrain(v * StarGlyphs.Length, 0, StarGlyphs.Length - 1)];
                    Fill(190, 205, 255, 255 * Min(1, v * 1.5f + 0.2f));    // a star
                }
                else
                {
                    // Gas: deep red outside, orange, then white-hot inside; the side coming at us bluer-white.
                    float d = blue[i];
                    float red = 255, green = Constrain(70 + 200 * h + 60 * d, 40, 255), bl = Constrain(20 + 230 * h * h + 120 * d, 10, 255);
                    float k = 0.45f + 0.55f * Min(1, v * (1.2f + 0.5f * swell));
                    Fill(red * k, green * k, bl * k);
                    glyph = Ramp[(int)Constrain(Sqrt(v) * Ramp.Length, 1, Ramp.Length - 1)];
                }
                Text(glyph.ToString(), (c + 0.5f) * CellW, (r + 0.5f) * CellH);
            }

        if (labels) Labels(song, eye);
    }

    // =================================================================================
    // Ray tracing
    // =================================================================================
    void Trace(PVector eye, PVector look, float t, int parity)
    {
        var f = PVector.Sub(look, eye).Normalize();
        var right = f.Cross(new PVector(0, 1, 0)).Normalize();
        var up = right.Cross(f);
        float tanHalf = Tan(Radians(50) / 2);
        float aspect = Cols * CellW / (Rows * CellH);

        for (int r = parity; r < Rows; r += 2)
            for (int c = 0; c < Cols; c++)
            {
                float sx = ((c + 0.5f) / Cols * 2 - 1) * tanHalf * aspect;
                float sy = (1 - (r + 0.5f) / Rows * 2) * tanHalf;
                float dx = f.X + right.X * sx + up.X * sy, dy = f.Y + right.Y * sx + up.Y * sy, dz = f.Z + right.Z * sx + up.Z * sy;
                float dl = Sqrt(dx * dx + dy * dy + dz * dz);
                dx /= dl; dy /= dl; dz /= dl;
                Ray(eye.X, eye.Y, eye.Z, dx, dy, dz, t, r * Cols + c);
            }
    }

    void Ray(float px, float py, float pz, float vx, float vy, float vz, float t, int i)
    {
        // h² = |p x v|²: constant along the ray; it sets how hard the hole pulls it sideways.
        float cx = py * vz - pz * vy, cy = pz * vx - px * vz, cz = px * vy - py * vx;
        float h2 = cx * cx + cy * cy + cz * cz;
        float light = 0, hot = 0, shift = 0, seen = 1;  // seen: how much of what's behind still gets through
        float start = Sqrt(px * px + py * py + pz * pz);

        // Far from the hole the ray is a straight line: skip the stepping.
        bool straight = h2 > 22 * 22;
        for (int step = 0; step < (straight ? 1 : 260); step++)
        {
            float r2 = px * px + py * py + pz * pz, rr = Sqrt(r2);
            float dt = straight ? 1e6f : Constrain(0.08f * rr, 0.04f, 1.2f);
            if (straight)
            {
                // Straight line: does it cross the disk plane ahead of us?
                if (vy != 0 && py * vy < 0)
                {
                    float k = -py / vy;
                    Disk(px + vx * k, pz + vz * k, vx, vy, vz, t, ref light, ref hot, ref shift, ref seen);
                }
                break;
            }
            if (rr < 1) { seen = 0; break; }                                  // fell in
            if (rr > start + 2 && px * vx + py * vy + pz * vz > 0) break;       // on its way out

            float a = -1.5f * h2 / (r2 * r2 * rr);
            vx += px * a * dt; vy += py * a * dt; vz += pz * a * dt;
            float nx = px + vx * dt, ny = py + vy * dt, nz = pz + vz * dt;
            if (py * ny < 0)                                                    // crossed the disk plane
            {
                float k = py / (py - ny);
                Disk(px + (nx - px) * k, pz + (nz - pz) * k, vx, vy, vz, t, ref light, ref hot, ref shift, ref seen);
                if (seen < 0.02f) break;
            }
            px = nx; py = ny; pz = nz;
        }

        if (seen > 0.02f)
        {
            // Escaped: a star, if there's one in that direction.
            float vl = Sqrt(vx * vx + vy * vy + vz * vz);
            // The sky is cut in tiny cells (~a third of a character); a few of them hold a star.
            int sx = (int)Math.Floor(vx / vl * 400), sy = (int)Math.Floor(vy / vl * 400), sz = (int)Math.Floor(vz / vl * 400);
            uint hsh = (uint)(sx * 73856093 ^ sy * 19349663 ^ sz * 83492791);
            hsh ^= hsh >> 13; hsh *= 0x5bd1e995; hsh ^= hsh >> 15;
            float s = (hsh & 0xffff) / 65535f;
            if (s > 0.9965f)
                light += seen * (0.25f + (s - 0.9965f) / 0.0035f * 0.75f);
        }
        glow[i] = Min(1, light);
        heat[i] = hot;
        blue[i] = shift;
    }

    /// <summary>A ray going through the disk at (x, 0, z): adds the gas' glow, and the gas hides what's behind it.</summary>
    void Disk(float x, float z, float vx, float vy, float vz, float t, ref float light, ref float hot, ref float shift, ref float seen)
    {
        float r = Sqrt(x * x + z * z);
        if (r < DiskIn || r > DiskOut) return;
        // The gas orbits: inner rings faster (Kepler), so the streaks wind up over time.
        float omega = 0.45f / (r * Sqrt(r));
        float angle = Atan2(z, x) - omega * t * 6;
        int ai = (int)((angle / TWO_PI % 1 + 1) % 1 * SwirlA) % SwirlA;
        int ri = (int)Constrain((r - DiskIn) / (DiskOut - DiskIn) * SwirlR, 0, SwirlR - 1);
        float edge = Smooth(DiskIn, DiskIn + 0.6f, r) * (1 - Smooth(DiskOut - 3, DiskOut, r));
        float temp = Pow(DiskIn / r, 1.6f);                                   // hotter inside
        // Doppler: the orbital velocity (counterclockwise seen from above) against the
        // direction to the camera (-v). Coming at us: brighter and bluer.
        float speed = Sqrt(0.5f / r);
        float tx = -z / r, tz = x / r;
        float vl = Sqrt(vx * vx + vy * vy + vz * vz);
        float towards = -(tx * vx + tz * vz) / vl * speed;                     // -0.4 .. 0.4
        float beam = Pow(1 / Max(0.2f, 1 - towards), 3);
        float gas = edge * (0.35f + 0.65f * swirl[ri, ai]);
        float add = seen * gas * temp * beam * 1.5f;
        light += add;
        if (add > 0.02f && hot == 0) { hot = Constrain(temp * beam * 0.8f, 0.05f, 1); shift = Constrain(towards * 2.5f, -1, 1); }
        seen *= 1 - Constrain(gas * 0.9f, 0, 0.92f);
    }

    static float Smooth(float a, float b, float x)
    {
        float k = Math.Clamp((x - a) / (b - a), 0, 1);
        return k * k * (3 - 2 * k);
    }

    // =================================================================================
    // The camera: one continuous move per pass of the song, ending where it began
    // (same place, standing still), so the loop never jumps.
    // =================================================================================
    (PVector, PVector) Camera(float beat)
    {
        float b = beat % 128;                                       // the 32-bar song
        // In from far away, then a slow creep closer all through the build and the horizon...
        float dist = Lerp(44, 14, Smooth(0, 40, b)) - 4.5f * Smooth(36, 108, b);
        // Tilt above the disk: high at first, almost edge-on by the climax (the classic
        // view, the far side of the disk bent over the top).
        float tilt = Lerp(28, 4, Smooth(4, 40, b));
        // ...and in "after", a long pull back up and out to where it started.
        float leave = Smooth(108, 128, b);
        dist = Lerp(dist, 44, leave) * zoomOut;
        tilt = Lerp(tilt, 28, leave);
        float around = Radians(-20 + beat * 1.4f);                  // an orbit that never stops
        float el = Radians(tilt);
        var eye = new PVector(Cos(around) * Cos(el) * dist, Sin(el) * dist, Sin(around) * Cos(el) * dist);
        return (eye, new PVector(0, 0, 0));
    }

    /// <summary>How loud the orchestra is in this bar, 0..1: the disk glows with it.</summary>
    static float Dynamics(int bar) =>
        bar < 4 ? 0.15f :
        bar < 12 ? 0.4f :
        bar < 16 ? 0.4f + 0.6f * (bar - 11) / 4f :     // the build
        bar < 28 ? 1f :
        0.4f - 0.1f * (bar - 28);                       // after

    float Swell(float beat)
    {
        int bar = (int)(beat / 4) % 32;
        // In the climax the disk also throbs with the timpani's heartbeat.
        return Dynamics(bar) + (bar >= 16 && bar < 28 ? Pulse(4, 4) * 0.5f : 0);
    }

    void Labels(double song, PVector eye)
    {
        int bar = (int)(song / 4) % 32;
        string part = bar < 4 ? "the void" : bar < 12 ? "the pull" : bar < 16 ? "the build" : bar < 28 ? "the horizon" : "after";
        float d = Sqrt(eye.X * eye.X + eye.Y * eye.Y + eye.Z * eye.Z);
        TextFont(mono, 13);
        TextAlign(TextAlignH.Left, TextAlignV.Bottom);
        Fill(255, 255, 255, 100);
        Text($"bar {bar + 1}/32 · {part} · distance {d:0.0} horizon radii{(frozen ? " · camera frozen" : "")}", 14, Height - 26);
        Fill(255, 255, 255, 55);
        Text("Space: freeze camera · wheel: closer/farther · H: hide labels", 14, Height - 9);
    }

    public override void KeyPressed()
    {
        if (Key == ' ') frozen = !frozen;
        else if (Key == 'h' || Key == 'H') labels = !labels;
    }

    public override void MouseWheel(float delta) => zoomOut = Constrain(zoomOut * (delta > 0 ? 1.1f : 1 / 1.1f), 0.6f, 2.5f);

    // =================================================================================
    // The score: 76 BPM, 32 bars in A minor, looping. An orchestra made of synths:
    //   bars 0-3    the void:    a clock, a low drone, a high shimmer
    //   bars 4-11   the pull:    a piano figure (with its echo) and soft strings
    //   bars 12-15  the build:   strings and cellos grow, timpani roll, a rising wind
    //   bars 16-27  the horizon: everything -- organ, choir, timpani like a heartbeat
    //   bars 28-31  after:       one last chord, the piano alone, the clock
    // Each chord lasts two bars: Am F C G | Dm F Esus4 E.
    // =================================================================================
    static readonly string[][] Harmony =
    {
        new[] { "A2", "E3", "A3", "C4", "E4" },     // Am
        new[] { "F2", "C3", "A3", "C4", "F4" },     // F
        new[] { "C3", "G3", "C4", "E4", "G4" },     // C
        new[] { "G2", "D3", "B3", "D4", "G4" },     // G
        new[] { "D3", "A3", "D4", "F4", "A4" },     // Dm
        new[] { "F2", "C3", "A3", "C4", "F4" },     // F
        new[] { "E2", "B2", "E3", "A3", "B3" },     // Esus4: holds its breath...
        new[] { "E2", "B2", "G#3", "B3", "E4" },    // E: ...and leans back home
    };

    static string[] ChordAt(int bar) => Harmony[(bar / 2) % Harmony.Length];

    int clockBar, droneBar, stringBar, celloBar, pianoBar, choirBar, organBar, timpaniBar;

    [LiveLoop]
    async Task Clock()
    {
        int bar = clockBar++ % 32;
        // The tick that never stops; it steps back a little when the orchestra is loud.
        double soft = bar >= 16 && bar < 28 ? 0.6 : 1;
        for (int i = 0; i < 8; i++)
        {
            Sample("hat", amp: (i % 2 == 0 ? 0.20 : 0.08) * soft, rate: 1.6, pan: -0.3);
            await Sleep(0.5);
        }
    }

    [LiveLoop]
    async Task Drone()
    {
        int bar = droneBar++ % 32;
        if (bar % 2 == 0)
        {
            double root = Notes.Parse(ChordAt(bar)[0]) - (bar >= 16 && bar < 28 ? 12 : 0);
            Play(root, amp: bar < 4 ? 0.15 : bar >= 16 && bar < 28 ? 0.26 : 0.2, attack: 2, sustain: 4, release: 3, synth: Synth.Sine);
            if (bar < 4)   // the void: a faint shimmer of high harmonics
                foreach (int up in new[] { 31, 36, 40 })
                    Play(root + up, amp: 0.025, attack: 3, sustain: 2, release: 3, pan: up % 2 == 0 ? 0.5 : -0.5, synth: Synth.Triangle);
        }
        await Sleep(4);
    }

    [LiveLoop]
    async Task Strings()
    {
        int bar = stringBar++ % 32;
        float dyn = Dynamics(bar);
        if (bar >= 4 && bar % 2 == 0 && bar < 30)
        {
            // A section: each note played by two saws a hair out of tune with each other,
            // so they beat slowly against each other like a row of violins. Louder = brighter.
            var chord = ChordAt(bar);
            bool last = bar == 28;                  // the last chord rings out
            for (int k = 1; k < chord.Length; k++)
            {
                double note = Notes.Parse(chord[k]) + 12;
                foreach (double detune in new[] { -0.08, 0.08 })
                    Play(note + detune, amp: 0.012 + 0.05 * dyn, attack: 2, sustain: last ? 8 : 5, release: last ? 6 : 3,
                         cutoff: 72 + 22 * dyn, pan: detune * 4, synth: Synth.Saw);
            }
        }
        await Sleep(4);
    }

    [LiveLoop]
    async Task Cellos()
    {
        int bar = celloBar++ % 32;
        // Half notes that walk under the strings: root, fifth, third, root.
        var chord = ChordAt(bar);
        // chord[0] is the root, chord[1] the fifth, chord[3] the third (an octave down here).
        double[] walk = bar % 2 == 0
            ? new double[] { Notes.Parse(chord[0]), Notes.Parse(chord[1]) }
            : new double[] { Notes.Parse(chord[3]) - 12, Notes.Parse(chord[0]) };
        foreach (double note in walk)
        {
            if (bar >= 8 && bar < 29)
            {
                float dyn = Dynamics(bar);
                Play(note, amp: 0.10 + 0.10 * dyn, attack: 0.25, sustain: 1.4, release: 0.6, cutoff: 66 + 14 * dyn, synth: Synth.Saw);
            }
            await Sleep(2);
        }
    }

    [LiveLoop]
    async Task Piano()
    {
        int bar = pianoBar++ % 32;
        // Eight notes a bar, rising and falling through the chord, and an echo three
        // sixteenths behind on the other side -- the figure seems to chase itself.
        var chord = ChordAt(bar);
        int[] shape = { 2, 3, 4, 3, 2, 4, 3, 4 };
        bool plays = bar >= 4 && bar != 15;      // one bar of silence before the horizon
        double amp = bar >= 16 && bar < 28 ? 0.12 : 0.15;
        for (int s = 0; s < 16; s++)
        {
            if (plays)
            {
                if (s % 2 == 0)
                    Play(Notes.Parse(chord[shape[s / 2]]) + 12, amp: amp, release: 1.2, pan: 0.25, synth: Synth.Pluck);
                if (s >= 3 && (s - 3) % 2 == 0)
                    Play(Notes.Parse(chord[shape[(s - 3) / 2]]) + 12, amp: amp * 0.35, release: 1.0, pan: -0.45, synth: Synth.Pluck);
            }
            await Sleep(0.25);
        }
    }

    [LiveLoop]
    async Task Choir()
    {
        int bar = choirBar++ % 32;
        // High voices on the third and fifth, only at the horizon.
        if (bar >= 16 && bar < 28 && bar % 2 == 0)
        {
            var chord = ChordAt(bar);
            foreach (int k in new[] { 3, 4 })
            {
                double note = Notes.Parse(chord[k]) + 12;
                Play(note, amp: 0.05, attack: 2.5, sustain: 4, release: 2.5, pan: k == 3 ? -0.3 : 0.3, synth: Synth.Triangle);
                Play(note + 0.05, amp: 0.035, attack: 3, sustain: 3.5, release: 2.5, pan: k == 3 ? 0.3 : -0.3, synth: Synth.Sine);
            }
        }
        await Sleep(4);
    }

    [LiveLoop]
    async Task Organ()
    {
        int bar = organBar++ % 32;
        // The pipe organ: squares in octaves, slow to open, at the horizon only.
        if (bar >= 16 && bar < 28 && bar % 2 == 0)
            foreach (var note in ChordAt(bar))
            {
                Play(note, amp: 0.055, attack: 1.2, sustain: 5, release: 2.5, cutoff: 84, synth: Synth.Square);
                Play(Notes.Parse(note) + 12, amp: 0.03, attack: 1.6, sustain: 4.5, release: 2.5, cutoff: 90, synth: Synth.Square);
            }
        // The final chord: everything rings out over A.
        if (bar == 28)
            foreach (var note in Harmony[0])
                Play(note, amp: 0.05, attack: 0.3, sustain: 4, release: 8, cutoff: 80, synth: Synth.Square);
        await Sleep(4);
    }

    [LiveLoop]
    async Task Timpani()
    {
        int bar = timpaniBar++ % 32;
        if (bar >= 12 && bar < 16)
        {
            // The build: a roll that gets faster and louder, with a wind rising under it in the last bar.
            if (bar == 15)
                Play(48, amp: 0.10, attack: 3.8, release: 0.3, cutoff: 96, synth: Synth.Noise);
            int perBeat = bar < 14 ? 2 : bar == 14 ? 4 : 6;
            for (int i = 0; i < 4 * perBeat; i++)
            {
                double grow = (bar - 12 + i / (4.0 * perBeat)) / 4;
                Sample("kick", amp: 0.15 + 0.45 * grow, rate: 0.55);
                await Sleep(1.0 / perBeat);
            }
        }
        else if (bar >= 16 && bar < 28)
        {
            // The horizon: a heartbeat, and a big hit at the start of every chord.
            Sample("kick", amp: bar % 2 == 0 ? 0.9 : 0.6, rate: 0.55);
            await Sleep(0.5);
            Sample("kick", amp: 0.35, rate: 0.6);
            await Sleep(3.5);
        }
        else if (bar == 28)
        {
            Sample("kick", amp: 0.9, rate: 0.5);     // the last chord lands
            await Sleep(4);
        }
        else
            await Sleep(4);
    }
}

// A 3D liquid made of ASCII characters.
//
// About 1,500 particles of "water" in a glass box, simulated with particle-based
// fluid dynamics (the "double density relaxation" method of Clavet, Beaudoin and
// Poulin, 2005 -- the trick behind many game liquids):
//   1. every particle falls and moves on with its velocity;
//   2. it counts how crowded it is (its density, from the neighbours within one
//      unit). Too crowded: it pushes its neighbours away; too sparse: it pulls
//      them in -- that's what makes it a liquid that keeps its volume, with a
//      surface, instead of sand or gas;
//   3. the walls push it back in, and its new velocity is just where it ended
//      up minus where it started.
// Neighbours are found with a grid: each particle only looks at the 27 cells
// around it, so the cost grows with the number of particles, not its square.
//
// Each particle is drawn as one glyph in 3D, sorted far to near: crowded ones
// (deep water) are dense glyphs, lonely fast ones (spray and foam) are dots and
// stars, and the faster it moves the whiter it gets.
//
// Drag the mouse: tilt the box (the water sloshes).  Wheel: zoom.
// Click: kick the water up from below.  1: dam break   2: a ball of water drops into a pool
// 3: two walls of water collide.  Space: pause.  A: auto mode on/off (it rocks by itself and
// splashes every few seconds, until you touch it).
public class AsciiFluid : Sketch
{
    // ---- the box (units: one particle's reach, h = 1) ------------------------------------
    const float BoxX = 14, BoxY = 10, BoxZ = 7;
    const int MaxParticles = 1800;

    // ---- the fluid -----------------------------------------------------------------------
    const float Gravity = 0.010f;          // per step²
    const float Stiffness = 0.08f, NearStiffness = 0.2f;
    const float Viscosity = 0.08f;
    const int Substeps = 2;
    float restDensity = 8;

    int count;
    readonly float[] px = new float[MaxParticles], py = new float[MaxParticles], pz = new float[MaxParticles];
    readonly float[] ox = new float[MaxParticles], oy = new float[MaxParticles], oz = new float[MaxParticles];
    readonly float[] vx = new float[MaxParticles], vy = new float[MaxParticles], vz = new float[MaxParticles];
    readonly float[] density = new float[MaxParticles];

    // The neighbour grid: particles sorted by cell.
    const int CX = (int)BoxX + 1, CY = (int)BoxY + 1, CZ = (int)BoxZ + 1;
    readonly int[] cellOf = new int[MaxParticles], sorted = new int[MaxParticles];
    readonly int[] cellStart = new int[CX * CY * CZ + 1];

    // ---- the view ------------------------------------------------------------------------
    PFont mono;
    float tiltX, tiltZ, autoT, zoom = 1, orbit;
    bool paused, auto = true;
    readonly float[] sx = new float[MaxParticles + 400], sy = new float[MaxParticles + 400], ss = new float[MaxParticles + 400];
    readonly float[] depth = new float[MaxParticles + 400];
    readonly int[] order = new int[MaxParticles + 400];
    int scenario = 1;

    public override void Setup()
    {
        Size(960, 540);
        mono = CreateFont("Consolas", 32);
        Scenario(1);
    }

    // =====================================================================================
    // Scenarios
    // =====================================================================================
    void Scenario(int which)
    {
        scenario = which;
        count = 0;
        const float s = 0.62f;                       // spacing: about 17 neighbours each
        if (which == 1)                              // dam break: a block of water against the left wall
            Block(0.3f, 0.3f, 0.3f, 5.2f, 8.5f, BoxZ - 0.3f, s);
        else if (which == 2)                         // a shallow pool, and a ball of water above it
        {
            Block(0.3f, 0.3f, 0.3f, BoxX - 0.3f, 1.9f, BoxZ - 0.3f, s);
            Ball(BoxX / 2, 7, BoxZ / 2, 2.6f, s);
        }
        else                                         // two walls of water, one at each end
        {
            Block(0.3f, 0.3f, 0.3f, 3.4f, 8.5f, BoxZ - 0.3f, s);
            Block(BoxX - 3.4f, 0.3f, 0.3f, BoxX - 0.3f, 8.5f, BoxZ - 0.3f, s);
        }
        // The rest density is what the starting water already has: so it starts at rest.
        FindNeighbours();
        Densities();
        float sum = 0; int n = 0;
        for (int i = 0; i < count; i++)
            if (density[i] > 0) { sum += density[i]; n++; }
        restDensity = n > 0 ? sum / n * 1.05f : 8;
    }

    void Block(float x0, float y0, float z0, float x1, float y1, float z1, float s)
    {
        for (float y = y0; y < y1; y += s)
            for (float x = x0; x < x1; x += s)
                for (float z = z0; z < z1; z += s)
                    Spawn(x + Jitter(), y + Jitter(), z + Jitter());
    }

    void Ball(float cx, float cy, float cz, float r, float s)
    {
        for (float y = -r; y <= r; y += s)
            for (float x = -r; x <= r; x += s)
                for (float z = -r; z <= r; z += s)
                    if (x * x + y * y + z * z <= r * r)
                        Spawn(cx + x + Jitter(), cy + y + Jitter(), cz + z + Jitter());
    }

    float Jitter() => Random(-0.02f, 0.02f);

    void Spawn(float x, float y, float z)
    {
        if (count >= MaxParticles) return;
        px[count] = x; py[count] = y; pz[count] = z;
        vx[count] = vy[count] = vz[count] = 0;
        count++;
    }

    // =====================================================================================
    // The simulation
    // =====================================================================================
    void Step(float gx, float gy, float gz)
    {
        // 1. Gravity, viscosity (neighbours moving apart or together slow down), move on.
        for (int i = 0; i < count; i++)
        {
            vx[i] += gx; vy[i] += gy; vz[i] += gz;
        }
        Viscous();
        for (int i = 0; i < count; i++)
        {
            ox[i] = px[i]; oy[i] = py[i]; oz[i] = pz[i];
            px[i] += vx[i]; py[i] += vy[i]; pz[i] += vz[i];
        }

        // 2. Push apart where it's too crowded, pull together where it's too sparse.
        FindNeighbours();
        Relax();

        // 3. Walls, then the velocity is simply how far it actually went.
        for (int i = 0; i < count; i++)
        {
            px[i] = Math.Clamp(px[i], 0.05f, BoxX - 0.05f);
            py[i] = Math.Clamp(py[i], 0.05f, BoxY - 0.05f);
            pz[i] = Math.Clamp(pz[i], 0.05f, BoxZ - 0.05f);
            vx[i] = px[i] - ox[i]; vy[i] = py[i] - oy[i]; vz[i] = pz[i] - oz[i];
        }
    }

    void FindNeighbours()
    {
        System.Array.Clear(cellStart);
        for (int i = 0; i < count; i++)
        {
            int c = Cell(px[i], py[i], pz[i]);
            cellOf[i] = c;
            cellStart[c + 1]++;
        }
        for (int c = 0; c < CX * CY * CZ; c++) cellStart[c + 1] += cellStart[c];
        var fill = new int[CX * CY * CZ];
        for (int i = 0; i < count; i++)
        {
            int c = cellOf[i];
            sorted[cellStart[c] + fill[c]++] = i;
        }
    }

    static int Cell(float x, float y, float z)
    {
        int cx = Math.Clamp((int)x, 0, CX - 1), cy = Math.Clamp((int)y, 0, CY - 1), cz = Math.Clamp((int)z, 0, CZ - 1);
        return (cy * CZ + cz) * CX + cx;
    }

    void Densities()
    {
        for (int i = 0; i < count; i++)
        {
            float d = 0;
            int c = cellOf[i], cx = c % CX, cz = c / CX % CZ, cy = c / (CX * CZ);
            for (int y = Math.Max(0, cy - 1); y <= Math.Min(CY - 1, cy + 1); y++)
                for (int z = Math.Max(0, cz - 1); z <= Math.Min(CZ - 1, cz + 1); z++)
                    for (int x = Math.Max(0, cx - 1); x <= Math.Min(CX - 1, cx + 1); x++)
                    {
                        int cell = (y * CZ + z) * CX + x;
                        for (int k = cellStart[cell]; k < cellStart[cell + 1]; k++)
                        {
                            int j = sorted[k];
                            if (j == i) continue;
                            float dx = px[j] - px[i], dy = py[j] - py[i], dz = pz[j] - pz[i];
                            float r2 = dx * dx + dy * dy + dz * dz;
                            if (r2 >= 1) continue;
                            float q = 1 - MathF.Sqrt(r2);
                            d += q * q;
                        }
                    }
            density[i] = d;
        }
    }

    void Relax()
    {
        for (int i = 0; i < count; i++)
        {
            // This particle's density (and "near density", which keeps particles from clumping).
            float d = 0, dn = 0;
            int c = cellOf[i], cx = c % CX, cz = c / CX % CZ, cy = c / (CX * CZ);
            int y0 = Math.Max(0, cy - 1), y1 = Math.Min(CY - 1, cy + 1);
            int z0 = Math.Max(0, cz - 1), z1 = Math.Min(CZ - 1, cz + 1);
            int x0 = Math.Max(0, cx - 1), x1 = Math.Min(CX - 1, cx + 1);
            for (int y = y0; y <= y1; y++)
                for (int z = z0; z <= z1; z++)
                    for (int x = x0; x <= x1; x++)
                    {
                        int cell = (y * CZ + z) * CX + x;
                        for (int k = cellStart[cell]; k < cellStart[cell + 1]; k++)
                        {
                            int j = sorted[k];
                            if (j == i) continue;
                            float dx = px[j] - px[i], dy = py[j] - py[i], dz = pz[j] - pz[i];
                            float r2 = dx * dx + dy * dy + dz * dz;
                            if (r2 >= 1) continue;
                            float q = 1 - MathF.Sqrt(r2);
                            d += q * q; dn += q * q * q;
                        }
                    }
            density[i] = d;
            float pressure = Stiffness * (d - restDensity), near = NearStiffness * dn;

            // Move the neighbours (half) and this particle (the other half), along the line between them.
            float mx = 0, my = 0, mz = 0;
            for (int y = y0; y <= y1; y++)
                for (int z = z0; z <= z1; z++)
                    for (int x = x0; x <= x1; x++)
                    {
                        int cell = (y * CZ + z) * CX + x;
                        for (int k = cellStart[cell]; k < cellStart[cell + 1]; k++)
                        {
                            int j = sorted[k];
                            if (j == i) continue;
                            float dx = px[j] - px[i], dy = py[j] - py[i], dz = pz[j] - pz[i];
                            float r2 = dx * dx + dy * dy + dz * dz;
                            if (r2 >= 1 || r2 < 1e-8f) continue;
                            float r = MathF.Sqrt(r2), q = 1 - r;
                            float push = (pressure * q + near * q * q) * 0.5f / r;
                            float ddx = dx * push, ddy = dy * push, ddz = dz * push;
                            px[j] += ddx; py[j] += ddy; pz[j] += ddz;
                            mx -= ddx; my -= ddy; mz -= ddz;
                        }
                    }
            px[i] += mx; py[i] += my; pz[i] += mz;
        }
    }

    void Viscous()
    {
        // A light touch of viscosity: neighbours approaching each other lose a bit of that speed.
        for (int i = 0; i < count; i++)
        {
            int c = cellOf[i], cx = c % CX, cz = c / CX % CZ, cy = c / (CX * CZ);
            for (int y = Math.Max(0, cy - 1); y <= Math.Min(CY - 1, cy + 1); y++)
                for (int z = Math.Max(0, cz - 1); z <= Math.Min(CZ - 1, cz + 1); z++)
                    for (int x = Math.Max(0, cx - 1); x <= Math.Min(CX - 1, cx + 1); x++)
                    {
                        int cell = (y * CZ + z) * CX + x;
                        for (int k = cellStart[cell]; k < cellStart[cell + 1]; k++)
                        {
                            int j = sorted[k];
                            if (j <= i) continue;
                            float dx = px[j] - px[i], dy = py[j] - py[i], dz = pz[j] - pz[i];
                            float r2 = dx * dx + dy * dy + dz * dz;
                            if (r2 >= 1 || r2 < 1e-8f) continue;
                            float r = MathF.Sqrt(r2);
                            float u = ((vx[i] - vx[j]) * dx + (vy[i] - vy[j]) * dy + (vz[i] - vz[j]) * dz) / r;
                            if (u <= 0) continue;
                            float imp = (1 - r) * Viscosity * u * 0.5f / r;
                            vx[i] -= dx * imp; vy[i] -= dy * imp; vz[i] -= dz * imp;
                            vx[j] += dx * imp; vy[j] += dy * imp; vz[j] += dz * imp;
                        }
                    }
        }
    }

    /// <summary>A kick from below: the water over (x, z) jumps up, more in the middle.</summary>
    void Splash(float x, float z)
    {
        for (int i = 0; i < count; i++)
        {
            float dx = px[i] - x, dz = pz[i] - z, d2 = dx * dx + dz * dz;
            if (d2 > 9) continue;
            float k = 1 - d2 / 9;
            vy[i] += 0.45f * k;
            vx[i] += dx * 0.02f * k; vz[i] += dz * 0.02f * k;
        }
    }

    // =====================================================================================
    // Each frame
    // =====================================================================================
    public override void Draw()
    {
        // The tilt: you drag it, or it rocks by itself.
        if (auto && !paused)
        {
            autoT += 1 / 60f;
            float a = Smooth(0, 4, autoT);
            tiltZ = Lerp(tiltZ, Radians(22) * Sin(autoT * 1.1f) * a, 0.06f);
            tiltX = Lerp(tiltX, Radians(9) * Sin(autoT * 0.63f + 1) * a, 0.06f);
            // Every 7 seconds something kicks the water up from below.
            if (autoT > 5 && (int)(autoT / 7) != (int)((autoT - 1 / 60f) / 7))
                Splash(Random(2, BoxX - 2), Random(1.5f, BoxZ - 1.5f));
        }
        // Gravity in the box's own frame: the box is tilted, gravity still points down.
        float cz = Cos(tiltZ), sz = Sin(tiltZ), cx = Cos(tiltX), sx_ = Sin(tiltX);
        float gx = -Gravity * sz, gy = -Gravity * cz * cx, gz = Gravity * cz * sx_;
        if (!paused)
            for (int s = 0; s < Substeps; s++)
                Step(gx, gy, gz);

        orbit += paused ? 0 : 0.0025f;
        Background(5, 7, 16);
        Render();
        Hud();
    }

    // =====================================================================================
    // Drawing: the box (glyph edges) and every particle, projected and sorted.
    // =====================================================================================
    void Render()
    {
        // Camera on a slow orbit around the box.
        float yaw = Radians(-28) + Sin(orbit) * 0.45f, pitch = Radians(24);
        float dist = 15 / zoom;
        var eye = new PVector(Sin(yaw) * Cos(pitch) * dist, Sin(pitch) * dist + 1, -Cos(yaw) * Cos(pitch) * dist);
        var f = new PVector(-eye.X, -eye.Y + 0.5f, -eye.Z).Normalize();
        var r = f.Cross(new PVector(0, 1, 0)).Normalize();
        var u = r.Cross(f);
        float focal = Height / 2f / Tan(Radians(30));

        // Box space -> world: centered, then tilted (Z tilt, then X tilt).
        float czr = Cos(tiltZ), szr = Sin(tiltZ), cxr = Cos(tiltX), sxr = Sin(tiltX);
        PVector World(float x, float y, float z)
        {
            x -= BoxX / 2; y -= BoxY / 2; z -= BoxZ / 2;
            float x1 = x * czr - y * szr, y1 = x * szr + y * czr;      // around Z
            float y2 = y1 * cxr - z * sxr, z2 = y1 * sxr + z * cxr;    // around X
            return new PVector(x1, y2, z2);
        }

        int n = 0;
        bool Project(PVector w, int slot, float scale)
        {
            float dx = w.X - eye.X, dy = w.Y - eye.Y, dz = w.Z - eye.Z;
            float zc = dx * f.X + dy * f.Y + dz * f.Z;
            if (zc < 0.5f) return false;
            float xc = dx * r.X + dy * r.Y + dz * r.Z, yc = dx * u.X + dy * u.Y + dz * u.Z;
            sx[slot] = Width / 2f + focal * xc / zc;
            sy[slot] = Height / 2f - focal * yc / zc;
            ss[slot] = Min(focal * scale / zc, 90);
            depth[n] = -zc;
            order[n] = slot;
            n++;
            return true;
        }

        for (int i = 0; i < count; i++)
            Project(World(px[i], py[i], pz[i]), i, 0.95f);

        // The glass: its 12 edges, dotted.
        int edgeSlot = MaxParticles, e = 0;
        float[] xs = { 0, BoxX }, ys = { 0, BoxY }, zs = { 0, BoxZ };
        void Edge(float x0, float y0, float z0, float x1, float y1, float z1)
        {
            float len = MathF.Sqrt((x1 - x0) * (x1 - x0) + (y1 - y0) * (y1 - y0) + (z1 - z0) * (z1 - z0));
            int steps = (int)(len / 0.7f);
            for (int k = 0; k <= steps && e < 400; k++)
            {
                float t = k / (float)steps;
                if (Project(World(Lerp(x0, x1, t), Lerp(y0, y1, t), Lerp(z0, z1, t)), edgeSlot + e, 0.6f)) e++;
            }
        }
        foreach (var y in ys) foreach (var z in zs) Edge(0, y, z, BoxX, y, z);
        foreach (var x in xs) foreach (var z in zs) Edge(x, 0, z, x, BoxY, z);
        foreach (var x in xs) foreach (var y in ys) Edge(x, y, 0, x, y, BoxZ);

        System.Array.Sort(depth, order, 0, n);
        TextFont(mono, 32);
        TextAlign(TextAlignH.Center, TextAlignV.Center);
        for (int q = 0; q < n; q++)
        {
            int k = order[q];
            float z = -depth[q];
            float fog = Constrain(1.35f - z / 45, 0.35f, 1);
            float size = ss[k];
            if (size < 3) continue;
            TextSize(size < 24 ? MathF.Round(size) : MathF.Round(size / 6) * 6);   // few sizes: Skia's glyph cache hits
            if (k >= MaxParticles)
            {
                Fill(150, 170, 210, 90 * fog);
                Text(".", sx[k], sy[k]);
                continue;
            }
            float speed = MathF.Sqrt(vx[k] * vx[k] + vy[k] * vy[k] + vz[k] * vz[k]) * Substeps;
            float crowd = density[k] / restDensity;                   // ~1 inside the water, low at the surface and in spray
            float foam = Constrain(speed * 2.2f - 0.15f, 0, 1);
            // Spray, surface, body: by how crowded it is (the surface has neighbours on one side only).
            char glyph = crowd < 0.35f ? (foam > 0.35f ? '*' : '.')
                       : crowd < 0.6f ? (foam > 0.5f ? '+' : '~')
                       : crowd < 0.78f ? 'o'
                       : foam > 0.6f ? '%' : '#';
            // Deep navy at the bottom, brighter blue towards the top, white where it's fast (foam).
            float up = Constrain(py[k] / 5f, 0, 1);
            float br = Lerp(0.45f, 1, up) * (crowd < 0.72f ? 1.15f : 1);
            float r0 = 25 * br, g0 = 95 * br, b0 = 215 * br;
            Fill(Lerp(r0, 235, foam) * fog, Lerp(g0, 248, foam) * fog, Lerp(b0, 255, foam) * fog, 240);
            Text(glyph.ToString(), sx[k], sy[k]);
        }
    }

    void Hud()
    {
        TextFont(mono, 13);
        TextSize(13);
        TextAlign(TextAlignH.Left, TextAlignV.Bottom);
        string[] names = { "", "dam break", "drop into a pool", "two walls collide" };
        Fill(255, 255, 255, 110);
        Text($"{count:N0} particles · {names[scenario]}{(paused ? " · paused" : "")}{(auto ? " · auto" : "")}", 16, Height - 30);
        Fill(255, 255, 255, 60);
        Text("drag: tilt · click: splash · wheel: zoom · 1 2 3: scenarios · Space: pause · A: auto", 16, Height - 12);
    }

    public override void MouseDragged()
    {
        auto = false;
        tiltZ = Constrain(tiltZ - (MouseX - PMouseX) * 0.004f, Radians(-40), Radians(40));
        tiltX = Constrain(tiltX + (MouseY - PMouseY) * 0.004f, Radians(-30), Radians(30));
    }

    public override void MouseClicked() => Splash(Random(2, BoxX - 2), Random(1.5f, BoxZ - 1.5f));

    public override void MouseWheel(float delta) => zoom = Constrain(zoom * (delta > 0 ? 1 / 1.1f : 1.1f), 0.6f, 2.5f);

    public override void KeyPressed()
    {
        if (Key >= '1' && Key <= '3') { Scenario(Key - '0'); autoT = 0; }
        else if (Key == ' ') paused = !paused;
        else if (Key == 'a' || Key == 'A') auto = !auto;
    }

    static float Smooth(float a, float b, float x)
    {
        float k = Math.Clamp((x - a) / (b - a), 0, 1);
        return k * k * (3 - 2 * k);
    }
}

// MIDI learn: play this flower with a MIDI controller.
//
// 1. Click MIDI in the [Tweak] panel (top right): it lights up.
// 2. Touch a slider, then turn a knob or move a fader: they're connected.
// 3. Do the same with as many sliders as you like, then click MIDI again.
//
// Connections last the whole session (Run and Hot Reload keep them). To make
// one permanent, write it in Setup(): MapMidi("petals", 21);
// Pads and keys fire bursts (OnMidi), sized by velocity; the pitch-bend wheel
// twists the whole flower. No controller? Keys 1-8 fake pad hits.
public class MySketch : Sketch
{
    [Tweak(3, 24)] int petals = 9;
    [Tweak(30, 260)] float radius = 150;
    [Tweak(0, 3)] float spin = 0.5f;
    [Tweak(0, 360)] float hue = 200;
    [Tweak(0, 1)] float wobble = 0.35f;
    [Tweak] bool trails = true;

    private readonly List<Burst> _bursts = new();
    private float _bend;   // -1..1 from the pitch-bend wheel
    private float _angle;
    private string _status = "";

    private sealed class Burst
    {
        public float X, Y, Size, Hue, Life = 1;
    }

    public override void Setup()
    {
        Size(720, 520);
        var inputs = MidiInputs();
        _status = inputs.Length == 0
            ? "No MIDI controller found -- keys 1-8 fake pad hits"
            : "MIDI: " + string.Join(", ", inputs);
    }

    public override void OnMidi(MidiMessage m)
    {
        if (m.Kind == MidiKind.NoteOn)
            Fire(m.Note, m.Velocity / 127f);
        else if (m.Kind == MidiKind.PitchBend)
            _bend = m.Bend / 8192f;
    }

    public override void KeyPressed()
    {
        if (Key >= '1' && Key <= '8')
            Fire(36 + (Key - '1'), 0.8f);
    }

    private void Fire(int note, float strength)
    {
        float a = note * 0.7f;
        _bursts.Add(new Burst
        {
            X = Width / 2f + Cos(a) * radius * 0.8f,
            Y = Height / 2f + Sin(a) * radius * 0.8f,
            Size = 30 + strength * 160,
            Hue = (hue + note * 15) % 360,
        });
    }

    public override void Draw()
    {
        if (trails)
            Background(10, 12, 20, 40);
        else
            Background(10, 12, 20);

        _angle += spin * 0.02f;
        float t = Millis() / 1000f;

        PushMatrix();
        Translate(Width / 2f, Height / 2f);
        Rotate(_angle + _bend * 1.2f);
        NoFill();
        StrokeWeight(2);
        for (int ring = 0; ring < 4; ring++)
        {
            float r = radius * (1 - ring * 0.2f);
            StrokeHSB((hue + ring * 25) % 360, 70, 100, 200);
            BeginShape();
            for (int i = 0; i <= 200; i++)
            {
                float a = TWO_PI * i / 200;
                float petal = Sin(a * petals + t * 1.5f + ring) * wobble;
                float rr = r * (0.6f + 0.4f * Abs(Cos(a * petals / 2f))) * (1 + petal * 0.3f);
                Vertex(Cos(a) * rr, Sin(a) * rr);
            }
            EndShape(true);
        }
        PopMatrix();

        NoStroke();
        for (int i = _bursts.Count - 1; i >= 0; i--)
        {
            var b = _bursts[i];
            FillHSB(b.Hue, 60, 100, 180 * b.Life);
            Circle(b.X, b.Y, b.Size * (2 - b.Life));
            b.Life -= 0.03f;
            if (b.Life <= 0)
                _bursts.RemoveAt(i);
        }

        Fill(255, 160);
        TextSize(13);
        Text(_status, 14, Height - 16);
    }
}

// Visuals in time with the music -- no math with Millis() or frame counts.
//
//   Beat()          where the music is, in beats (2.5 = halfway through beat 3)
//   Phase(n)        0 -> 1 ramp every n beats (0 = right on the beat)
//   Pulse(n)        1 on the beat, fading out before the next one
//   OnBeat(n)       true on the one frame a new beat (or every n beats) starts
//   BeatTween(a, b, Ease.OutBack)   a -> b, landing exactly on the next beat
//
// While sound plays they follow what you HEAR; the loops' first downbeat is
// beat 0 of a bar. Change Bpm and press Hot Reload: everything keeps up.
public class MySketch : Sketch
{
    private int _palette;
    private readonly float[] _hues = { 200, 330, 40, 160 };

    public override void Setup()
    {
        Size(720, 480);
        Bpm = 110;
    }

    [LiveLoop]
    async Task Drums()
    {
        for (int i = 0; i < 4; i++)
        {
            Sample("kick");
            if (i % 2 == 1) Sample("snare", amp: 0.7);
            await Sleep(0.5);
            Sample("hat", amp: 0.4);
            await Sleep(0.5);
        }
    }

    [LiveLoop]
    async Task Bass()
    {
        foreach (var note in new[] { "E2", "E2", "G2", "A2" })
        {
            UseSynth(Synth.Saw);
            Play(note, amp: 0.4, release: 0.5, cutoff: 75);
            await Sleep(1);
        }
    }

    public override void Draw()
    {
        if (OnBeat(4))
            _palette = (_palette + 1) % _hues.Length;  // a new color every bar
        float hue = _hues[_palette];

        Background(12, 12, 18);

        // 1. The ring throbs on every beat.
        float throb = Pulse(1, sharpness: 5);
        NoFill();
        StrokeWeight(6 + throb * 10);
        StrokeHSB(hue, 70, 100);
        Circle(180, 200, 140 + throb * 60);

        // 2. Blocks slide to a new spot on every beat, landing on the next one.
        NoStroke();
        for (int i = 0; i < 4; i++)
        {
            int step = (int)Beat() + i;
            float from = 360 + (step % 4) * 80;
            float to = 360 + ((step + 1) % 4) * 80;
            float x = BeatTween(from, to, Ease.OutBack);
            FillHSB((hue + i * 30) % 360, 60, 95);
            Rect(x, 90 + i * 60, 50, 40);
        }

        // 3. A 16-step sequencer row: the cursor is Beat() in sixteenths.
        int sixteenth = (int)(Beat() * 4) % 16;
        for (int i = 0; i < 16; i++)
        {
            bool on = i == sixteenth;
            if (on) FillHSB(hue, 50, 100); else Fill(255, i % 4 == 0 ? 70 : 35);
            Rect(40 + i * 40, 400, 32, on ? 40 : 24);
        }

        // 4. Bars and beats as text.
        Fill(255, 200);
        TextSize(14);
        Text($"bar {(int)Bar() + 1}   beat {(int)Beat() % 4 + 1}   {Bpm:0} BPM", 40, 380);
    }
}

// The microphone: Amplitude, Spectrum() and Waveform() hear the room.
//
// ListenTo(AudioSource.Microphone) switches them from the sketch's own sound
// to your default microphone. Talk, clap, whistle, play music nearby.
// S cycles: microphone -> sketch sound -> both. The microphone turns off by
// itself when the sketch stops.
public class MySketch : Sketch
{
    [Tweak(1, 12)] float gain = 4;
    [Tweak(0.02f, 0.4f)] float clapJump = 0.12f;

    private readonly float[] _bands = new float[48];
    private readonly float[] _smooth = new float[48];
    private readonly float[] _wave = new float[512];
    private readonly List<PVector> _sparks = new();
    private readonly List<PVector> _velocities = new();
    private float _lastLevel;

    public override void Setup()
    {
        Size(720, 520);
        ListenTo(AudioSource.Microphone);
    }

    public override void KeyPressed()
    {
        if (Key == 's')
            ListenTo(Listening switch
            {
                AudioSource.Microphone => AudioSource.Sketch,
                AudioSource.Sketch => AudioSource.Both,
                _ => AudioSource.Microphone,
            });
    }

    public override void Draw()
    {
        MicGain = gain;
        Background(8, 10, 16, 60);

        float level = Amplitude;
        if (level - _lastLevel > clapJump)
            Clap();
        _lastLevel = level;

        // Radial spectrum: one bar per band, smoothed so it breathes instead of flickers.
        Spectrum(_bands);
        PushMatrix();
        Translate(Width / 2f, Height / 2f);
        StrokeWeight(5);
        for (int i = 0; i < _bands.Length; i++)
        {
            _smooth[i] = Lerp(_smooth[i], _bands[i], 0.35f);
            float a = TWO_PI * i / _bands.Length - HALF_PI;
            float r0 = 90 + level * 200;
            float r1 = r0 + _smooth[i] * 170;
            StrokeHSB(190 + i * 3.5f, 70, 100);
            Line(Cos(a) * r0, Sin(a) * r0, Cos(a) * r1, Sin(a) * r1);
        }

        // The waveform as a ring inside.
        Waveform(_wave);
        NoFill();
        StrokeWeight(2);
        Stroke(255, 180);
        BeginShape();
        for (int i = 0; i < _wave.Length; i += 4)
        {
            float a = TWO_PI * i / _wave.Length;
            float r = 70 + _wave[i] * 120;
            Vertex(Cos(a) * r, Sin(a) * r);
        }
        EndShape(true);

        // Sparks from claps.
        NoStroke();
        for (int i = _sparks.Count - 1; i >= 0; i--)
        {
            _sparks[i].Add(_velocities[i]);
            _velocities[i].Mult(0.96f);
            FillHSB(30, 80, 100, 220);
            Circle(_sparks[i].X, _sparks[i].Y, 6);
            if (_velocities[i].Mag() < 0.3f)
            {
                _sparks.RemoveAt(i);
                _velocities.RemoveAt(i);
            }
        }

        PopMatrix();
        Fill(255, 170);
        TextSize(13);
        Text($"listening to: {Listening}   level {level:0.00}   (S to switch)", 14, Height - 16);
        if (MicStatus.StartsWith("No"))
            Text(MicStatus, 14, Height - 38);
    }

    private void Clap()
    {
        for (int i = 0; i < 40; i++)
        {
            _sparks.Add(new PVector(0, 0));
            _velocities.Add(PVector.FromAngle(Random(TWO_PI)).Mult(Random(4, 12)));
        }
    }
}

// Seeded generative art: same seed, same landscape.
//
// Everything random here comes from Random() and Noise(), which follow the
// sketch's Seed -- so:
//   F6 (🎲)              a new seed (Sketch menu: keep the seed to lock it)
//   Ctrl+Shift+V         the variations sheet: pick the best of 9 or 16
//   S                    save a PNG; it remembers the seed and the sliders
//                        (Sketch > Open seed from PNG... brings them back)
//
// RandomSeed(Seed) at the top of Draw() makes every frame repeat the same
// random numbers, so moving a slider changes only what that slider controls.
public class MySketch : Sketch
{
    [Tweak(2, 8)] int layers = 5;
    [Tweak(0.5f, 6)] float roughness = 2.2f;
    [Tweak(0, 360)] float hue = 215;
    [Tweak(0, 400)] int stars = 160;
    [Tweak] bool sun = true;

    public override void Setup() => Size(800, 500);

    public override void Draw()
    {
        RandomSeed(Seed);

        // Sky: a vertical gradient.
        for (int y = 0; y < Height; y += 4)
        {
            float t = y / (float)Height;
            FillHSB(hue, 50 - t * 20, 18 + t * 30);
            NoStroke();
            Rect(0, y, Width, 4);
        }

        // Stars.
        for (int i = 0; i < stars; i++)
        {
            float x = Random(Width), y = Random(Height * 0.6f);
            Fill(255, Random(80, 230));
            Circle(x, y, Random(1, 3));
        }

        // Sun (or moon).
        if (sun)
        {
            FillHSB((hue + 180) % 360, 40, 100, 230);
            Circle(Random(120, Width - 120), Random(80, 200), Random(60, 120));
        }

        // Mountain layers, back to front: lighter and smoother far away.
        for (int layer = 0; layer < layers; layer++)
        {
            float depth = layer / (float)Math.Max(1, layers - 1);
            float baseY = Height * (0.45f + depth * 0.4f);
            float amp = 60 + depth * 90;
            float offset = Random(1000);
            FillHSB(hue, 35 + depth * 30, 70 - depth * 55);
            BeginShape();
            Vertex(0, Height);
            for (int x = 0; x <= Width; x += 6)
                Vertex(x, baseY - Noise(offset + x * 0.004f * roughness, layer * 10) * amp * 2 + amp);
            Vertex(Width, Height);
            EndShape(true);
        }

        Fill(255, 200);
        TextSize(13);
        Text($"seed {Seed}   ·   F6 new seed   ·   Ctrl+Shift+V variations   ·   S save PNG", 14, Height - 14);
    }

    public override void KeyPressed()
    {
        if (Key == 's')
        {
            HideTweaks();
            SaveFrame($"landscape-{Seed}-####.png");
            ShowTweaks();
            Println($"Saved landscape-{Seed}-{FrameCount:0000}.png (seed and sliders are inside the PNG)");
        }
    }
}

// Plotter-friendly art: only strokes, two pens.
//
// File > Export for print (Ctrl+Shift+E):
//   "Plotter SVG"  one layer per color (= per pen), strokes reordered so the
//                  pen travels as little as possible between them
//   "Big PNG"      2x-16x, drawn again as vectors: sharp at poster size
// Same seed, same drawing -- F6 rolls another one.
public class MySketch : Sketch
{
    [Tweak(50, 900)] int lines = 420;
    [Tweak(10, 160)] int steps = 70;
    [Tweak(0.5f, 6)] float zoom = 2.2f;
    [Tweak(0, 1)] float secondPen = 0.25f;

    public override void Setup()
    {
        Size(700, 500);
        FrameRate(12); // a still drawing: a few frames a second is plenty for the sliders
    }

    public override void Draw()
    {
        RandomSeed(Seed);
        Background(250, 248, 240);
        NoFill();
        StrokeWeight(1);

        for (int i = 0; i < lines; i++)
        {
            float x = Random(-50, Width + 50);
            float y = Random(-50, Height + 50);
            bool red = Random(1) < secondPen;
            if (red) Stroke(200, 40, 40); else Stroke(20, 20, 30);

            BeginShape();
            for (int s = 0; s < steps; s++)
            {
                Vertex(x, y);
                float angle = Noise(x / Width * zoom, y / Height * zoom) * TWO_PI * 2;
                x += Cos(angle) * 4;
                y += Sin(angle) * 4;
            }
            EndShape();
        }
    }

}

// The performance panel: press F3 (here it starts open via ShowStats()).
//
//   fps          frames per second actually reached (target: FrameRate())
//   Draw ms      how long your Draw() takes -- the bars; the line is the budget
//   KB/frame     memory Draw() allocates every frame
//   GC 0/1/2     garbage collections since the panel opened
//
// Raise "particles" until the bars go red. Then switch on "garbage": the same
// work, but a new List every frame -- watch KB/frame and the GC counter climb.
public class MySketch : Sketch
{
    [Tweak(100, 20000)] int particles = 3000;
    [Tweak] bool garbage = false;

    private readonly List<PVector> _pos = new();
    private readonly List<PVector> _vel = new();
    private readonly List<PVector> _reused = new();

    public override void Setup()
    {
        Size(720, 480);
        ShowStats();
    }

    public override void Draw()
    {
        while (_pos.Count < particles)
        {
            _pos.Add(new PVector(Random(Width), Random(Height)));
            _vel.Add(PVector.Random2D().Mult(Random(0.5f, 2)));
        }
        if (_pos.Count > particles)
        {
            _pos.RemoveRange(particles, _pos.Count - particles);
            _vel.RemoveRange(particles, _vel.Count - particles);
        }

        // The wasteful way allocates a fresh list (and fresh vectors) every frame.
        var visible = garbage ? new List<PVector>() : _reused;
        visible.Clear();

        for (int i = 0; i < _pos.Count; i++)
        {
            var p = _pos[i];
            p.Add(_vel[i]);
            if (p.X < 0) p.X += Width; else if (p.X > Width) p.X -= Width;
            if (p.Y < 0) p.Y += Height; else if (p.Y > Height) p.Y -= Height;
            visible.Add(garbage ? p.Copy() : p);
        }

        Background(14, 16, 24);
        NoStroke();
        Fill(120, 200, 255, 160);
        foreach (var p in visible)
            Circle(p.X, p.Y, 3);

        Fill(255, 180);
        TextSize(13);
        Text($"{particles} particles  ·  garbage {(garbage ? "ON" : "off")}  ·  F3 hides the panel", 14, Height - 14);
    }
}

// The data/ folder: files that belong to the sketch, found by name.
//
//   LoadTable("clima.csv", "header")   looks in data/ first, then next to the .cs
//   LoadImage("foto.jpg")               same
//   SaveTable(t, DataPath("x.csv"))     DataPath() = the full path inside data/
//
// Exporting the sketch copies data/ next to the app, so these paths work there
// too. Save this sketch (Ctrl+S) first: an unsaved sketch has no folder yet.
public class MySketch : Sketch
{
    private Table? _table;
    private PImage? _photo;
    private string _note = "";
    private readonly string[] _months = { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };

    public override void Setup()
    {
        Size(760, 460);

        if (SketchFolder == null)
        {
            _note = "Save this sketch (Ctrl+S) to give it a data/ folder -- showing data made in memory meanwhile.";
            _table = MakeSampleTable();
            return;
        }

        // First run: write a CSV into data/ so there's something to load.
        if (!File.Exists(DataPath("clima.csv")))
            SaveTable(MakeSampleTable(), DataPath("clima.csv"));

        _table = LoadTable("clima.csv", "header");
        if (File.Exists(DataPath("foto.jpg")))
            _photo = LoadImage("foto.jpg");
        _note = $"data/ = {DataFolder}" + (_photo == null ? "   (add foto.jpg there for a background)" : "");
    }

    private Table MakeSampleTable()
    {
        var t = new Table();
        t.SetColumnTitle(0, "month");
        t.SetColumnTitle(1, "temp");
        t.SetColumnTitle(2, "rain");
        for (int m = 0; m < 12; m++)
        {
            var row = t.AddRow();
            row.SetString("month", _months[m]);
            row.SetFloat("temp", 22 + 6 * Sin((m - 1) / 12f * TWO_PI));
            row.SetFloat("rain", 40 + 120 * Abs(Sin((m - 3) / 12f * PI)));
        }
        return t;
    }

    public override void Draw()
    {
        Background(250, 247, 240);
        if (_photo != null)
        {
            Tint(70); // see-through
            Image(_photo, 0, 0, Width, Height);
            NoTint();
        }

        int n = _table!.RowCount;
        float left = 60, right = Width - 30, bottom = Height - 70, top = 50;
        float step = (right - left) / n;

        NoStroke();
        for (int i = 0; i < n; i++)
        {
            var row = _table.GetRow(i);
            float rain = row.GetFloat("rain");
            float h = Map(rain, 0, 200, 0, bottom - top);
            Fill(90, 150, 220, 180);
            Rect(left + i * step + 6, bottom - h, step - 12, h);
            Fill(60);
            TextSize(11);
            Text(row.GetString("month"), left + i * step + 8, bottom + 16);
        }

        NoFill();
        Stroke(220, 90, 50);
        StrokeWeight(3);
        BeginShape();
        for (int i = 0; i < n; i++)
            Vertex(left + i * step + step / 2, Map(_table.GetRow(i).GetFloat("temp"), 10, 35, bottom, top));
        EndShape();

        NoStroke();
        Fill(40);
        TextSize(15);
        Text("Rain (bars) and temperature (line), from data/clima.csv", left, 30);
        Fill(90);
        TextSize(11);
        Text(_note, 14, Height - 18);
    }
}

// Real rewind. Under the canvas:
//   ⏸  pause            the slider scrubs through the last frames
//   ⤺  continue from here: the sketch's fields (the grid, the generation,
//      even the random generator) go back to that frame, and it runs on --
//      the future after it is forgotten.
// Paint cells with the mouse (drag) to make the new future different.
public class MySketch : Sketch
{
    const int Cols = 90, Rows = 60, Cell = 8;
    bool[,] _grid = new bool[Cols, Rows];
    bool[,] _next = new bool[Cols, Rows];
    int _generation;

    public override void Setup()
    {
        Size(Cols * Cell, Rows * Cell + 30);
        FrameRate(15);
        for (int x = 0; x < Cols; x++)
            for (int y = 0; y < Rows; y++)
                _grid[x, y] = Random(1) < 0.22f;
    }

    public override void Draw()
    {
        Step();
        Background(16, 18, 26);
        NoStroke();
        for (int x = 0; x < Cols; x++)
            for (int y = 0; y < Rows; y++)
                if (_grid[x, y])
                {
                    FillHSB((x * 2 + _generation) % 360, 55, 95);
                    Rect(x * Cell, y * Cell, Cell - 1, Cell - 1);
                }

        Fill(255, 190);
        TextSize(13);
        Text($"generation {_generation}  ·  ⏸ then ⤺ under the canvas to rewind for real  ·  drag to paint", 10, Height - 10);
    }

    void Step()
    {
        for (int x = 0; x < Cols; x++)
            for (int y = 0; y < Rows; y++)
            {
                int n = 0;
                for (int dx = -1; dx <= 1; dx++)
                    for (int dy = -1; dy <= 1; dy++)
                        if ((dx != 0 || dy != 0) && _grid[(x + dx + Cols) % Cols, (y + dy + Rows) % Rows])
                            n++;
                _next[x, y] = _grid[x, y] ? n is 2 or 3 : n == 3;
            }
        (_grid, _next) = (_next, _grid);
        _generation++;
    }

    public override void MouseDragged() => Paint();
    public override void MousePressed() => Paint();

    void Paint()
    {
        int cx = (int)(MouseX / Cell), cy = (int)(MouseY / Cell);
        for (int dx = -1; dx <= 1; dx++)
            for (int dy = -1; dy <= 1; dy++)
            {
                int x = cx + dx, y = cy + dy;
                if (x >= 0 && x < Cols && y >= 0 && y < Rows)
                    _grid[x, y] = true;
            }
    }
}

// Rain on the terminal: an AttachedSketch has no window of its own,
// it draws on another app -- here, Windows Terminal, always behind its
// text: it shows through a see-through profile ("opacity" below 100).
//
// 1. Open Windows Terminal and press Run: it rains on it.
// 2. Move it, resize it, maximize it: the sketch follows
//    (Width/Height change and WindowResized() tells you).
// 3. Clicks go through to the terminal: keep typing.
//    The mouse cursor is an umbrella. ■ Stop removes the rain.
//
// Windows only for now. Clear() at the start of Draw() keeps the terminal visible.
public class TerminalRain : AttachedSketch
{
    private readonly List<Drop> _drops = new();
    private readonly List<Ripple> _ripples = new();

    private sealed class Drop { public float X, Y, Speed, Length; }
    private sealed class Ripple { public float X, Y, R, Life = 1; }

    public override void Settings()
    {
        // Runs before the window is looked for, so Width/Height in Setup()
        // are already the terminal's.
        Attach(WindowTarget.Terminal);
    }

    public override void Setup()
    {
        FitDrops();
    }

    public override void WindowResized()
    {
        FitDrops(); // wider window, more rain
    }

    private void FitDrops()
    {
        int wanted = Math.Max(10, Width / 6);
        while (_drops.Count < wanted)
            _drops.Add(NewDrop(Random(Height)));
        if (_drops.Count > wanted)
            _drops.RemoveRange(wanted, _drops.Count - wanted);
    }

    private Drop NewDrop(float y) => new Drop
    {
        X = Random(Width),
        Y = y,
        Speed = Random(4, 9),
        Length = Random(8, 18),
    };

    public override void Draw()
    {
        Clear(); // transparent: the terminal shows through

        StrokeWeight(1.5f);
        Stroke(140, 200, 255, 150);
        foreach (var d in _drops)
        {
            Line(d.X, d.Y, d.X - 1, d.Y + d.Length);
            d.Y += d.Speed;

            // MouseX/MouseY follow the cursor even though clicks go through.
            bool umbrella = Math.Abs(d.X - MouseX) < 40 && d.Y + d.Length > MouseY - 6 && d.Y < MouseY;
            if (umbrella || d.Y > Height)
            {
                _ripples.Add(new Ripple { X = d.X, Y = umbrella ? MouseY - 6 : Height - 4 });
                d.X = Random(Width);
                d.Y = -Random(60);
            }
        }

        NoFill();
        for (int i = _ripples.Count - 1; i >= 0; i--)
        {
            var r = _ripples[i];
            Stroke(140, 200, 255, 170 * r.Life);
            Ellipse(r.X, r.Y, r.R * 2, r.R * 0.6f);
            r.R += 0.8f;
            r.Life -= 0.05f;
            if (r.Life <= 0)
                _ripples.RemoveAt(i);
        }
    }
}

// Water in the terminal: drag Windows Terminal around and the water inside
// sloshes, hits the walls and splashes -- the same trick as a glass of
// water in a moving car: what's inside feels the opposite of
// TargetAcceleration.
//
// 1. Open Windows Terminal and press Run.
// 2. Drag the window and let go suddenly. Shake it. Yank it down: the water jumps.
// 3. Type in the terminal: every key drops a drop, Enter makes a splash.
//    Click the water to drop one where you click.
// 4. Switch to another window: the water dims until you come back.
//
// ListenToTargetKeys()/ListenToTargetMouse() read keys typed into the terminal
// and clicks over it (the terminal still gets all of them). Windows only.
public class TerminalWater : AttachedSketch
{
    const float Cell = 8;          // width of one water column, in pixels
    const float Gravity = 900;     // px/s²
    const float Inertia = 0.28f;   // how strongly the window's motion pushes the water
    const float FillLevel = 0.3f;  // how full the window is

    float[] _h = new float[0];     // water height per column
    float[] _u = new float[0];     // flow between columns
    float[] _flux = new float[0];
    int _cols;
    float _dim = 1;
    readonly List<PVector> _drops = new();
    readonly List<PVector> _dropSpeeds = new();

    public override void Settings() => Attach(WindowTarget.Terminal);

    public override void Setup()
    {
        ListenToTargetKeys();
        ListenToTargetMouse();
        Rebuild();
    }

    public override void WindowResized() => Rebuild();

    void Rebuild()
    {
        _cols = Math.Max(8, (int)(Width / Cell));
        _h = new float[_cols];
        _u = new float[_cols + 1];
        _flux = new float[_cols + 1];
        for (int i = 0; i < _cols; i++)
            _h[i] = Height * FillLevel;
    }

    // --- input from the terminal -------------------------------------------

    public override void KeyTyped() => Drop(Random(Width), 1);

    public override void KeyPressed()
    {
        if (Key == ENTER)
            for (int i = 0; i < 6; i++)
                Drop(Random(Width), 2);
    }

    public override void MousePressed() => Drop(MouseX, 1.5f);

    public override void TargetShown() => Splash(_cols / 2, 60); // welcome back

    void Drop(float x, float size)
    {
        _drops.Add(new PVector(x, -10, size));
        _dropSpeeds.Add(new PVector(Random(-20, 20), Random(0, 80)));
    }

    void Splash(int col, float amount)
    {
        if (col < 1 || col >= _cols - 1) return;
        float take = Math.Min(amount, _h[col] * 0.5f);
        _h[col] -= take;               // a dent in the surface...
        _h[col - 1] += take / 2;       // ...pushes water to both sides: a wave
        _h[col + 1] += take / 2;
    }

    // --- simulation -----------------------------------------------------------

    public override void Draw()
    {
        Clear();
        float dt = DeltaTime;   // real seconds: same speed at 60 fps or in eco mode
        var a = TargetAcceleration;
        float fx = -a.X * Inertia;                                        // sideways push
        float g = Constrain(Gravity - a.Y * Inertia, Gravity * 0.25f, Gravity * 4);  // moving down = lighter

        Step(dt, fx, g);
        UpdateDrops(dt, g);

        _dim = Lerp(_dim, IsTargetFocused ? 1 : 0.45f, 0.08f);
        DrawWater();
        DrawDrops();
    }

    void Step(float dt, float fx, float g)
    {
        int sub = 8;
        float sdt = dt / sub;
        float damp = Exp(-0.8f * sdt);
        float maxU = 0.45f * Cell / sdt;
        for (int s = 0; s < sub; s++)
        {
            for (int i = 1; i < _cols; i++)
            {
                float v = _u[i] + sdt * (-g * (_h[i] - _h[i - 1]) / Cell + fx);
                if (_h[i] < 0.5f && _h[i - 1] < 0.5f) v = 0;
                _u[i] = Constrain(v * damp, -maxU, maxU);
            }
            _u[0] = _u[_cols] = 0;   // the window's walls
            for (int i = 1; i < _cols; i++)
                _flux[i] = _u[i] * (_u[i] > 0 ? _h[i - 1] : _h[i]);
            for (int i = 0; i < _cols; i++)
                _h[i] = Constrain(_h[i] - sdt * (_flux[i + 1] - _flux[i]) / Cell, 0, Height);
        }

        // Keep the volume constant (rounding slowly leaks it).
        float target = FillLevel * Height * _cols, vol = 0;
        foreach (var h in _h) vol += h;
        if (vol > 1)
            for (int i = 0; i < _cols; i++) _h[i] *= 1 + (target / vol - 1) * 0.1f;
    }

    void UpdateDrops(float dt, float g)
    {
        for (int i = _drops.Count - 1; i >= 0; i--)
        {
            var p = _drops[i];
            var v = _dropSpeeds[i];
            v.Y += g * dt;
            p.X += v.X * dt;
            p.Y += v.Y * dt;
            int col = Constrain((int)(p.X / Cell), 0, _cols - 1);
            if (p.Y >= Height - _h[col])
            {
                Splash(col, 6 * p.Z);
                _drops.RemoveAt(i);
                _dropSpeeds.RemoveAt(i);
            }
        }
    }

    void DrawWater()
    {
        // The body: one polygon through the middle of every column's top.
        NoStroke();
        Fill(20, 90, 170, 110 * _dim);
        BeginShape();
        Vertex(0, Height);
        Vertex(0, Height - _h[0]);
        for (int i = 0; i < _cols; i++)
            Vertex(i * Cell + Cell / 2, Height - _h[i]);
        Vertex(Width, Height - _h[_cols - 1]);
        Vertex(Width, Height);
        EndShape(close: true);

        // The surface line, brighter (foam) where it's steep.
        StrokeWeight(2);
        for (int i = 1; i < _cols; i++)
        {
            float steep = Abs(_h[i] - _h[i - 1]);
            Stroke(150, 230, 255, (110 + Math.Min(steep * 25, 145)) * _dim);
            Line((i - 1) * Cell + Cell / 2, Height - _h[i - 1], i * Cell + Cell / 2, Height - _h[i]);
        }
    }

    void DrawDrops()
    {
        NoStroke();
        Fill(170, 230, 255, 220 * _dim);
        foreach (var p in _drops)
            Ellipse(p.X, p.Y, 4 * p.Z, 6 * p.Z);
    }
}

// Bubbles from the keyboard: every key you type in Windows Terminal floats up
// as a bubble with its letter inside. Enter pops them all into sparks,
// Backspace pops the newest one. Shake the window and they scatter.
//
// 1. Open Windows Terminal, press Run and type something there.
// 2. Click anywhere over the terminal: a ring of sparks (the click still
//    reaches the terminal).
// 3. Minimize it and restore it: TargetHidden()/TargetShown() count the trips.
//
// Keys are read only while the terminal is the window in front
// (ListenToTargetKeys), and nothing is ever kept from it. Windows only.
public class TerminalKeys : AttachedSketch
{
    sealed class Bubble { public PVector Pos = new(0, 0), Vel = new(0, 0); public char Letter; public float Hue, Life = 1; }
    sealed class Spark { public PVector Pos = new(0, 0), Vel = new(0, 0); public float Hue, Life = 1; }

    readonly List<Bubble> _bubbles = new();
    readonly List<Spark> _sparks = new();
    int _trips;
    float _typedX;

    public override void Settings() => Attach(WindowTarget.Terminal);

    public override void Setup()
    {
        ListenToTargetKeys();
        ListenToTargetMouse();
        ColorMode(ColorSpaceMode.HSB, 360, 100, 100, 255);
        TextAlign(TextAlignH.Center, TextAlignV.Center);
        _typedX = Width * 0.1f;
    }

    public override void KeyTyped()
    {
        if (Key == ' ')
        {
            _typedX += 14;
            return;
        }
        // Letters go left to right like the text you're typing, wrapping around.
        _typedX += 18;
        if (_typedX > Width - 30) _typedX = 30;
        _bubbles.Add(new Bubble
        {
            Letter = Key,
            Pos = new PVector(_typedX, Height - 30),
            Vel = new PVector(Random(-15, 15), Random(-90, -60)),
            Hue = char.IsDigit(Key) ? 40 : char.IsLetter(Key) ? 195 : 300,
        });
    }

    public override void KeyPressed()
    {
        if (Key == ENTER)
        {
            foreach (var b in _bubbles) Burst(b.Pos.X, b.Pos.Y, b.Hue, 8);
            _bubbles.Clear();
            _typedX = Width * 0.1f;
        }
        else if (Key == BACKSPACE && _bubbles.Count > 0)
        {
            var last = _bubbles[^1];
            Burst(last.Pos.X, last.Pos.Y, last.Hue, 6);
            _bubbles.RemoveAt(_bubbles.Count - 1);
            _typedX = Math.Max(30, _typedX - 18);
        }
    }

    public override void MousePressed() => Burst(MouseX, MouseY, Random(360), 24);

    public override void TargetHidden() => _trips++;

    public override void TargetShown() => Burst(Width / 2f, Height / 2f, 120, 40);

    void Burst(float x, float y, float hue, int n)
    {
        for (int i = 0; i < n; i++)
        {
            float a = TWO_PI * i / n + Random(0.2f);
            float speed = Random(80, 220);
            _sparks.Add(new Spark { Pos = new PVector(x, y), Vel = new PVector(Cos(a) * speed, Sin(a) * speed), Hue = hue });
        }
    }

    public override void Draw()
    {
        Clear();
        float dt = DeltaTime;   // real seconds: same speed at 60 fps or in eco mode

        // Shaking the window throws the bubbles the other way (inertia).
        var kick = TargetAcceleration;
        foreach (var b in _bubbles)
        {
            b.Vel.X -= kick.X * 0.02f * dt;
            b.Vel.Y -= kick.Y * 0.02f * dt;
            b.Vel.Y -= 10 * dt;                 // keep floating up
            b.Vel.X *= 0.99f;
            b.Pos.X += b.Vel.X * dt;
            b.Pos.Y += b.Vel.Y * dt;
            if (b.Pos.X < 16 || b.Pos.X > Width - 16) b.Vel.X *= -0.8f;
            b.Pos.X = Constrain(b.Pos.X, 16, Width - 16);
            if (b.Pos.Y < 20) b.Life -= dt * 2;  // fades out at the top
        }
        _bubbles.RemoveAll(b => b.Life <= 0);

        foreach (var s in _sparks)
        {
            s.Vel.Y += 300 * dt;
            s.Pos.X += s.Vel.X * dt;
            s.Pos.Y += s.Vel.Y * dt;
            s.Life -= dt * 1.4f;
        }
        _sparks.RemoveAll(s => s.Life <= 0);

        TextSize(16);
        foreach (var b in _bubbles)
        {
            Stroke(b.Hue, 60, 100, 200 * b.Life);
            StrokeWeight(1.5f);
            Fill(b.Hue, 70, 40, 90 * b.Life);
            Ellipse(b.Pos.X, b.Pos.Y, 28, 28);
            NoStroke();
            Fill(b.Hue, 20, 100, 255 * b.Life);
            Text(b.Letter.ToString(), b.Pos.X, b.Pos.Y);
        }

        NoStroke();
        foreach (var s in _sparks)
        {
            Fill(s.Hue, 80, 100, 255 * s.Life);
            Ellipse(s.Pos.X, s.Pos.Y, 4, 4);
        }

        if (_trips > 0)
        {
            Fill(0, 0, 100, 120);
            TextSize(12);
            Text($"minimized {_trips}×", Width - 70, Height - 14);
        }
    }
}

// Flow field in the terminal: particles drift along a vector field drawn
// behind Windows Terminal's text -- and every terminal window gets a field of its own.
//
// Idea from "Vector field with particles" by jcponcemath on OpenProcessing
// (openprocessing.org/sketch/3017881); this is a fresh take written for Dana.
//
// 1. Open one or more Windows Terminal windows and press Run.
// 2. Drag a terminal: the particles lag behind (inertia, -TargetAcceleration)
//    and the field twists with the speed (TargetVelocity). Let go: it untwists.
// 3. Run a command that fails (try:  cmd /c exit 3): the field becomes a red
//    storm and shows the exit code. A command that works calms it with a cyan
//    pulse. dana-signal reset draws a new field.
//    Commands need the PowerShell snippet once: run ShellSignals.InstallForPowerShell()
//    (or use the tray menu of the exported app), then open a new terminal.
public class TerminalFlowField : AttachedSketch
{
    const int Tail = 10;  // positions kept per particle for its trail

    sealed class Particle
    {
        public float X, Y, VX, VY, Age, Life;
        public readonly float[] TX = new float[Tail], TY = new float[Tail];
        public int Head;
    }

    readonly List<Particle> _particles = new();

    // Trails are drawn in batches: every segment of the same color and alpha goes
    // into one shape (BeginShape(ShapeKind.Lines) = one Skia call) instead of a
    // Stroke() + Line() per segment, thousands of calls a frame otherwise.
    const int HueSteps = 24, AlphaSteps = 8;   // 15° hue steps, 8 alpha levels
    readonly List<float>[] _batches = Enumerable.Range(0, HueSteps * (AlphaSteps + 1)).Select(_ => new List<float>()).ToArray();
    float _a, _b, _swirl, _phase;   // the field's shape: different per window (each instance has its own seed)
    float _storm;                   // 1 right after a failed command, fades out
    float _calm;                    // 1 right after a command that worked
    float _twist;                   // follows how fast the window is dragged
    float _ringRadius = -1, _ringHue;

    public override void Settings() =>
        Attach(WindowTarget.Terminal, mode: AttachMode.EachWindow);

    public override void Setup()
    {
        ListenToShell();
        ColorMode(ColorSpaceMode.HSB, 360, 100, 100, 255);
        TextAlign(TextAlignH.Right, TextAlignV.Bottom);
        NewField();
        FitParticles();
    }

    public override void WindowResized() => FitParticles();

    void NewField()
    {
        _a = Random(1.5f, 3.5f);
        _b = Random(1.5f, 3.5f);
        _swirl = Random(-0.8f, 0.8f);
        _phase = Random(TWO_PI);
    }

    void FitParticles()
    {
        int wanted = Constrain(Width * Height / 900, 150, 1000);
        while (_particles.Count < wanted)
            _particles.Add(Respawn(new Particle()));
        if (_particles.Count > wanted)
            _particles.RemoveRange(wanted, _particles.Count - wanted);
    }

    Particle Respawn(Particle p)
    {
        p.X = Random(Width);
        p.Y = Random(Height);
        p.VX = p.VY = 0;
        p.Age = 0;
        p.Life = Random(2, 6);
        for (int i = 0; i < Tail; i++) { p.TX[i] = p.X; p.TY[i] = p.Y; }
        return p;
    }

    // --- the vector field -------------------------------------------------------

    (float X, float Y) Field(float x, float y, float t)
    {
        // Smooth swirls in coordinates centred on the window, scaled to it.
        float s = Math.Max(1, Math.Min(Width, Height));
        float u = (x - Width / 2f) / s * 2, v = (y - Height / 2f) / s * 2;
        float fx = Sin(_a * v + _phase + t * 0.2f) - _swirl * v;
        float fy = Cos(_b * u - _phase + t * 0.15f) + _swirl * u;

        // After an error: noisy turbulence on top.
        if (_storm > 0)
        {
            float n = Noise(x * 0.008f + t * 0.4f, y * 0.008f) * TWO_PI * 3;
            fx += Cos(n) * 2.5f * _storm;
            fy += Sin(n) * 2.5f * _storm;
        }

        // While the window is dragged: the whole field turns.
        float c = Cos(_twist), sn = Sin(_twist);
        return (fx * c - fy * sn, fx * sn + fy * c);
    }

    // --- the shell ----------------------------------------------------------------

    public override void CommandFinished()
    {
        if (LastCommandOk)
        {
            _calm = 1;
            Ring(170);
        }
        else
        {
            _storm = 1;
            Ring(5);
            foreach (var p in _particles)   // a kick in every direction
            {
                float a = Random(TWO_PI);
                p.VX += Cos(a) * 250;
                p.VY += Sin(a) * 250;
            }
        }
    }

    public override void OnShellSignal(string name)
    {
        if (name == "reset")
        {
            NewField();
            foreach (var p in _particles) Respawn(p);
            Ring(270);
        }
    }

    void Ring(float hue)
    {
        _ringRadius = 0;
        _ringHue = hue;
    }

    // --- every frame ----------------------------------------------------------------

    void DrawBatches()
    {
        // StrokeWeight(0) is a hairline: exactly one physical pixel at any DPI,
        // and Skia's fastest antialiased line -- about 10x cheaper than 1.6 px
        // with round ends (the trails are thousands of tiny segments).
        StrokeWeight(0);
        NoFill();
        for (int b = 0; b < _batches.Length; b++)
        {
            var batch = _batches[b];
            if (batch.Count == 0) continue;
            int hueStep = b / (AlphaSteps + 1), alphaStep = b % (AlphaSteps + 1);
            Stroke(hueStep * (360f / HueSteps), 65 + 35 * _storm, 100, 255f * alphaStep / AlphaSteps);
            BeginShape(ShapeKind.Lines);
            for (int i = 0; i < batch.Count; i += 2)
                Vertex(batch[i], batch[i + 1]);
            EndShape();
            batch.Clear();
        }
    }

    public override void Draw()
    {
        Clear(); // transparent: the terminal stays visible underneath
        float dt = DeltaTime;   // real seconds: same speed at 60 fps or in eco mode
        float t = Millis() / 1000f;

        _storm = Math.Max(0, _storm - dt / 2.5f);
        _calm = Math.Max(0, _calm - dt / 1.5f);
        _twist = Lerp(_twist, Constrain(TargetVelocity.X / 1500f, -1.3f, 1.3f), Math.Min(1, dt * 4));
        var push = TargetAcceleration;
        float speed = 110 * (1 + 1.5f * _storm) * (1 - 0.5f * _calm);
        float follow = Math.Min(1, dt * 3);

        foreach (var p in _particles)
        {
            var (fx, fy) = Field(p.X, p.Y, t);
            // Follow the field, and feel the window's motion the other way round.
            p.VX += (fx * speed - p.VX) * follow - push.X * 0.15f * dt;
            p.VY += (fy * speed - p.VY) * follow - push.Y * 0.15f * dt;
            p.X += p.VX * dt;
            p.Y += p.VY * dt;
            p.Age += dt;
            p.Head = (p.Head + 1) % Tail;
            p.TX[p.Head] = p.X;
            p.TY[p.Head] = p.Y;

            if (p.Age > p.Life || p.X < -20 || p.Y < -20 || p.X > Width + 20 || p.Y > Height + 20)
            {
                Respawn(p);
                continue;
            }

            // Blue-violet by direction; red in a storm; cyan when calm.
            float hue = 190 + 50 * Sin(Atan2(p.VY, p.VX));
            hue = Lerp(hue, 5, _storm);
            hue = Lerp(hue, 175, _calm * (1 - _storm));
            float fade = Math.Min(1, Math.Min(p.Age * 2, (p.Life - p.Age) * 2));
            int hueStep = ((int)Math.Round(hue / (360f / HueSteps)) % HueSteps + HueSteps) % HueSteps;
            for (int k = 1; k < Tail; k++)   // oldest segment first, fainter
            {
                int alphaStep = (int)Math.Round(fade * k / Tail * AlphaSteps);
                if (alphaStep == 0) continue;
                int i0 = (p.Head + k) % Tail, i1 = (p.Head + k + 1) % Tail;
                var batch = _batches[hueStep * (AlphaSteps + 1) + alphaStep];
                batch.Add(p.TX[i0]); batch.Add(p.TY[i0]); batch.Add(p.TX[i1]); batch.Add(p.TY[i1]);
            }
        }
        DrawBatches();

        // The pulse after a command, from the centre outwards.
        if (_ringRadius >= 0)
        {
            float max = Dist(0, 0, Width, Height) / 2;
            _ringRadius += 700 * dt;
            Stroke(_ringHue, 80, 100, 220 * (1 - _ringRadius / max));
            StrokeWeight(3);
            Ellipse(Width / 2f, Height / 2f, _ringRadius * 2, _ringRadius * 2);
            if (_ringRadius > max) _ringRadius = -1;
        }

        if (_storm > 0)
        {
            NoStroke();
            Fill(5, 80, 100, 255 * _storm);
            TextSize(28);
            Text($"exit {LastExitCode}", Width - 16, Height - 12);
        }
    }
}

// Cloth on the terminal: the whole Windows Terminal window is covered by a
// sheet of see-through cloth hanging from its top edge. Move the window and
// the cloth swings, ripples and folds.
//
// Idea from "Cloth!!" by Millie on OpenProcessing (openprocessing.org/sketch/2999200);
// its code is hidden, so this is written from scratch for Dana: a grid of
// points joined by sticks (Verlet integration), pinned along the top, drawn
// as one shaded mesh plus a fine weave.
//
// 1. Open Windows Terminal and press Run.
// 2. Drag the terminal: the cloth lags behind and swings (-TargetAcceleration).
//    Shake it hard and it flaps.
// 3. Move the mouse through it to push it; click to cut a hole (the click
//    still reaches the terminal). Too much stretch tears it too.
// 4. A command that fails rips a hole and flashes red; one that works sends a
//    gust of wind through it. dana-signal reset hangs a new cloth.
public class TerminalCloth : AttachedSketch
{
    sealed class Point
    {
        public float X, Y, OldX, OldY, RestX;
        public bool Pinned;
    }

    sealed class Stick
    {
        public Point A, B;
        public float Length;
        public bool Broken;
    }

    const float Gravity = 500;       // px/s²
    const float Inertia = 0.7f;      // how much the window's motion moves the cloth
    const float TearStretch = 3f;    // a stick breaks past this many times its length

    readonly List<Point> _points = new();
    readonly List<Stick> _sticks = new();
    Stick[] _right = new Stick[0], _down = new Stick[0];   // the stick to the right of / below each point
    int _cols, _rows;
    float _redness;                  // 1 right after a failed command
    float _gust;                     // 1 right after a command that worked

    public override void Settings() => Attach(WindowTarget.Terminal);

    public override void Setup()
    {
        ListenToShell();
        ListenToTargetMouse();
        Hang();
    }

    public override void WindowResized() => Hang();

    // A cloth exactly the size of the window, its top row pinned to the top edge.
    void Hang()
    {
        _points.Clear();
        _sticks.Clear();
        _cols = Constrain(Width / 28, 12, 60) + 1;
        _rows = Constrain(Height / 28, 8, 40) + 1;
        float sx = Width / (float)(_cols - 1), sy = Height / (float)(_rows - 1);
        _right = new Stick[_cols * _rows];
        _down = new Stick[_cols * _rows];
        for (int r = 0; r < _rows; r++)
            for (int c = 0; c < _cols; c++)
            {
                float x = c * sx, y = r * sy;
                _points.Add(new Point { X = x, Y = y, OldX = x, OldY = y, RestX = x, Pinned = r == 0 });
            }
        for (int r = 0; r < _rows; r++)
            for (int c = 0; c < _cols; c++)
            {
                int i = r * _cols + c;
                if (c + 1 < _cols) _right[i] = Join(_points[i], _points[i + 1], sx);
                if (r + 1 < _rows) _down[i] = Join(_points[i], _points[i + _cols], sy);
            }
    }

    Stick Join(Point a, Point b, float length)
    {
        var s = new Stick { A = a, B = b, Length = length };
        _sticks.Add(s);
        return s;
    }

    // --- input ------------------------------------------------------------------

    public override void MousePressed() => Cut(MouseX, MouseY, 22);

    public override void CommandFinished()
    {
        if (LastCommandOk) { _gust = 1; return; }
        _redness = 1;
        Cut(Random(Width * 0.2f, Width * 0.8f), Random(Height * 0.3f, Height * 0.7f), Math.Min(Width, Height) * 0.12f);
    }

    public override void OnShellSignal(string name)
    {
        if (name == "reset") Hang();
    }

    void Cut(float x, float y, float radius)
    {
        foreach (var s in _sticks)
        {
            float mx = (s.A.X + s.B.X) / 2, my = (s.A.Y + s.B.Y) / 2;
            if (Dist(mx, my, x, y) < radius) s.Broken = true;
        }
    }

    // --- every frame ----------------------------------------------------------------

    public override void Draw()
    {
        Clear();
        float dt = Math.Min(DeltaTime, 1 / 30f);
        float t = Millis() / 1000f;
        var a = TargetAcceleration;
        _redness = Math.Max(0, _redness - dt / 2);
        _gust = Math.Max(0, _gust - dt / 1.5f);

        // A jerk of the window is felt, but capped: a real drag shouldn't throw the cloth off.
        float ax = Constrain(-a.X * Inertia, -5000, 5000), ay = Constrain(-a.Y * Inertia, -5000, 5000);
        Simulate(dt, t, ax, Gravity + ay);
        DrawMesh();
        DrawWeave();
    }

    void Simulate(float dt, float t, float ax, float ay)
    {
        bool mouseInside = MouseX >= 0 && MouseX < Width && MouseY >= 0 && MouseY < Height;
        float gustX = _gust * 2500;

        // Verlet: the velocity is just "where it was" vs "where it is".
        foreach (var p in _points)
        {
            if (p.Pinned) continue;
            float vx = (p.X - p.OldX) * 0.985f, vy = (p.Y - p.OldY) * 0.985f;
            // A light breeze so the cloth is never perfectly still, plus the gust.
            float breeze = (Noise(p.Y * 0.004f, t * 0.4f) - 0.5f) * 90 + gustX * Noise(p.Y * 0.01f, t * 3);
            p.OldX = p.X;
            p.OldY = p.Y;
            p.X += vx + (ax + breeze) * dt * dt;
            p.Y += vy + ay * dt * dt;

            // The mouse pushes the cloth away (no click needed: MouseX/MouseY follow the cursor).
            if (mouseInside)
            {
                float d = Dist(p.X, p.Y, MouseX, MouseY);
                if (d < 45 && d > 0.01f)
                {
                    p.X += (p.X - MouseX) / d * (45 - d) * 0.25f;
                    p.Y += (p.Y - MouseY) / d * (45 - d) * 0.25f;
                }
            }
        }

        // Sticks pull their two points back to their length, a few times per frame.
        for (int iteration = 0; iteration < 6; iteration++)
            foreach (var s in _sticks)
            {
                if (s.Broken) continue;
                float dx = s.B.X - s.A.X, dy = s.B.Y - s.A.Y;
                float d = Math.Max(0.001f, Sqrt(dx * dx + dy * dy));
                if (d > s.Length * TearStretch) { s.Broken = true; continue; }
                // Cloth resists stretching fully and squeezing only a little, so it can fold.
                float stiffness = d > s.Length ? 1 : 0.3f;
                float push = (d - s.Length) / d * (s.A.Pinned || s.B.Pinned ? 1 : 0.5f) * stiffness;
                if (!s.A.Pinned) { s.A.X += dx * push; s.A.Y += dy * push; }
                if (!s.B.Pinned) { s.B.X -= dx * push; s.B.Y -= dy * push; }
            }

        // Torn-off pieces that fell away stop below the window.
        foreach (var p in _points)
            if (p.Y > Height + 300) { p.Y = p.OldY = Height + 300; p.OldX = p.X; }
    }

    // --- drawing --------------------------------------------------------------------

    // The cloth itself: every quad whose four sides hold, filled with a shade for
    // how the cloth bends there -- folds darker, stretched or swung parts lighter.
    // Quads of the same shade go in one shape (one contour each): a handful of
    // draw calls for the whole window instead of one per quad.
    const int Shades = 6;
    readonly List<int>[] _byShade = Enumerable.Range(0, Shades).Select(_ => new List<int>()).ToArray();

    void DrawMesh()
    {
        foreach (var list in _byShade) list.Clear();
        for (int r = 0; r < _rows - 1; r++)
            for (int c = 0; c < _cols - 1; c++)
            {
                int i = r * _cols + c;
                if (_right[i].Broken || _down[i].Broken || _right[i + _cols].Broken || _down[i + 1].Broken) continue;
                _byShade[(int)(Light(i) * (Shades - 0.01f))].Add(i);
            }

        // Without antialiasing: much faster for shapes this big, and neighbouring
        // quads meet exactly (no faint seams). The weave drawn on top hides the edges.
        NoSmooth();
        NoStroke();
        for (int k = 0; k < Shades; k++)
        {
            if (_byShade[k].Count == 0) continue;
            float shade = k / (float)(Shades - 1);
            Fill(Lerp(60, 150, shade) + 150 * _redness,
                 Lerp(80, 190, shade) * (1 - 0.6f * _redness),
                 Lerp(150, 255, shade) * (1 - 0.5f * _redness),
                 Lerp(26, 62, Math.Abs(shade - 0.5f) * 2) + 45 * _redness);
            BeginShape();
            foreach (int i in _byShade[k])
            {
                BeginContour();
                Vertex(_points[i].X, _points[i].Y);
                Vertex(_points[i + 1].X, _points[i + 1].Y);
                Vertex(_points[i + _cols + 1].X, _points[i + _cols + 1].Y);
                Vertex(_points[i + _cols].X, _points[i + _cols].Y);
                EndContour();
            }
            EndShape();
        }
        Smooth();
    }

    // 0 (a fold) to 1 (stretched or swung out) for the quad at point i.
    float Light(int i)
    {
        Point a = _points[i], b = _points[i + 1], d = _points[i + _cols];
        float span = Dist(a.X, a.Y, b.X, b.Y) / _right[i].Length;              // < 1 where it folds
        float slant = ((d.X - a.X) + (a.X - a.RestX) * 0.15f) / _down[i].Length;  // swinging sideways
        return Constrain(0.5f + (span - 1) * 2.5f + slant * 0.6f, 0, 1);
    }

    // The weave: every stick as a hairline (Skia's fastest line), one shape per
    // color; the stretched ones, warm, go in a second shape on top.
    readonly List<Stick> _stretched = new();

    void DrawWeave()
    {
        StrokeWeight(0);
        Stroke(170 + 85 * _redness, 200 - 120 * _redness, 255 - 150 * _redness, 55);
        _stretched.Clear();
        BeginShape(ShapeKind.Lines);
        foreach (var s in _sticks)
        {
            if (s.Broken) continue;
            float dx = s.B.X - s.A.X, dy = s.B.Y - s.A.Y;
            if (dx * dx + dy * dy > s.Length * s.Length * 1.69f) { _stretched.Add(s); continue; }   // over 1.3x its length
            Vertex(s.A.X, s.A.Y);
            Vertex(s.B.X, s.B.Y);
        }
        EndShape();

        Stroke(255, 160 - 100 * _redness, 90 - 60 * _redness, 200);
        BeginShape(ShapeKind.Lines);
        foreach (var s in _stretched)
        {
            Vertex(s.A.X, s.A.Y);
            Vertex(s.B.X, s.B.Y);
        }
        EndShape();

        // The top hem the cloth hangs from.
        Stroke(220, 230, 255, 140);
        StrokeWeight(2);
        Line(0, 1, Width, 1);
    }
}

// Blobs in the terminal: soft blobs (metaballs) float inside Windows Terminal
// like a lava lamp, slosh when you move the window, and melt into each other.
//
// Idea from "Blobules" on OpenProcessing (openprocessing.org/sketch/2993583);
// its code is hidden, so this is written from scratch for Dana.
//
// 1. Open Windows Terminal and press Run.
// 2. Drag or shake the terminal: the blobs are thrown the other way (inertia),
//    bounce off the edges and drift back together.
// 3. Type in the terminal: each key drops a small blob that swims to the others
//    and merges; Backspace takes one away. The cursor pulls them towards it.
// 4. A command that fails blows them apart into red droplets; after a moment
//    they find each other and melt back together. One that works makes them pulse.
//
// How it's drawn: a "field" adds up every blob's influence on a grid; where
// it's over a threshold you're inside a blob. Marching squares turns each grid
// cell into the exact piece of blob it holds: those pieces are filled as one
// mesh (shaded smoothly by the field, so blobs look round), a soft glossy
// highlight goes on top, and the pieces' edges are the outline.
public class TerminalBlobs : AttachedSketch
{
    sealed class Blob { public float X, Y, VX, VY, R, Loner; }   // Loner: seconds it won't merge

    const float Cell = 8;           // grid size in pixels: smaller = smoother and slower
    const float Threshold = 1;
    const int MaxBlobs = 40;

    readonly List<Blob> _blobs = new();
    float[] _field = new float[0];
    int _cols, _rows;
    float _boil;                    // 1 right after a failed command, fades
    float _apart;                   // seconds left before split blobs may merge again
    float _pulse;                   // 1 right after a command that worked, fades
    float _hue = 175;               // the blobs' hue now (eases to red and back)

    public override void Settings() => Attach(WindowTarget.Terminal);

    public override void Setup()
    {
        ListenToShell();
        ListenToTargetKeys();
        ColorMode(ColorSpaceMode.HSB, 360, 100, 100, 255);
        WindowResized();
        float r = BaseRadius();
        for (int i = 0; i < 4; i++)
            AddBlob(Width * Random(0.3f, 0.7f), Height * Random(0.35f, 0.65f), r * Random(0.7f, 1.1f), Random(-80, 80), Random(-80, 80));
    }

    float BaseRadius() => Math.Min(Width, Height) * 0.11f;

    public override void WindowResized()
    {
        _cols = (int)(Width / Cell) + 2;
        _rows = (int)(Height / Cell) + 2;
        _field = new float[_cols * _rows];
    }

    Blob? AddBlob(float x, float y, float r, float vx, float vy)
    {
        if (_blobs.Count >= MaxBlobs) return null;
        var b = new Blob { X = x, Y = y, R = r, VX = vx, VY = vy };
        _blobs.Add(b);
        return b;
    }

    // Lava lamp: now and then a big blob lets a droplet go, which drifts off and comes back.
    void Bud()
    {
        var big = _blobs.MaxBy(b => b.R)!;
        if (big.R < BaseRadius() * 0.9f || Random(1) > DeltaTime / 2.5f) return;
        float r = big.R * Random(0.3f, 0.45f);
        big.R = Sqrt(big.R * big.R - r * r);
        float angle = Random(TWO_PI);
        var drop = AddBlob(big.X + Cos(angle) * big.R, big.Y + Sin(angle) * big.R, r,
                           big.VX + Cos(angle) * 260, big.VY + Sin(angle) * 260);
        if (drop != null) drop.Loner = Random(1.5f, 3.5f);
    }

    // --- input ------------------------------------------------------------------

    public override void KeyTyped()
    {
        if (Key == BACKSPACE)
        {
            if (_blobs.Count > 1) _blobs.Remove(_blobs.MinBy(b => b.R)!);
        }
        else
            AddBlob(Random(Width * 0.1f, Width * 0.9f), Height * 0.05f, BaseRadius() * Random(0.3f, 0.45f), Random(-50, 50), Random(100, 250));
    }

    public override void CommandFinished()
    {
        if (LastCommandOk) { _pulse = 1; return; }

        // Blow every blob apart into droplets flying outwards.
        _boil = 1;
        _apart = 1.4f;
        var old = _blobs.ToList();
        _blobs.Clear();
        foreach (var b in old)
        {
            int pieces = b.R > BaseRadius() * 0.6f ? 4 : 2;
            float r = b.R / Sqrt(pieces);   // same total area
            for (int i = 0; i < pieces; i++)
            {
                float angle = TWO_PI * i / pieces + Random(-0.5f, 0.5f);
                float speed = Random(500, 950);
                AddBlob(b.X + Cos(angle) * r * 0.5f, b.Y + Sin(angle) * r * 0.5f, r,
                        b.VX + Cos(angle) * speed, b.VY + Sin(angle) * speed);
            }
        }
    }

    // --- every frame ----------------------------------------------------------------

    public override void Draw()
    {
        Clear();
        float dt = Math.Min(DeltaTime, 1 / 30f);
        _boil = Math.Max(0, _boil - dt / 2.5f);
        _pulse = Math.Max(0, _pulse - dt * 1.5f);
        _apart = Math.Max(0, _apart - dt);
        // Teal, and red (360) after a failed command: easing through blue and magenta, never green.
        _hue = Lerp(_hue, _boil > 0.05f ? 360 : 175, Math.Min(1, dt * 3));

        Bud();
        Move(dt);
        Merge();
        ComputeField();
        DrawFill();
        DrawShine();
        DrawOutline();
    }

    void Move(float dt)
    {
        var a = TargetAcceleration;
        float t = Millis() / 1000f;

        // Where the blobs gather: their center of mass (weighted by area).
        float cx = 0, cy = 0, mass = 0;
        foreach (var b in _blobs) { float m = b.R * b.R; cx += b.X * m; cy += b.Y * m; mass += m; }
        cx /= mass; cy /= mass;
        float cohesion = _apart > 0 ? 0 : 2.2f;   // off while freshly split, so they really fly apart
        bool mouseInside = MouseX >= 0 && MouseX < Width && MouseY >= 0 && MouseY < Height;

        for (int i = 0; i < _blobs.Count; i++)
        {
            var b = _blobs[i];
            b.Loner = Math.Max(0, b.Loner - dt);
            // The window's motion: the blob keeps going while the window moves under it.
            b.VX += -a.X * 0.9f * dt;
            b.VY += -a.Y * 0.9f * dt;
            // Lava lamp: a gentle wander, a little gravity, and the pull of the group.
            b.VX += (Noise(i * 7.1f, t * 0.3f) - 0.5f) * 220 * dt + (cx - b.X) * (b.Loner > 0 ? 0 : cohesion) * dt;
            b.VY += (Noise(i * 3.7f + 50, t * 0.3f) - 0.5f) * 220 * dt + (cy - b.Y) * (b.Loner > 0 ? 0 : cohesion) * dt + 25 * dt;
            if (mouseInside)
            {
                float dx = MouseX - b.X, dy = MouseY - b.Y, d = Math.Max(40, Sqrt(dx * dx + dy * dy));
                b.VX += dx / d * 260 * dt;
                b.VY += dy / d * 260 * dt;
            }
            if (_boil > 0)
            {
                b.VX += Random(-1, 1) * 600 * _boil * dt;
                b.VY += Random(-1, 1) * 600 * _boil * dt;
            }

            float drag = 1 - Math.Min(1, dt * 0.9f);
            b.VX = Constrain(b.VX * drag, -2500, 2500);
            b.VY = Constrain(b.VY * drag, -2500, 2500);
            b.X += b.VX * dt;
            b.Y += b.VY * dt;

            float edge = b.R * 0.6f;
            if (b.X < edge) { b.X = edge; b.VX = Math.Abs(b.VX) * 0.8f; }
            if (b.X > Width - edge) { b.X = Width - edge; b.VX = -Math.Abs(b.VX) * 0.8f; }
            if (b.Y < edge) { b.Y = edge; b.VY = Math.Abs(b.VY) * 0.8f; }
            if (b.Y > Height - edge) { b.Y = Height - edge; b.VY = -Math.Abs(b.VY) * 0.8f; }
        }
    }

    // Two blobs whose centers come close become one (same area, same momentum).
    void Merge()
    {
        if (_apart > 0) return;
        for (int i = 0; i < _blobs.Count; i++)
            for (int j = _blobs.Count - 1; j > i; j--)
            {
                Blob a = _blobs[i], b = _blobs[j];
                if (a.Loner > 0 || b.Loner > 0) continue;
                if (Dist(a.X, a.Y, b.X, b.Y) > (a.R + b.R) * 0.45f) continue;
                float ma = a.R * a.R, mb = b.R * b.R, m = ma + mb;
                a.X = (a.X * ma + b.X * mb) / m;
                a.Y = (a.Y * ma + b.Y * mb) / m;
                a.VX = (a.VX * ma + b.VX * mb) / m;
                a.VY = (a.VY * ma + b.VY * mb) / m;
                a.R = Sqrt(m);
                _blobs.RemoveAt(j);
            }
    }

    // The field: sum of r² / distance² from every blob, at each grid corner.
    void ComputeField()
    {
        float grow = 1 + 0.25f * Sin(_pulse * PI);   // a command that worked: one soft pulse
        for (int j = 0; j < _rows; j++)
            for (int i = 0; i < _cols; i++)
            {
                float x = i * Cell, y = j * Cell, sum = 0;
                foreach (var b in _blobs)
                {
                    float dx = x - b.X, dy = y - b.Y, r = b.R * grow;
                    sum += r * r / (dx * dx + dy * dy + 1);
                }
                _field[j * _cols + i] = sum;
            }
    }

    float F(int i, int j) => _field[j * _cols + i];

    // Where the field crosses the threshold between two corners (linear interpolation).
    float Cross(float a, float b) => Constrain((Threshold - a) / (b - a), 0, 1);

    // --- the fill: every cell's piece of blob, as triangles of one mesh -----------

    // Corners of a cell clockwise from top-left, and the field there.
    readonly float[] _cx = new float[4], _cy = new float[4], _cf = new float[4];
    readonly List<(float X, float Y, float F)> _poly = new();

    void DrawFill()
    {
        NoStroke();
        BeginShape(ShapeKind.Triangles);
        for (int j = 0; j < _rows - 1; j++)
            for (int i = 0; i < _cols - 1; i++)
            {
                float x = i * Cell, y = j * Cell;
                _cx[0] = x;        _cy[0] = y;        _cf[0] = F(i, j);
                _cx[1] = x + Cell; _cy[1] = y;        _cf[1] = F(i + 1, j);
                _cx[2] = x + Cell; _cy[2] = y + Cell; _cf[2] = F(i + 1, j + 1);
                _cx[3] = x;        _cy[3] = y + Cell; _cf[3] = F(i, j + 1);

                // Walk the square: keep the corners that are inside, and where an edge
                // crosses the threshold add the crossing. That's the cell's piece of blob.
                _poly.Clear();
                for (int k = 0; k < 4; k++)
                {
                    int n = (k + 1) % 4;
                    bool inK = _cf[k] > Threshold, inN = _cf[n] > Threshold;
                    if (inK) _poly.Add((_cx[k], _cy[k], _cf[k]));
                    if (inK != inN)
                    {
                        float u = Cross(_cf[k], _cf[n]);
                        _poly.Add((Lerp(_cx[k], _cx[n], u), Lerp(_cy[k], _cy[n], u), Threshold));
                    }
                }
                for (int k = 1; k + 1 < _poly.Count; k++)   // a fan of triangles
                {
                    Shade(_poly[0]);
                    Shade(_poly[k]);
                    Shade(_poly[k + 1]);
                }
            }
        EndShape();
    }

    // Each vertex gets its color from the field: see-through at the edge, brighter
    // towards the middle -- the blobs look round and the terminal still reads under them.
    void Shade((float X, float Y, float F) v)
    {
        // depth: 0 at the edge, approaching 1 towards the middle -- never a hard
        // cap, so there's no flat plateau with a jagged rim, just a smooth slope.
        float over = Math.Max(0, v.F - Threshold);
        float depth = over / (over + 1.6f);
        depth = depth * depth * (3 - 2 * depth);   // smoothstep: soft at both ends
        Fill((_hue + 20 * depth) % 360, 75 - 35 * depth + 20 * _boil, 35 + 50 * depth + 10 * _pulse, 60 + 90 * depth);
        Vertex(v.X, v.Y);
    }

    // A soft glossy highlight on every blob, up and to the left, like light on gel:
    // a few stacked translucent ellipses make a smooth radial falloff.
    void DrawShine()
    {
        NoStroke();
        foreach (var b in _blobs)
        {
            float x = b.X - b.R * 0.28f, y = b.Y - b.R * 0.32f;
            for (int k = 0; k < 14; k++)
            {
                float u = k / 13f;                      // 0 = widest and faintest, 1 = smallest
                Fill(_hue % 360, 25 * (1 - u), 100, 6 + 5 * u);
                float w = b.R * Lerp(0.75f, 0.12f, u);
                Ellipse(x, y, w * 1.25f, w);
            }
        }
    }

    // --- the outline: where the field crosses the threshold, all in one shape ---

    void DrawOutline()
    {
        Stroke(_hue % 360, 45 + 40 * _boil, 100, 235);
        StrokeWeight(1.6f);
        BeginShape(ShapeKind.Lines);
        for (int j = 0; j < _rows - 1; j++)
            for (int i = 0; i < _cols - 1; i++)
            {
                float tl = F(i, j), tr = F(i + 1, j), br = F(i + 1, j + 1), bl = F(i, j + 1);
                int code = (tl > Threshold ? 8 : 0) | (tr > Threshold ? 4 : 0) | (br > Threshold ? 2 : 0) | (bl > Threshold ? 1 : 0);
                if (code == 0 || code == 15) continue;

                float x = i * Cell, y = j * Cell;
                // The four edge crossings (top, right, bottom, left).
                float tx = x + Cross(tl, tr) * Cell, ty = y;
                float rx = x + Cell, ry = y + Cross(tr, br) * Cell;
                float bx = x + Cross(bl, br) * Cell, by = y + Cell;
                float lx = x, ly = y + Cross(tl, bl) * Cell;

                switch (code)
                {
                    case 1: case 14: Seg(lx, ly, bx, by); break;
                    case 2: case 13: Seg(bx, by, rx, ry); break;
                    case 3: case 12: Seg(lx, ly, rx, ry); break;
                    case 4: case 11: Seg(tx, ty, rx, ry); break;
                    case 5: Seg(lx, ly, tx, ty); Seg(bx, by, rx, ry); break;
                    case 6: case 9: Seg(tx, ty, bx, by); break;
                    case 7: case 8: Seg(lx, ly, tx, ty); break;
                    case 10: Seg(lx, ly, bx, by); Seg(tx, ty, rx, ry); break;
                }
            }
        EndShape();
    }

    void Seg(float x1, float y1, float x2, float y2)
    {
        Vertex(x1, y1);
        Vertex(x2, y2);
    }
}

// Wobbly functions under the terminal's text: a stack of glowing ribbons along
// the bottom of every Windows Terminal window. Each line is a wobbly function
// (a sum of sines) and also a string you can pluck: the window's motion, your
// keys, the cursor and your commands all send waves along it.
//
// Idea from "Class 8/31" by Tyler Alexander on OpenProcessing
// (openprocessing.org/sketch/2998495), made for Genuary 2024's "wobbly
// function day"; its code is hidden, so this is written from scratch for Dana.
//
// 1. Open one or more Windows Terminal windows and press Run.
// 2. Drag a terminal: the ribbons slosh the other way (each layer a little
//    later than the one above) and settle. Dragging sideways slides the waves.
// 3. Type in the terminal: every key plucks the strings; Enter plucks hard.
//    The cursor pushes them aside like a finger in water.
// 4. A command that fails snaps them into a jagged red tangle; one that works
//    sends a calm wave from left to right.
public class TerminalWobble : AttachedSketch
{
    const int Curves = 13;
    const int Steps = 96;           // points per curve

    // Each curve is also a string: a height and a speed per point (a 1-D wave equation).
    readonly float[,] _wave = new float[Curves, Steps + 1];
    readonly float[,] _speed = new float[Curves, Steps + 1];
    // Each curve hangs on a spring that the window's motion shakes (lower = later).
    readonly float[] _offset = new float[Curves], _offsetSpeed = new float[Curves];
    float _slide;                   // horizontal shift of the waves, from dragging sideways
    float _jagged;                  // 1 right after a failed command
    float _seed;

    public override void Settings() =>
        Attach(WindowTarget.Terminal, mode: AttachMode.EachWindow);

    public override void Setup()
    {
        ListenToShell();
        ListenToTargetKeys();
        ColorMode(ColorSpaceMode.HSB, 360, 100, 100, 255);
        _seed = Random(1000);   // each window's instance has its own seed: its own curves
    }

    // --- input ------------------------------------------------------------------

    public override void KeyTyped()
    {
        bool enter = Key == ENTER || Key == RETURN;
        Pluck(Random(0.05f, 0.95f), enter ? 40 : 14, enter ? Curves : 5);
    }

    public override void CommandFinished()
    {
        if (LastCommandOk)
        {
            for (int c = 0; c < Curves; c++) _speed[c, 2] -= 900;   // a wave from the left edge
            return;
        }
        _jagged = 1;
        for (int c = 0; c < Curves; c++)
            for (int s = 1; s < Steps; s++)
                _speed[c, s] += Random(-400, 400);
    }

    // Pull the strings at u (0-1 along the width): the top `count` curves, each a bit less.
    void Pluck(float u, float strength, int count)
    {
        int at = (int)(u * Steps);
        for (int c = 0; c < count && c < Curves; c++)
            for (int s = Math.Max(1, at - 4); s <= Math.Min(Steps - 1, at + 4); s++)
                _speed[c, s] -= strength * 20 * (1 - Math.Abs(s - at) / 5f) * (1 - c / (float)(count + 1));
    }

    // --- every frame ----------------------------------------------------------------

    public override void Draw()
    {
        Clear();
        float dt = Math.Min(DeltaTime, 1 / 30f);
        float t = Millis() / 1000f;
        _jagged = Math.Max(0, _jagged - dt / 2);

        Shake(dt);
        Ripple(dt);

        float band = Height * 0.4f;                   // the ribbons live in the bottom 40 %
        float top = Height - band;
        float amplitude = band / Curves * 1.3f;

        // Every curve's points first, so the ribbons and the lines share them.
        var pts = new float[Curves, Steps + 1];
        for (int c = 0; c < Curves; c++)
        {
            float baseY = top + (c + 0.7f) * band / Curves + _offset[c];
            for (int s = 0; s <= Steps; s++)
            {
                float u = s / (float)Steps;
                float y = baseY + Wobble(c, u, t) * amplitude + _wave[c, s];
                pts[c, s] = Finger(u * Width, y);
            }
        }

        DrawRibbons(pts);
        DrawLines(pts, t);
    }

    // The window's motion shakes each curve's spring; lower curves are softer, so they lag.
    void Shake(float dt)
    {
        var a = TargetAcceleration;
        _slide += TargetVelocity.X * dt * 0.0025f;
        for (int c = 0; c < Curves; c++)
        {
            float stiffness = Lerp(90, 25, c / (float)(Curves - 1));
            _offsetSpeed[c] += (-a.Y * 0.05f - stiffness * _offset[c] - 4 * _offsetSpeed[c]) * dt;
            _offset[c] = Constrain(_offset[c] + _offsetSpeed[c] * dt, -Height * 0.3f, Height * 0.3f);
        }
    }

    // The strings: each point pulled towards its neighbors, waves travel and fade.
    void Ripple(float dt)
    {
        const float Tension = 2400, Damping = 1.6f;
        for (int c = 0; c < Curves; c++)
        {
            for (int s = 1; s < Steps; s++)
            {
                float pull = (_wave[c, s - 1] + _wave[c, s + 1] - 2 * _wave[c, s]) * Tension;
                _speed[c, s] += (pull - _speed[c, s] * Damping - _wave[c, s] * 6) * dt;
            }
            for (int s = 1; s < Steps; s++)
                _wave[c, s] = Constrain(_wave[c, s] + _speed[c, s] * dt, -200, 200);
        }
    }

    // The wobbly function: a few sines of different speeds, plus noise when jagged.
    float Wobble(int curve, float u, float t)
    {
        float k = curve * 0.37f + _seed;
        float v = u * 6 + _slide;
        float y = Sin(v * (0.9f + 0.15f * (curve % 5)) + t * (0.5f + 0.05f * curve) + k)
                + 0.55f * Sin(v * (2.1f + 0.1f * (curve % 3)) - t * 1.1f + k * 1.7f)
                + 0.3f * Sin(v * 4.3f + t * 1.9f + k * 0.3f) * Sin(t * 0.37f + curve);
        if (_jagged > 0)
            y += (Noise(u * 30 + k, t * 5) - 0.5f) * 7 * _jagged;
        return y;
    }

    // The cursor pushes the lines away from it, like a finger in water.
    float Finger(float x, float y)
    {
        if (MouseX < 0 || MouseX >= Width || MouseY < 0 || MouseY >= Height) return y;
        float dx = (x - MouseX) / 90f, dy = y - MouseY;
        float near = Exp(-dx * dx) * Exp(-dy * dy / (70f * 70f));
        return y + dy / (Math.Abs(dy) + 25) * 45 * near;   // smooth on both sides of the cursor
    }

    // Teal to violet down the stack; a failed command turns it red (going on through magenta, not back through green).
    float Hue(int c, float u) => Lerp(Lerp(185, 300, c / (float)Curves) + 25 * Sin(u * 3 + c * 0.2f), 360, _jagged) % 360;

    // Between each curve and the next, a see-through ribbon: one polygon per band
    // (along one curve, back along the next), alternating light and dark.
    void DrawRibbons(float[,] pts)
    {
        NoSmooth();   // faster for big shapes; the lines drawn on top hide the edges
        NoStroke();
        for (int c = 0; c < Curves - 1; c++)
        {
            Fill(Hue(c, 0.5f), 75 + 25 * _jagged, c % 2 == 0 ? 95 : 55, 34 + 30 * _jagged);
            BeginShape();
            for (int s = 0; s <= Steps; s++)
                Vertex(s * Width / (float)Steps, pts[c, s]);
            for (int s = Steps; s >= 0; s--)
                Vertex(s * Width / (float)Steps, pts[c + 1, s]);
            EndShape(true);
        }
        Smooth();
    }

    // The lines themselves, brighter where the light passes along the stack.
    void DrawLines(float[,] pts, float t)
    {
        NoFill();
        StrokeWeight(1.3f);
        for (int c = 0; c < Curves; c++)
        {
            float bright = 0.6f + 0.4f * Sin(t * 1.3f + c * 0.5f);
            Stroke(Hue(c, 0.5f), 35 + 50 * _jagged, 100, 140 + 100 * bright);
            BeginShape();
            for (int s = 0; s <= Steps; s++)
                Vertex(s * Width / (float)Steps, pts[c, s]);
            EndShape();
        }
    }
}

// A morphing blob in the terminal, the way CSS does it: a box whose eight
// border-radius values (four corners, each with a horizontal and a vertical
// radius) are animated between a few keyframes, filled with a gradient,
// slowly turning, with a soft glow. Floating behind Windows Terminal, it also
// feels the window: it lags and stretches when you drag it, leans towards
// the cursor, pulses as you type and changes mood with your commands.
//
// Inspired by "Create Smooth Blob Animation with CSS (No JavaScript)" by
// Code With Nazia (youtube.com/watch?v=eXlzVo90Jr4): border-radius tricks +
// keyframe animations. Written from scratch for Dana.
//
// In CSS it would be:
//   border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%;
//   animation: morph 8s ease-in-out infinite;
// Each corner is a quarter of an ellipse; here it's drawn with BezierVertex.
//
// 1. Open Windows Terminal and press Run.
// 2. Drag the terminal: the blob trails behind, stretches along the motion and
//    morphs faster; let go and it wobbles back into place.
// 3. Type: every key gives it a little pulse. Move the cursor near it: it leans in.
// 4. A command that fails turns it red and makes it quiver; one that works
//    makes it swell in a green-blue flash.
public class TerminalMorphBlob : AttachedSketch
{
    // border-radius keyframes, in % of the box: horizontal radii of the
    // top-left, top-right, bottom-right, bottom-left corners, then the vertical ones.
    readonly float[][] _keyframes =
    {
        new float[] { 60, 40, 30, 70,   60, 30, 70, 40 },
        new float[] { 30, 60, 70, 40,   50, 60, 30, 60 },
        new float[] { 50, 50, 34, 66,   56, 68, 32, 44 },
        new float[] { 70, 30, 52, 48,   38, 52, 48, 62 },
    };
    const float SecondsPerKeyframe = 2.2f;

    float _morph;                   // position in the keyframe cycle (keyframes)
    float _spin;                    // rotation, radians
    float _pulse;                   // a key or a good command: 0..1, fades
    float _anger;                   // a failed command: 1, fades
    float _joy;                     // a command that worked: 1, fades
    float _x, _y, _vx, _vy;         // where the blob is (it trails the window)

    public override void Settings() => Attach(WindowTarget.Terminal);

    public override void Setup()
    {
        ListenToShell();
        ListenToTargetKeys();
        _x = Width * 0.68f;
        _y = Height * 0.5f;
    }

    public override void KeyTyped() => _pulse = Math.Min(1, _pulse + 0.35f);

    public override void CommandFinished()
    {
        if (LastCommandOk) { _joy = 1; _pulse = 1; }
        else _anger = 1;
    }

    public override void Draw()
    {
        Clear();
        float dt = Math.Min(DeltaTime, 1 / 30f);
        _pulse = Math.Max(0, _pulse - dt * 2.5f);
        _anger = Math.Max(0, _anger - dt / 2.5f);
        _joy = Math.Max(0, _joy - dt / 1.5f);

        // --- where it is: a spring towards its home spot, pushed by the window's motion ---
        var a = TargetAcceleration;
        float homeX = Width * 0.68f, homeY = Height * 0.5f;
        bool mouseInside = MouseX >= 0 && MouseX < Width && MouseY >= 0 && MouseY < Height;
        if (mouseInside)
        {
            // Lean towards the cursor, but only so far.
            homeX += Constrain((MouseX - homeX) * 0.15f, -60, 60);
            homeY += Constrain((MouseY - homeY) * 0.15f, -60, 60);
        }
        _vx += (-a.X * 0.35f + (homeX - _x) * 18 - _vx * 4.5f) * dt;
        _vy += (-a.Y * 0.35f + (homeY - _y) * 18 - _vy * 4.5f) * dt;
        _x += _vx * dt;
        _y += _vy * dt;

        // --- the animation: faster while it moves or is upset ---
        float speed = Sqrt(_vx * _vx + _vy * _vy);
        float tempo = 1 + Math.Min(3, speed / 300) + 3 * _anger;
        _morph += dt * tempo / SecondsPerKeyframe;
        _spin += dt * (0.25f + 0.8f * _anger);

        // --- size, squash and stretch along the motion ---
        float size = Math.Min(Width, Height) * 0.5f * (1 + 0.12f * _pulse + 0.15f * _joy);
        float stretch = 1 + Math.Min(0.6f, speed / 1500);
        float heading = speed > 1 ? Atan2(_vy, _vx) : 0;
        float quiver = _anger * 0.06f * Sin(Millis() * 0.05f);

        float[] radii = Radii(_morph);
        PushMatrix();
        Translate(_x, _y);
        Rotate(heading);
        Scale(stretch * (1 + quiver), (1 / stretch) * (1 - quiver));   // stretched along its motion, same area
        Rotate(_spin - heading);

        // Glow: the same shape a few times, bigger and fainter (a CSS box-shadow, by hand).
        NoStroke();
        for (int k = 4; k >= 1; k--)
        {
            Fill(Lerp(150, 255, _anger), Lerp(110, 60, _anger) + 80 * _joy, Lerp(255, 90, _anger), 10);
            Blob(size * (1 + 0.07f * k), size * 0.9f * (1 + 0.07f * k), radii);
        }

        // The blob: a gradient that turns with time, like `background: linear-gradient(...)`.
        float g = size * 0.6f, turn = Millis() / 3000f;
        Color from = Color(Lerp(110, 255, _anger), Lerp(90, 70, _anger) + 120 * _joy, Lerp(255, 60, _anger), 120);
        Color to = Color(Lerp(255, 255, _anger), Lerp(90, 170, _anger) + 60 * _joy, Lerp(200, 40, _anger), 120);
        Fill(255);   // a gradient is tinted by the fill's alpha: start from opaque white
        LinearGradientFill(-Cos(turn) * g, -Sin(turn) * g, Cos(turn) * g, Sin(turn) * g, from, to);
        Blob(size, size * 0.9f, radii);

        // A soft highlight and a crisp rim.
        Fill(255);
        RadialGradientFill(-size * 0.15f, -size * 0.18f, size * 0.35f, Color(255, 255, 255, 60), Color(255, 255, 255, 0));
        Blob(size, size * 0.9f, radii);
        NoFill();
        Stroke(255, 255, 255, 90);
        StrokeWeight(1.2f);
        Blob(size, size * 0.9f, radii);
        PopMatrix();
    }

    // The eight radii at this point of the cycle: ease-in-out between keyframes,
    // like `animation-timing-function: ease-in-out`.
    float[] Radii(float morph)
    {
        int n = _keyframes.Length;
        int i = (int)Math.Floor(morph) % n;
        float u = morph - (float)Math.Floor(morph);
        u = u * u * (3 - 2 * u);
        var from = _keyframes[i];
        var to = _keyframes[(i + 1) % n];
        var r = new float[8];
        for (int k = 0; k < 8; k++) r[k] = Lerp(from[k], to[k], u);
        return r;
    }

    // A w×h box centered on (0, 0) with CSS border-radius `radii` (in %).
    void Blob(float w, float h, float[] radii)
    {
        // Horizontal radii in px, vertical radii in px.
        float tlh = radii[0] / 100 * w, trh = radii[1] / 100 * w, brh = radii[2] / 100 * w, blh = radii[3] / 100 * w;
        float tlv = radii[4] / 100 * h, trv = radii[5] / 100 * h, brv = radii[6] / 100 * h, blv = radii[7] / 100 * h;

        // CSS rule: if two radii on one side add up to more than that side, all
        // radii shrink by the same factor until they fit.
        float f = Math.Min(1, Math.Min(Math.Min(w / (tlh + trh), w / (blh + brh)), Math.Min(h / (tlv + blv), h / (trv + brv))));
        tlh *= f; trh *= f; brh *= f; blh *= f; tlv *= f; trv *= f; brv *= f; blv *= f;

        float l = -w / 2, r = w / 2, t = -h / 2, b = h / 2;
        const float K = 0.5523f;   // how far a cubic Bézier's handles go to draw a quarter ellipse

        BeginShape();
        Vertex(l + tlh, t);
        Vertex(r - trh, t);
        BezierVertex(r - trh + trh * K, t, r, t + trv - trv * K, r, t + trv);   // top-right corner
        Vertex(r, b - brv);
        BezierVertex(r, b - brv + brv * K, r - brh + brh * K, b, r - brh, b);   // bottom-right
        Vertex(l + blh, b);
        BezierVertex(l + blh - blh * K, b, l, b - blv + blv * K, l, b - blv);   // bottom-left
        Vertex(l, t + tlv);
        BezierVertex(l, t + tlv - tlv * K, l + tlh - tlh * K, t, l + tlh, t);   // top-left
        EndShape(true);
    }
}

// nuget: NAudio, 2.2.1
#nullable enable

using System;
using NAudio.Wave;

// Audio-reactive terminal: whatever your computer is playing moves a row of
// 40 glowing blobs along the bottom of Windows Terminal -- low notes on the
// left, high ones on the right. It's the "Audio-reactive: live FFT" sample
// moved onto the terminal: the same capture (WasapiLoopbackCapture: the
// system's output, no microphone) and FFT with log-spaced bands, and the
// same idea that silence sets the blobs free.
//
// 1. Open Windows Terminal, play some music, press Run.
// 2. Each blob rides a stalk from the bottom edge; its height is its band's loudness.
// 3. When the music stops the blobs come loose and float up, drifting; when it
//    starts again they ease back onto their stalks.
// 4. Drag the terminal: the blobs swing on their stalks (inertia).
// 5. A command that fails flings them up in red; one that works sends a wave
//    of light along the row.
// Capture starts in Setup() and stops in OnStop() (Stop, or the window closing).
public class TerminalAudio : AttachedSketch
{
    const int FftSize = 1024;           // must be a power of two
    const int FftLog2 = 10;
    const int Bars = 40;
    const int MinBin = 1;               // skip bin 0 (DC offset)
    const int MaxBin = 400;             // ~18.7 kHz at 48 kHz
    const float Gain = 26f;
    const float Decay = 0.85f;          // per FFT: bars settle instead of flickering
    const float SilenceEnter = 0.06f, SilenceExit = 0.08f;   // hysteresis: no flicker in quiet passages

    // Log-spaced bands (like a real spectrum analyzer): BinBoundaries[b]..[b+1] feed bar b.
    static readonly int[] BinBoundaries = BuildBinBoundaries();

    static int[] BuildBinBoundaries()
    {
        var bounds = new int[Bars + 1];
        for (int b = 0; b <= Bars; b++)
            bounds[b] = (int)MathF.Round(MinBin * MathF.Pow((float)MaxBin / MinBin, (float)b / Bars));
        for (int b = 1; b <= Bars; b++)
            if (bounds[b] <= bounds[b - 1]) bounds[b] = bounds[b - 1] + 1;
        return bounds;
    }

    // --- capture thread -> Draw() ---
    WasapiLoopbackCapture? _capture;
    readonly NAudio.Dsp.Complex[] _fft = new NAudio.Dsp.Complex[FftSize];
    int _fftWritePos;
    readonly float[] _bars = new float[Bars];
    readonly object _lock = new object();
    string _status = "";

    // --- per blob, Draw() only ---
    readonly float[] _level = new float[Bars];       // smoothed loudness 0..1
    readonly float[] _ox = new float[Bars], _oy = new float[Bars];   // offset from the stalk tip (flight / swing)
    readonly float[] _vx = new float[Bars], _vy = new float[Bars];
    float _free;                         // 0 = on the stalks, 1 = floating free (silence)
    bool _silent = true;
    float _anger, _wave = -1;

    public override void Settings() => Attach(WindowTarget.Terminal);

    public override void Setup()
    {
        ListenToShell();
        ColorMode(ColorSpaceMode.HSB, 360, 100, 100, 255);
        StartCapture();
    }

    public override void OnStop() => StopCapture();

    public override void CommandFinished()
    {
        if (LastCommandOk) { _wave = 0; return; }
        _anger = 1;
        for (int i = 0; i < Bars; i++) { _vy[i] -= Random(400, 900); _vx[i] += Random(-200, 200); }
    }

    public override void Draw()
    {
        Clear();
        float dt = Math.Min(DeltaTime, 1 / 30f);
        float t = Millis() / 1000f;
        _anger = Math.Max(0, _anger - dt / 2);
        if (_wave >= 0 && (_wave += dt * 1.6f) > 1.3f) _wave = -1;

        float[] snapshot;
        lock (_lock) snapshot = (float[])_bars.Clone();

        float overall = 0;
        for (int i = 0; i < Bars; i++)
        {
            float target = Constrain(snapshot[i], 0, 1);
            _level[i] = Lerp(_level[i], target, Math.Min(1, dt * (target > _level[i] ? 25 : 8)));   // fast attack, slower release
            overall += _level[i];
        }
        overall /= Bars;
        if (_silent && overall > SilenceExit) _silent = false;
        if (!_silent && overall < SilenceEnter) _silent = true;
        _free = Lerp(_free, _silent ? 1 : 0, Math.Min(1, dt * (_silent ? 1.2f : 3)));

        var a = TargetAcceleration;
        float gap = Width / (float)Bars;
        float maxLen = Height * 0.45f;

        for (int i = 0; i < Bars; i++)
        {
            // Flight: a spring back to the stalk tip (weak while free), a noise wander
            // while free, and the window's motion felt as inertia.
            float spring = Lerp(60, 0.3f, _free);
            float wander = 260 * _free;
            float heading = i * 2.4f + (Noise(i * 0.7f, t * 0.35f) - 0.5f) * 8;
            _vx[i] += (-a.X * 0.3f - _ox[i] * spring + Cos(heading) * wander - _vx[i] * 2.2f) * dt;
            _vy[i] += (-a.Y * 0.3f - _oy[i] * spring + Sin(heading) * wander - 380 * _free - _vy[i] * 2.2f) * dt;   // free blobs rise
            _ox[i] += _vx[i] * dt;
            _oy[i] += _vy[i] * dt;
        }

        NoStroke();
        for (int i = 0; i < Bars; i++)
        {
            float baseX = (i + 0.5f) * gap, baseY = Height;
            float len = Lerp(gap * 0.5f, maxLen, _level[i]);
            float hx = Constrain(baseX + _ox[i], 0, Width), hy = Constrain(baseY - len + _oy[i], gap * 0.5f, Height);
            if (hy <= gap * 0.5f && _vy[i] < 0) _vy[i] = -_vy[i] * 0.5f;   // bounce off the top edge
            float lit = _wave >= 0 ? Exp(-Sq((i / (float)Bars - _wave) / 0.08f)) : 0;
            float hue = Lerp(Map(i, 0, Bars, 170, 300), 360, _anger) % 360;
            float r = gap * (0.28f + 0.35f * _level[i]) * (1 + 0.6f * lit);

            // The stalk: a tapered quad from the bottom edge to the head, fading as the blob floats away.
            float stalk = 1 - _free;
            if (stalk > 0.02f)
            {
                float dx = hx - baseX, dy = hy - baseY, d = Math.Max(1, Sqrt(dx * dx + dy * dy));
                float nx = -dy / d, ny = dx / d, w0 = gap * 0.18f, w1 = r * 0.5f;
                Fill(hue, 70, 90, 90 * stalk);
                Quad(baseX + nx * w0, baseY + ny * w0, hx + nx * w1, hy + ny * w1,
                     hx - nx * w1, hy - ny * w1, baseX - nx * w0, baseY - ny * w0);
            }

            // The head: a glow faked the classic 2D way -- the same circle, bigger and fainter.
            for (int k = 4; k >= 1; k--)
            {
                Fill(hue, 70, 100, (14 + 30 * lit) * (0.5f + _level[i]));
                Circle(hx, hy, r * 2 * (1 + 0.45f * k));
            }
            Fill(hue, 45 - 30 * lit, 100, 220);
            Circle(hx, hy, r * 2);
        }

        if (_status.Length > 0)
        {
            Fill(0, 0, 100, 160);
            TextSize(12);
            TextAlign(TextAlignH.Right, TextAlignV.Bottom);
            Text(_status, Width - 8, Height - 6);
        }
    }

    // --- capture -----------------------------------------------------------------

    void StartCapture()
    {
        if (!OperatingSystem.IsWindows()) { _status = "audio del sistema: solo Windows"; return; }
        try
        {
            var capture = new WasapiLoopbackCapture();
            capture.DataAvailable += (s, e) => OnAudio(e.Buffer, e.BytesRecorded, capture.WaveFormat);
            capture.StartRecording();
            _capture = capture;
            _status = "";
        }
        catch (Exception ex)
        {
            _status = "sin audio: " + ex.Message;
        }
    }

    void StopCapture()
    {
        try { _capture?.StopRecording(); _capture?.Dispose(); } catch { }
        _capture = null;
    }

    // Capture thread: mix to mono, window it, and every FftSize samples run the FFT.
    void OnAudio(byte[] buffer, int bytes, WaveFormat format)
    {
        int bytesPerSample = format.BitsPerSample / 8, channels = format.Channels;
        int frameSize = bytesPerSample * channels;
        if (bytesPerSample != 4) return;   // loopback is 32-bit float
        for (int i = 0; i < bytes / frameSize; i++)
        {
            float sum = 0;
            for (int ch = 0; ch < channels; ch++)
                sum += BitConverter.ToSingle(buffer, i * frameSize + ch * bytesPerSample);
            _fft[_fftWritePos].X = (float)(sum / channels * NAudio.Dsp.FastFourierTransform.HammingWindow(_fftWritePos, FftSize));
            _fft[_fftWritePos].Y = 0;
            if (++_fftWritePos >= FftSize)
            {
                _fftWritePos = 0;
                NAudio.Dsp.FastFourierTransform.FFT(true, FftLog2, _fft);
                UpdateBars();
            }
        }
    }

    void UpdateBars()
    {
        lock (_lock)
            for (int b = 0; b < Bars; b++)
            {
                int start = BinBoundaries[b], end = BinBoundaries[b + 1];
                float sum = 0;
                for (int k = start; k < end; k++)
                    sum += Mag(_fft[k].X, _fft[k].Y);
                float value = Sqrt(sum / (end - start)) * Gain * Map(b, 0, Bars, 0.75f, 2.1f);   // a mild ramp: highs are quieter
                _bars[b] = Math.Max(value, _bars[b] * Decay);
            }
    }
}

// The planet's earthquakes, live, on a dotted globe with relief and the world's countries.
//
// Three free, keyless downloads -- each one a single line, loading in the background
// while the sketch keeps drawing (RequestGeoJSON / RequestPImage), cached on disk so the
// next run starts at once:
// - the earthquakes: the USGS (U.S. Geological Survey) real-time feed, GeoJSON, every
//   5 minutes. https://earthquake.usgs.gov/earthquakes/feed/
// - the countries: Natural Earth's 1:110m outlines (public domain), GeoJSON.
// - the relief: a 2048 x 1024 grayscale elevation map of the Earth (three-globe's, from
//   NASA data), read pixel by pixel with img.LoadPixels() / img.Pixels.
//
// The globe is ~36,000 points from Geo.FibonacciSphere(): the ones inside a country
// (countries.FeatureAt(lat, lon)) are land and rise with the terrain -- flat below a
// threshold, amplified above it, so mountain ranges stand out -- the rest a faint sea.
// They're all drawn in one batch with Points(cloud, view), hiding the far side of the
// ball. Each earthquake stands out of the ground: height is magnitude, color is depth.
// Hover one: magnitude, depth, country, place, time, and the area where it was felt
// (Geo.Circle) with waves running out to it.
//
// Drag: turn.  Wheel: zoom.  D / W: last day / last week (with the week the quakes trace
// the plate boundaries by themselves).  R: replay the period in 40 s, a ring and a sound
// per quake.  E: relief flat / normal / dramatic.  L: labels.  Space: stop the spin.
public class QuakeGlobe : Sketch
{
    // ---- settings ------------------------------------------------------------------------
    const string FeedDay = "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_day.geojson";
    const string FeedWeek = "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_week.geojson";
    const string CountriesUrl = "https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_110m_admin_0_countries.geojson";
    const string ReliefUrl = "https://raw.githubusercontent.com/vasturiano/three-globe/master/example/img/earth-topology.png";
    const string NameField = "NAME_ES";      // NAME for English names, NAME_FR, NAME_DE, NAME_PT...
    const float R = 10;                      // globe radius
    const float MountainThreshold = 0.14f;   // below this (of the elevation range) the land stays flat
    const float ReplaySeconds = 40;
    static readonly TimeSpan Forever = TimeSpan.FromDays(365);

    record Quake(float Lat, float Lon, float DepthKm, float Mag, string Place, DateTime Time)
    {
        public string Country = "";
    }

    // ---- data ----------------------------------------------------------------------------
    Request<GeoMap> countriesReq, quakesReq, quakesRead;
    Request<PImage> reliefReq;
    GeoMap countries;
    Color[] relief;
    int reliefW, reliefH;
    List<Quake> quakes = new();
    bool week, labels = true;
    long lastFetch;

    // The globe's points: built a few thousand per frame once the countries are in (a bar shows it).
    readonly PVector[] sphere = Geo.FibonacciSphere(36000);
    readonly List<int> land = new(), sea = new();
    float[] height = System.Array.Empty<float>(), shade = System.Array.Empty<float>();
    int classified;
    bool built, heightsDone;
    float shown;                             // fades the world in once it's built

    // ---- view ----------------------------------------------------------------------------
    PFont font;
    readonly PointCloud cloud = new();
    View3D view;
    float yaw = -1.4f, pitch = 0.15f, zoom = 1, reliefScale = 1;   // starts over the Americas
    bool spinning = true;
    float replayT = -1;
    readonly List<(Quake Q, float Born)> rings = new();
    Quake hovered;

    public override void Setup()
    {
        Size(960, 600);
        font = CreateFont("Segoe UI", 14);
        countriesReq = RequestGeoJSON(CountriesUrl, cacheFor: Forever);
        reliefReq = RequestPImage(ReliefUrl, cacheFor: Forever);
        FetchQuakes();
        cloud.OccluderCenter = new PVector(0, 0, 0);
        cloud.OccluderRadius = R * 0.995f;
    }

    void FetchQuakes()
    {
        quakesReq = RequestGeoJSON(week ? FeedWeek : FeedDay, cacheFor: TimeSpan.FromMinutes(4));
        lastFetch = Millis();
    }

    // =====================================================================================
    // Each frame
    // =====================================================================================
    public override void Draw()
    {
        TakeArrivals();
        if (Millis() - lastFetch > 5 * 60 * 1000) FetchQuakes();
        if (spinning) yaw -= 0.0015f;
        if (built && (heightsDone || reliefReq.Failed)) shown = Min(1, shown + 0.02f);

        view = View3D.Orbit(yaw, pitch, 25 / zoom);
        Background(5, 8, 18);
        Atmosphere();
        if (shown > 0)
        {
            DrawGlobe();
            DrawBorders();
            var clock = Replay();
            DrawQuakes(clock);
            if (labels) DrawLabels();
        }
        Hud();
        if (shown < 1) Loading();
    }

    void TakeArrivals()
    {
        if (countries == null && countriesReq.Ready) countries = countriesReq.Value;
        if (relief == null && reliefReq.Ready)
        {
            var img = reliefReq.Value;
            img.LoadPixels();                                   // the PNG's pixels, as Colors
            relief = img.Pixels; reliefW = img.Width; reliefH = img.Height;
        }

        // Land or sea: 3,000 points a frame, so the bar moves and the window never freezes.
        if (!built && (countries != null || countriesReq.Failed))
        {
            int end = Math.Min(sphere.Length, classified + 3000);
            for (; classified < end; classified++)
            {
                var (lat, lon) = Geo.FromSphere(sphere[classified]);
                if (countries?.FeatureAt(lat, lon) != null) land.Add(classified);
                else if ((uint)(classified * 2654435761u) % 6 == 0) sea.Add(classified);   // 1 in 6, scattered (every 6th would line up in spirals)
            }
            if (classified == sphere.Length) built = true;
        }

        // Heights and hill shading, once both the land and the relief are in.
        if (built && relief != null && !heightsDone)
        {
            height = new float[land.Count];
            shade = new float[land.Count];
            for (int k = 0; k < land.Count; k++)
            {
                var (lat, lon) = Geo.FromSphere(sphere[land[k]]);
                height[k] = HeightAt(lat, lon);
                // Light from the north-west: slopes facing it brighter, the others darker.
                float slope = (HeightAt(lat + 0.6f, lon) - HeightAt(lat - 0.6f, lon)) + (HeightAt(lat, lon - 0.6f) - HeightAt(lat, lon + 0.6f));
                shade[k] = Math.Clamp(1 + slope * 4, 0.45f, 1.6f);
            }
            heightsDone = true;
        }

        if (quakesReq.Ready && quakesRead != quakesReq)
        {
            quakes = ReadQuakes(quakesReq.Value);
            quakesRead = quakesReq;
        }
        if (countries != null)
            foreach (var q in quakes)
                if (q.Country == "") q.Country = countries.FeatureAt(q.Lat, q.Lon)?.Text(NameField) ?? "-";
    }

    /// <summary>USGS GeoJSON: one Point per quake (its third coordinate is the depth, km) with mag, place and time (ms).</summary>
    static List<Quake> ReadQuakes(GeoMap map)
    {
        var list = new List<Quake>();
        foreach (var f in map.Features)
        {
            double mag = f.Number("mag");
            if (double.IsNaN(mag) || f.Points.Count == 0) continue;
            var time = DateTimeOffset.FromUnixTimeMilliseconds((long)f.Number("time", 0)).LocalDateTime;
            list.Add(new Quake(f.Lat, f.Lon, f.Alt, (float)mag, f.Text("place") ?? "?", time));
        }
        list.Sort((a, b) => a.Time.CompareTo(b.Time));
        return list;
    }

    /// <summary>Elevation 0..1 (the map is equirectangular: Geo.Equirectangular() gives the pixel).</summary>
    float HeightAt(float lat, float lon)
    {
        if (relief == null) return 0;
        var (x, y) = Geo.Equirectangular(lat, lon, reliefW, reliefH);
        int px = Math.Clamp((int)x, 0, reliefW - 1), py = Math.Clamp((int)y, 0, reliefH - 1);
        return relief[py * reliefW + px].R / 248f;
    }

    /// <summary>Height above the sphere: almost flat below the threshold, amplified above it.</summary>
    float Lift(float h) => R * reliefScale * (0.012f * h + 0.16f * MathF.Pow(Math.Max(0, h - MountainThreshold) / (1 - MountainThreshold), 1.3f));

    PVector Ground(float lat, float lon, float extra = 0) => Geo.ToSphere(lat, lon, R + Lift(HeightAt(lat, lon)) + extra);

    /// <summary>Screen position of a point, and whether it's on the side of the globe facing us.</summary>
    (float X, float Y, bool Front) See(PVector p)
    {
        var (x, y, depth) = view.Project(p, Width, Height);
        var e = view.Eye;
        bool front = depth > 0 && p.X * (e.X - p.X) + p.Y * (e.Y - p.Y) + p.Z * (e.Z - p.Z) > 0;
        return (x, y, front);
    }

    // =====================================================================================
    // Drawing
    // =====================================================================================
    void Atmosphere()
    {
        var (cx, cy, _) = view.Project(new PVector(0, 0, 0), Width, Height);
        float d = 25 / zoom;
        float screenR = view.Scale(d, Height) * R * d / MathF.Sqrt(d * d - R * R);
        NoStroke();
        for (int k = 8; k >= 1; k--)
        {
            Fill(40, 110, 220, 7);
            Circle(cx, cy, 2 * screenR + k * 9);
        }
        Fill(6, 12, 28);
        Circle(cx, cy, 2 * screenR);
    }

    void DrawGlobe()
    {
        cloud.Clear();
        byte a = (byte)(255 * shown);
        foreach (int i in sea)
            cloud.Add(PVector.Mult(sphere[i], R), Color(30, 60, 105, 150 * shown), 0.07f);
        bool lifted = heightsDone && reliefScale > 0;
        for (int k = 0; k < land.Count; k++)
        {
            float h = heightsDone ? height[k] : 0;
            var p = PVector.Mult(sphere[land[k]], R + (lifted ? Lift(h) : 0));
            // Terrain colors: green lowlands, tan uplands, white peaks, hill-shaded.
            float cr, cg, cb;
            if (h < 0.18f) { float t = h / 0.18f; cr = Lerp(70, 160, t); cg = Lerp(190, 185, t); cb = Lerp(130, 105, t); }
            else if (h < 0.55f) { float t = (h - 0.18f) / 0.37f; cr = Lerp(150, 175, t); cg = Lerp(175, 140, t); cb = Lerp(100, 105, t); }
            else { float t = Math.Min(1, (h - 0.55f) / 0.35f); cr = Lerp(175, 245, t); cg = Lerp(140, 245, t); cb = Lerp(105, 250, t); }
            float l = heightsDone ? shade[k] : 1;
            var c = Color(Math.Min(255, cr * l), Math.Min(255, cg * l), Math.Min(255, cb * l), a);
            cloud.Add(p, c, 0.12f + h * 0.08f);
            // Mountains: a stalk from the ground up, so a range reads as volume.
            if (lifted && h > MountainThreshold)
                for (float s = 0.3f; s < 1; s += 0.35f)
                    cloud.Add(PVector.Mult(sphere[land[k]], R + Lift(h) * s), Color(cr * l * 0.8f, cg * l * 0.8f, cb * l * 0.8f, a * 0.7f), 0.07f);
        }
        Points(cloud, view);                                     // all of it, one batch
    }

    void DrawBorders()
    {
        if (countries == null) return;
        NoFill();
        StrokeWeight(0.8f);
        Stroke(120, 200, 230, 110 * shown);
        foreach (var f in countries.Features)
            foreach (var ring in f.Rings)
            {
                float px = 0, py = 0; bool prev = false;
                for (int i = 0; i < ring.Count; i++)
                {
                    var (x, y, front) = See(Ground(ring.Lat[i], ring.Lon[i], 0.02f));
                    if (front && prev) Line(px, py, x, y);
                    px = x; py = y; prev = front;
                }
            }
    }

    DateTime Replay()
    {
        DateTime now = DateTime.Now;
        if (replayT < 0 || quakes.Count == 0) return now;
        DateTime first = quakes[0].Time, last = quakes[^1].Time;
        DateTime At(float t) => first + TimeSpan.FromTicks((long)((last - first).Ticks * Math.Min(1, t / ReplaySeconds)));
        DateTime before = At(replayT);
        replayT += 1 / 60f;
        DateTime clock = At(replayT);
        foreach (var q in quakes)
            if (q.Time > before && q.Time <= clock)
            {
                rings.Add((q, Millis() / 1000f));
                // Bigger: lower and louder. Deeper: darker.
                Play(72 - q.Mag * 7, amp: Constrain(0.03f + q.Mag * q.Mag * 0.006f, 0.03f, 0.35f), attack: 0.01,
                     release: 0.4 + q.Mag * 0.3, cutoff: 100 - Math.Min(40, q.DepthKm / 15), synth: Synth.Triangle);
                if (q.Mag >= 4.5f) Sample("kick", amp: Math.Min(1, q.Mag / 7), rate: 0.5);
            }
        if (replayT > ReplaySeconds + 3) replayT = -1;
        return clock;
    }

    /// <summary>A ring on the ground, <paramref name="km"/> from (lat, lon) -- Geo.Circle does the sphere math.</summary>
    void GroundRing(float lat, float lon, float km, bool filled)
    {
        var pts = Geo.Circle(lat, lon, Math.Max(km, 1), 64);
        if (filled)
        {
            BeginShape();
            foreach (var (la, lo) in pts) { var s = See(Ground(la, lo, 0.03f)); if (s.Front) Vertex(s.X, s.Y); }
            EndShape(true);
            return;
        }
        float px = 0, py = 0; bool prev = false;
        foreach (var (la, lo) in pts)
        {
            var (x, y, front) = See(Ground(la, lo, 0.03f));
            if (front && prev) Line(px, py, x, y);
            px = x; py = y; prev = front;
        }
    }

    /// <summary>Roughly how far from the epicentre people feel it, km: ~10 at M2, ~160 at M5, ~1,200 at M7.</summary>
    static float FeltKm(float mag) => MathF.Pow(10, 0.43f * mag + 0.06f);

    void DrawQuakes(DateTime clock)
    {
        float tNow = Millis() / 1000f;
        rings.RemoveAll(r => tNow - r.Born > 3);
        NoFill();
        foreach (var (q, born) in rings)
        {
            float age = tNow - born;
            var (r, g, b) = DepthColor(q.DepthKm);
            Stroke(r, g, b, 255 * (1 - age / 3));
            StrokeWeight(1.5f);
            GroundRing(q.Lat, q.Lon, FeltKm(q.Mag) * age, false);
        }

        var visible = new List<(Quake Q, float X0, float Y0, float X1, float Y1, bool Front)>();
        foreach (var q in quakes)
        {
            if (q.Time > clock) continue;
            float h = 0.2f + Pow(Max(0, q.Mag), 1.6f) * 0.25f;
            var (x0, y0, front) = See(Ground(q.Lat, q.Lon));
            var (x1, y1, _) = See(Ground(q.Lat, q.Lon, h));
            if (float.IsNaN(x0)) continue;
            visible.Add((q, x0, y0, x1, y1, front));
        }
        visible.Sort((u, v) => u.Front.CompareTo(v.Front));          // the far side first

        hovered = null;
        float best = 12 * 12;
        foreach (var v in visible)
        {
            float d2 = (v.X1 - MouseX) * (v.X1 - MouseX) + (v.Y1 - MouseY) * (v.Y1 - MouseY);
            if (v.Front && d2 < best) { best = d2; hovered = v.Q; }
        }
        if (hovered != null) FeltArea(hovered);

        foreach (var v in visible)
        {
            var q = v.Q;
            var (r, g, b) = DepthColor(q.DepthKm);
            bool hot = q == hovered, dim = hovered != null && !hot;
            float pulse = (DateTime.Now - q.Time).TotalHours < 1 ? 0.5f + 0.5f * Sin(Millis() / 160f) : 0;
            float alpha = (v.Front ? 255 : 90) * (dim ? 0.3f : 1) * shown;
            StrokeWeight(1.2f + q.Mag * 0.25f);
            Stroke(r, g, b, alpha);
            Line(v.X0, v.Y0, v.X1, v.Y1);
            NoStroke();
            float size = (2.5f + q.Mag * 2.2f) * zoom * 0.8f;
            Fill(r, g, b, alpha * 0.25f);
            Circle(v.X1, v.Y1, size * (2 + pulse));
            Fill(hot ? 255 : r, hot ? 255 : g, hot ? 255 : b, alpha);
            Circle(v.X1, v.Y1, size);
        }
    }

    /// <summary>The hovered quake's reach: the felt area, and four waves running out to its edge.</summary>
    void FeltArea(Quake q)
    {
        var (r, g, b) = DepthColor(q.DepthKm);
        float km = FeltKm(q.Mag), t = Millis() / 1000f;
        NoStroke();
        Fill(r, g, b, 70);
        GroundRing(q.Lat, q.Lon, km, true);
        NoFill();
        Stroke(r, g, b, 170);
        StrokeWeight(1.2f);
        GroundRing(q.Lat, q.Lon, km, false);
        for (int w = 0; w < 4; w++)
        {
            float frac = (t * 0.5f + w / 4f) % 1;
            Stroke(r, g, b, 230 * (1 - frac));
            StrokeWeight(2.2f * (1 - frac) + 0.6f);
            GroundRing(q.Lat, q.Lon, km * frac, false);
        }
    }

    static (float, float, float) DepthColor(float km)
    {
        // 0 km yellow -> 70 km orange -> 300 km red -> 700 km violet.
        float t = Math.Clamp(MathF.Log(1 + Math.Max(0, km)) / MathF.Log(700), 0, 1);
        float r = t > 0.8f ? 255 - (t - 0.8f) * 400 : 255;
        return (r, 230 - 200 * t, 60 + 300 * Math.Max(0, t - 0.6f));
    }

    void DrawLabels()
    {
        if (countries == null) return;
        TextFont(font, 12);
        TextAlign(TextAlignH.Center, TextAlignV.Center);
        foreach (var f in countries.Features)
        {
            if (f.Number("LABELRANK", 9) > 2 + (int)((zoom - 1) * 3)) continue;   // closer: more names
            var p = Ground((float)f.Number("LABEL_Y", 0), (float)f.Number("LABEL_X", 0), 0.1f);
            var (x, y, front) = See(p);
            if (!front) continue;
            float facing = PVector.Dot(PVector.Sub(view.Eye, p).Normalize(), PVector.Mult(p, 1f / p.Mag()));
            Fill(235, 245, 255, 230 * Constrain((facing - 0.3f) * 3, 0, 1) * shown);
            Text(f.Text(NameField) ?? f.Name, x, y);
        }
    }

    void Hud()
    {
        TextFont(font, 14);
        if (hovered != null)
        {
            var q = hovered;
            float w = 360, x = Math.Min(MouseX + 16, Width - w - 8), y = Math.Min(MouseY + 12, Height - 120);
            NoStroke();
            Fill(0, 0, 0, 190);
            Rect(x, y, w, 108, 8);                                // rounded, like Processing's rect(x, y, w, h, r)
            TextAlign(TextAlignH.Left, TextAlignV.Top);
            Fill(255);
            Text($"M {q.Mag:0.0}  ·  {q.DepthKm:0} km deep  ·  {(q.Country is "" or "-" ? "ocean" : q.Country)}", x + 12, y + 8);
            Fill(200, 210, 230);
            Text(q.Place.Length > 48 ? q.Place[..48] + "…" : q.Place, x + 12, y + 32);
            Text($"{q.Time:ddd dd MMM HH:mm}  ({(DateTime.Now - q.Time).TotalHours:0.0} h ago)", x + 12, y + 56);
            Fill(255, 220, 160);
            Text($"felt up to ~{FeltKm(q.Mag):N0} km away (the waves reach that far)", x + 12, y + 80);
        }

        TextAlign(TextAlignH.Left, TextAlignV.Bottom);
        TextSize(13);
        string feed = quakesReq.Failed && quakes.Count == 0 ? "earthquakes: " + quakesReq.Status
                    : $"USGS · {quakes.Count} earthquakes · {(week ? "M2.5+, last 7 days" : "all, last 24 hours")}" + (quakesReq.Stale ? " · offline, older copy" : "");
        string replay = replayT >= 0 ? $"  ·  replay {Math.Min(100, replayT / ReplaySeconds * 100):0}%" : "";
        Fill(230, 235, 255, 170);
        Text($"{feed}{replay}  ·  Natural Earth · {countries?.Count ?? 0} countries", 16, Height - 30);
        Fill(255, 255, 255, 80);
        Text("drag: turn · wheel: zoom · hover: details · D/W: day/week · R: replay · E: relief · L: labels · Space: spin", 16, Height - 12);

        TextAlign(TextAlignH.Right, TextAlignV.Center);
        Fill(255, 255, 255, 120);
        Text("depth", Width - 16, 20);
        int[] kms = { 0, 30, 70, 150, 300, 600 };
        for (int k = 0; k < kms.Length; k++)
        {
            var (r, g, b) = DepthColor(kms[k]);
            Fill(r, g, b);
            Circle(Width - 22, 40 + k * 18, 9);
            Fill(255, 255, 255, 150);
            Text($"{kms[k]} km", Width - 34, 40 + k * 18);
        }
    }

    /// <summary>The loading panel: each request's own Status and Progress.</summary>
    void Loading()
    {
        float a = 1 - shown, w = 460, h = 190, x = (Width - w) / 2, y = (Height - h) / 2;
        NoStroke();
        Fill(8, 14, 30, 225 * a);
        Rect(x, y, w, h, 12);
        TextFont(font, 15);
        TextAlign(TextAlignH.Left, TextAlignV.Top);
        Fill(230, 240, 255, 255 * a);
        string[] spin = { "◐", "◓", "◑", "◒" };
        Text($"{spin[(int)(Millis() / 150) % 4]}  Loading the world", x + 20, y + 16);
        Row(0, "World map (country outlines)", countriesReq.Status, countriesReq.Ready ? 1 : countriesReq.Progress);
        Row(1, "Relief (elevation of the Earth)", reliefReq.Status, reliefReq.Ready ? 1 : reliefReq.Progress);
        Row(2, "Building the globe (land and sea)", $"{classified:N0} / {sphere.Length:N0} points", classified / (float)sphere.Length);
        Row(3, "Earthquakes (USGS)", quakes.Count > 0 ? $"{quakes.Count} earthquakes" : quakesReq.Status, quakes.Count > 0 ? 1 : quakesReq.Progress);

        void Row(int k, string name, string state, float progress)
        {
            float ly = y + 52 + k * 34;
            TextSize(12);
            TextAlign(TextAlignH.Left, TextAlignV.Top);
            Fill(190, 205, 230, 255 * a);
            Text(name, x + 20, ly);
            TextAlign(TextAlignH.Right, TextAlignV.Top);
            Fill(140, 160, 190, 255 * a);
            Text(state, x + w - 20, ly);
            Fill(255, 255, 255, 25 * a);
            Rect(x + 20, ly + 17, w - 40, 4, 2);
            Fill(90, 190, 255, 255 * a);
            if (progress >= 0) Rect(x + 20, ly + 17, (w - 40) * Math.Min(1, progress), 4, 2);
            else Rect(x + 20 + (Millis() / 4) % (long)(w - 100), ly + 17, 60, 4, 2);   // size unknown: a sliding block
        }
    }

    // =====================================================================================
    // Input
    // =====================================================================================
    public override void MouseDragged()
    {
        yaw -= (MouseX - PMouseX) * 0.008f;
        pitch = Constrain(pitch - (MouseY - PMouseY) * 0.008f, -1.3f, 1.3f);
    }

    public override void MouseWheel(float delta) => zoom = Constrain(zoom * (delta > 0 ? 1 / 1.1f : 1.1f), 0.7f, 2.6f);

    public override void KeyPressed()
    {
        if (Key == 'w' || Key == 'W') { week = true; FetchQuakes(); }
        else if (Key == 'd' || Key == 'D') { week = false; FetchQuakes(); }
        else if (Key == 'r' || Key == 'R') { replayT = 0; rings.Clear(); }
        else if (Key == 'e' || Key == 'E') reliefScale = reliefScale == 0 ? 1 : reliefScale == 1 ? 2.2f : 0;
        else if (Key == 'l' || Key == 'L') labels = !labels;
        else if (Key == ' ') spinning = !spinning;
    }
}

// A real storm, seen from above -- anywhere on Earth.
//
// Two free, keyless sources, downloaded in the background while the sketch keeps drawing:
// - RainViewer: the weather radar of the last two hours, as map tiles (10-minute steps).
//   https://www.rainviewer.com/api.html
// - Open-Meteo: the wind right now where you're looking (speed and where it blows from).
//   https://open-meteo.com
// and Natural Earth's country outlines for the coasts.
//
// The radar becomes a 3D field: where it rains, a cloud of soft points floats -- higher and
// thicker the harder it rains -- and streaks of rain fall from it, leaning with the real
// wind, splashing where it pours and flashing where it storms. The radar frames play in a
// loop, so you watch the storm move over the last two hours.
//
// It's a map: drag to move over the world, the wheel zooms from the whole planet (zoom 2)
// down to a region (zoom 7, the most RainViewer's free tiles give). Tiles already seen are
// kept, so going back is instant.
//
// Drag: move.  Right-drag (or Q/E, R/F): turn and tilt.  Wheel or +/-: zoom.
// Arrows: move.  1-6: jump to a city.  Space: pause.  , and .: step through the frames.
// M: a made-up storm (clearly labelled), for when it isn't raining anywhere you look.
public class StormFromAbove : Sketch
{
    // ---- settings -----------------------------------------------------------------------
    const int MinZoom = 2, MaxZoom = 7;          // RainViewer's free tiles go up to 7
    const int Tiles = 3;                         // 3 x 3 tiles of 256 px around the center
    const int G = 96;                            // the field: 96 x 96 cells (8 x 8 radar pixels each)
    const int Px = Tiles * 256, Cell = Px / G;
    const float Window = 40;                     // cells drawn around the center (a round window)
    const string CountriesUrl = "https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_50m_admin_0_countries.geojson";

    static readonly (string Name, float Lat, float Lon)[] Places =
    {
        ("Miami", 25.76f, -80.19f), ("Houston", 29.76f, -95.37f), ("London", 51.51f, -0.13f),
        ("Madrid", 40.42f, -3.70f), ("Tokyo", 35.68f, 139.69f), ("Sydney", -33.87f, 151.21f),
    };

    // ---- where we look --------------------------------------------------------------------
    int zoomLevel = 5;
    float lat = 25.76f, lon = -80.19f;           // the center of the view
    int ox, oy;                                  // the top-left tile of the 3 x 3 block
    bool haveBlock;

    // ---- data ---------------------------------------------------------------------------
    Request<JSONObject> mapsReq, windReq;
    Request<GeoMap> countriesReq;
    string host = "";
    readonly List<(long Time, string Path)> frames = new();       // newest last
    readonly Dictionary<string, Request<PImage>> tileCache = new(); // every tile ever asked for
    float[][] grids;                                               // per frame: intensity 0..1 per cell
    Color[][] tints;                                               // per frame: the radar's color per cell
    readonly Queue<(int Frame, int Tile)> pending = new();
    long lastRequest = -10000;
    bool[] land;
    int landDone;
    float windKmh, windFromDeg, temperature = float.NaN;
    float windLat = float.NaN, windLon = float.NaN;
    bool demo;

    // ---- view and time ------------------------------------------------------------------
    PFont font;
    readonly PointCloud ground = new(), clouds = new();
    float yaw = -0.35f, pitch = 0.75f;
    float clock;                                 // radar loop position, in frames
    float animT;                                 // the animation's own time: stops when paused
    bool paused;
    int shownFrame;

    public override void Setup()
    {
        Size(1000, 620);
        font = CreateFont("Segoe UI", 14);
        countriesReq = RequestGeoJSON(CountriesUrl, cacheFor: TimeSpan.FromDays(365));
        mapsReq = RequestJSONObject("https://api.rainviewer.com/public/weather-maps.json", cacheFor: TimeSpan.FromMinutes(5));
        ground.DepthSort = false;
        Retile();
    }

    // =====================================================================================
    // Map math: Web Mercator tiles, like every web map
    // =====================================================================================
    float TileX(float lo) => (lo + 180) / 360 * (1 << zoomLevel);
    float TileY(float la)
    {
        double r = Math.Clamp(la, -85, 85) * Math.PI / 180;
        return (float)((1 - Math.Log(Math.Tan(r) + 1 / Math.Cos(r)) / Math.PI) / 2 * (1 << zoomLevel));
    }
    float LonOf(float tx) => tx / (1 << zoomLevel) * 360 - 180;
    float LatOf(float ty) => (float)(Math.Atan(Math.Sinh(Math.PI * (1 - 2 * ty / (1 << zoomLevel)))) * 180 / Math.PI);

    /// <summary>How far the center is from the middle of the tile block, in cells (it moves smoothly as you drag).</summary>
    (float X, float Y) Offset() => ((TileX(lon) - (ox + 1.5f)) * 256 / Cell, (TileY(lat) - (oy + 1.5f)) * 256 / Cell);

    /// <summary>A cell of the field as world x (east) and z (north), with the view's center at the origin.</summary>
    (float X, float Z) CellPos(float cx, float cy, (float X, float Y) off) => (cx - G / 2f - off.X, G / 2f + off.Y - cy);

    /// <summary>0 outside the round window, 1 well inside it, a soft edge between.</summary>
    static float Fade(float x, float z)
    {
        float d = MathF.Sqrt(x * x + z * z);
        return Math.Clamp((Window - d) / 6, 0, 1);
    }

    /// <summary>When the center crosses into another tile, the 3 x 3 block moves with it.</summary>
    void Retile()
    {
        int nx = (int)Math.Floor(TileX(lon)) - 1, ny = (int)Math.Floor(TileY(lat)) - 1;
        if (haveBlock && nx == ox && ny == oy) return;
        haveBlock = true;
        ox = nx; oy = ny;
        grids = frames.Count > 0 ? new float[frames.Count][] : null;
        tints = frames.Count > 0 ? new Color[frames.Count][] : null;
        land = new bool[G * G];
        landDone = 0;
        ground.Clear();
        QueueTiles();
    }

    string TileUrl(int f, int t, out bool exists)
    {
        int n = 1 << zoomLevel;
        int tx = ((ox + t % Tiles) % n + n) % n, ty = oy + t / Tiles;   // wraps around the world east-west
        exists = ty >= 0 && ty < n;
        return $"{host}{frames[f].Path}/256/{zoomLevel}/{tx}/{ty}/2/1_0.png";
    }

    void QueueTiles()
    {
        pending.Clear();
        for (int f = frames.Count - 1; f >= 0; f--)              // newest frame first
            for (int t = 0; t < Tiles * Tiles; t++)
                pending.Enqueue((f, t));
    }

    void Jump(float la, float lo, int z)
    {
        lat = la; lon = lo; zoomLevel = z;
        haveBlock = false;                                       // force a new block
        Retile();
        windLat = float.NaN;
    }

    // =====================================================================================
    // Loading, a little every frame
    // =====================================================================================
    void Load()
    {
        // The radar's frame list.
        if (frames.Count == 0 && mapsReq.Ready)
        {
            var m = mapsReq.Value;
            host = m.GetString("host");
            var past = m.GetJSONObject("radar")?.GetJSONArray("past");
            for (int i = 0; past != null && i < past.Size(); i++)
                frames.Add((past.GetJSONObject(i).GetInt("time"), past.GetJSONObject(i).GetString("path")));
            clock = frames.Count - 1;
            haveBlock = false;
            Retile();
        }
        if (mapsReq.Failed && !demo) demo = true;

        // RainViewer allows 100 requests a minute: one every 0.65 s. Tiles seen before cost nothing.
        while (pending.Count > 0)
        {
            var (f, t) = pending.Peek();
            string url = TileUrl(f, t, out bool exists);
            if (!exists || tileCache.ContainsKey(url)) { pending.Dequeue(); continue; }
            if (Millis() - lastRequest < 650) break;
            pending.Dequeue();
            var req = RequestPImage(url, cacheFor: TimeSpan.FromHours(3));
            tileCache[url] = req;
            if (!req.FromCache) { lastRequest = Millis(); break; }
        }

        // A frame whose 9 tiles are in becomes a grid of intensities (a few per frame, so moving never stutters).
        int built = 0;
        for (int f = frames.Count - 1; grids != null && f >= 0 && built < 3; f--)
        {
            if (grids[f] != null) continue;
            bool all = true;
            for (int t = 0; t < Tiles * Tiles && all; t++)
            {
                string url = TileUrl(f, t, out bool exists);
                all = !exists || (tileCache.TryGetValue(url, out var r) && r.Done);
            }
            if (all) { Grid(f); built++; }
        }

        // Land or sea under each cell: a few rows a frame, once the countries are in.
        if (countriesReq.Ready && landDone < G)
        {
            var map = countriesReq.Value;
            for (int row = landDone; row < Math.Min(G, landDone + 6); row++)
                for (int c = 0; c < G; c++)
                {
                    float la = LatOf(oy + (row + 0.5f) * Cell / 256f), lo = LonOf(ox + (c + 0.5f) * Cell / 256f);
                    lo = ((lo + 540) % 360) - 180;
                    land[row * G + c] = map.FeatureAt(la, lo) != null;
                }
            landDone = Math.Min(G, landDone + 6);
        }

        // The wind where we look: asked again when the view has moved far and the mouse is up.
        bool moved = float.IsNaN(windLat) || Geo.DistanceKm(lat, lon, windLat, windLon) > 150 * (1 << (7 - zoomLevel));
        if (moved && !IsMousePressed)
        {
            windLat = MathF.Round(lat * 2) / 2; windLon = MathF.Round(lon * 2) / 2;   // rounded: nearby views share the cache
            string la = windLat.ToString(System.Globalization.CultureInfo.InvariantCulture), lo = windLon.ToString(System.Globalization.CultureInfo.InvariantCulture);
            windReq = RequestJSONObject($"https://api.open-meteo.com/v1/forecast?latitude={la}&longitude={lo}&current=wind_speed_10m,wind_direction_10m,temperature_2m&wind_speed_unit=kmh", cacheFor: TimeSpan.FromMinutes(15));
            windRead = false;
        }
        if (windReq != null && windReq.Ready && !windRead)
        {
            windRead = true;
            var cur = windReq.Value.GetJSONObject("current");
            windKmh = cur?.GetFloat("wind_speed_10m") ?? 0;
            windFromDeg = cur?.GetFloat("wind_direction_10m") ?? 0;
            temperature = cur?.GetFloat("temperature_2m", float.NaN) ?? float.NaN;
        }
    }
    bool windRead;

    /// <summary>Reads a frame's 9 tiles: each cell is the strongest of a few of its pixels.</summary>
    void Grid(int f)
    {
        var grid = new float[G * G];
        var tint = new Color[G * G];
        for (int t = 0; t < Tiles * Tiles; t++)
        {
            string url = TileUrl(f, t, out bool exists);
            if (!exists || !tileCache[url].Ready) continue;
            var img = tileCache[url].Value;
            img.LoadPixels();
            var px = img.Pixels;
            int baseX = (t % Tiles) * 256, baseY = (t / Tiles) * 256;
            for (int cy = 0; cy < 256 / Cell; cy++)
                for (int cx = 0; cx < 256 / Cell; cx++)
                {
                    float best = 0; Color bestColor = default;
                    for (int sy = 1; sy < Cell; sy += 3)
                        for (int sx = 1; sx < Cell; sx += 3)
                        {
                            var c = px[(cy * Cell + sy) * 256 + cx * Cell + sx];
                            float v = Intensity(c);
                            if (v > best) { best = v; bestColor = c; }
                        }
                    int gi = (baseY / Cell + cy) * G + baseX / Cell + cx;
                    grid[gi] = best;
                    tint[gi] = bestColor;
                }
        }
        grids[f] = grid;
        tints[f] = tint;
    }

    /// <summary>
    /// How hard it rains, 0..1, from a pixel of RainViewer's "Universal Blue" scheme:
    /// transparent where it's dry, light to deep blue for light to moderate rain, then
    /// yellow, orange, red and magenta for heavy rain and storms.
    /// </summary>
    float Intensity(Color c)
    {
        if (c.A < 40) return 0;
        float h = Hue(c), s = Saturation(c), b = Brightness(c);
        float v;
        if (h >= 170 && h <= 260) v = 0.12f + 0.4f * (1 - b / 100f) + 0.15f * (s / 100f);  // blues: darker = more (s, b: 0..100)
        else if (h > 260) v = 0.95f;                                                          // magenta / purple
        else if (h >= 40) v = 0.6f;                                                           // yellow
        else if (h >= 15) v = 0.72f;                                                          // orange
        else v = 0.85f;                                                                       // red
        return Math.Clamp(v * (c.A / 255f), 0, 1);
    }

    // =====================================================================================
    // Each frame
    // =====================================================================================
    public override void Draw()
    {
        Load();
        int loaded = 0;
        for (int f = 0; grids != null && f < grids.Length; f++) if (grids[f] != null) loaded++;
        if (!paused)
        {
            animT += 1 / 60f;
            if (loaded > 1) clock += 1 / 40f;                    // ~1.5 s per radar frame
        }
        if (KeyPressedNow(LEFT)) Move(-4, 0);
        if (KeyPressedNow(RIGHT)) Move(4, 0);
        if (KeyPressedNow(UP)) Move(0, -4);
        if (KeyPressedNow(DOWN)) Move(0, 4);

        var off = Offset();
        var (grid, tint) = demo ? Demo() : Current();
        var view = View3D.Orbit(yaw, pitch, 88, new PVector(0, 4, 0), 50);

        Background(6, 10, 20);
        Ground(view, off);
        Coasts(view, off);
        if (grid != null) Rain(view, grid, tint, off);
        Hud(loaded);
    }

    bool KeyPressedNow(int code) => IsKeyPressed && KeyCode == code;

    /// <summary>The radar now: between the two loaded frames around the clock, blended.</summary>
    (float[] Grid, Color[] Tint) Current()
    {
        if (grids == null) return (null, null);
        var ready = new List<int>();
        for (int f = 0; f < grids.Length; f++) if (grids[f] != null) ready.Add(f);
        if (ready.Count == 0) return (null, null);
        float pos = ((clock % ready.Count) + ready.Count) % ready.Count;
        int a = (int)pos, b = (a + 1) % ready.Count;
        float k = Smooth(pos - a);
        var ga = grids[ready[a]]; var gb = grids[ready[b]];
        var blend = new float[G * G];
        for (int i = 0; i < blend.Length; i++) blend[i] = ga[i] + (gb[i] - ga[i]) * k;
        shownFrame = ready[k < 0.5f ? a : b];
        return (blend, tints[shownFrame]);
    }

    static float Smooth(float x) => x * x * (3 - 2 * x);

    void Ground(View3D view, (float X, float Y) off)
    {
        ground.Clear();
        for (int r = 0; r < G; r++)
            for (int c = 0; c < G; c++)
            {
                if ((r + c) % 2 == 1) continue;                  // a checkerboard of dots is plenty
                var (x, z) = CellPos(c + 0.5f, r + 0.5f, off);
                float a = Fade(x, z);
                if (a <= 0) continue;
                bool isLand = r * G + c < landDone * G && land[r * G + c];
                var col = isLand ? Color(95, 150, 110, 255 * a) : Color(25, 45, 80, 200 * a);
                ground.Add(x, 0, z, col, isLand ? 0.5f : 0.28f);
            }
        Points(ground, view);
    }

    void Coasts(View3D view, (float X, float Y) off)
    {
        if (!countriesReq.Ready) return;
        StrokeWeight(1);
        int n = 1 << zoomLevel;
        float cx0 = TileX(lon);
        float left = LonOf(ox) - 2, right = LonOf(ox + Tiles) + 2;
        foreach (var f in countriesReq.Value.Features)
        {
            // Near the date line the block spans it: test the feature shifted by a turn too.
            if (f.MaxLat < LatOf(oy + Tiles) - 2 || f.MinLat > LatOf(oy) + 2) continue;
            bool near = (f.MaxLon >= left && f.MinLon <= right) || (f.MaxLon + 360 >= left && f.MinLon + 360 <= right) || (f.MaxLon - 360 >= left && f.MinLon - 360 <= right);
            if (!near) continue;
            foreach (var ring in f.Rings)
            {
                float px = 0, py = 0; bool prev = false;
                for (int i = 0; i < ring.Count; i++)
                {
                    float tx = TileX(ring.Lon[i]);
                    tx += MathF.Round((cx0 - tx) / n) * n;       // the copy of the world nearest the center
                    float cx = (tx - ox) * 256 / Cell, cy = (TileY(ring.Lat[i]) - oy) * 256 / Cell;
                    var (wx, wz) = CellPos(cx, cy, off);
                    float a = Fade(wx, wz);
                    var (sx, sy, d) = view.Project(new PVector(wx, 0.05f, wz), Width, Height);
                    bool ok = a > 0 && d > 0;
                    if (ok && prev)
                    {
                        Stroke(130, 185, 170, 170 * a);
                        Line(px, py, sx, sy);
                    }
                    px = sx; py = sy; prev = ok;
                }
            }
        }
    }

    void Rain(View3D view, float[] grid, Color[] tint, (float X, float Y) off)
    {
        // The wind: where it blows *to* (from + 180), as an east/north vector; stronger wind, more lean.
        float to = Radians(windFromDeg + 180);
        float lean = Math.Min(windKmh, 80) / 80f * 0.9f;
        float wx = Sin(to) * lean, wz = Cos(to) * lean;

        clouds.Clear();
        var light = new List<(float, float, float, float)>(6000);
        var heavy = new List<(float, float, float, float)>(2000);
        var splashes = new List<(float X, float Y, float R, float A)>();
        var bolts = new List<(float X, float Z, float Top, int Seed)>();

        for (int i = 0; i < G * G; i++)
        {
            float v = grid[i];
            if (v < 0.06f) continue;
            int r = i / G, c = i % G;
            var (x, z) = CellPos(c + 0.5f, r + 0.5f, off);
            float fade = Fade(x, z);
            if (fade <= 0) continue;
            var tc = tint != null && tint[i].A > 0 ? tint[i] : Color(120, 170, 255);

            // The cloud: a few soft puffs, higher and thicker where it rains harder.
            float top = 7 + v * 20;
            int puffs = 1 + (int)(v * 3);
            for (int k = 0; k < puffs; k++)
            {
                float h1 = Hash(i * 13 + k), h2 = Hash(i * 31 + k + 7);
                float shade = 0.55f + 0.45f * h2;
                clouds.Add(x + (h1 - 0.5f) * 0.9f, top + (h2 - 0.3f) * 3 * v, z + (h2 - 0.5f) * 0.9f,
                           Color(tc.R * 0.45f * shade + 120, tc.G * 0.45f * shade + 120, tc.B * 0.35f * shade + 140, (60 + 140 * v) * fade),
                           1.4f + 1.6f * v);
            }

            // The rain: streaks falling from the cloud, pushed by the wind.
            int drops = 1 + (int)(v * 3.5f);
            for (int k = 0; k < drops; k++)
            {
                float phase = Hash(i * 7 + k);
                float fall = (animT * (0.9f + v) / 1.2f + phase) % 1;   // 0 at the cloud, 1 at the ground
                float y = top * (1 - fall);
                float sx0 = x + wx * (top - y) + (phase - 0.5f) * 0.7f, sz0 = z + wz * (top - y);
                float len = 1.2f + 1.5f * v;
                var p = view.Project(new PVector(sx0, y, sz0), Width, Height);
                var q = view.Project(new PVector(sx0 - wx * len, Math.Min(top, y + len), sz0 - wz * len), Width, Height);
                if (p.Depth <= 0.5f || q.Depth <= 0.5f) continue;
                (v > 0.55f ? heavy : light).Add((p.X, p.Y, q.X, q.Y));
                if (v > 0.3f && fall > 0.9f)
                {
                    var g = view.Project(new PVector(x + wx * top + (phase - 0.5f) * 0.7f, 0.05f, z + wz * top), Width, Height);
                    if (g.Depth > 0.5f)
                        splashes.Add((g.X, g.Y, view.Scale(g.Depth, Height) * (fall - 0.9f) * 6, (1 - (fall - 0.9f) * 10) * fade));
                }
            }

            // Lightning where it storms: rare, short, tied to the animation's time.
            if (v > 0.8f)
            {
                int slot = (int)(animT * 3);
                if (Hash(i * 17 + slot * 101) < 0.004f) bolts.Add((x, z, top, i + slot));
            }
        }

        // Splashes: little rings on the ground.
        NoFill();
        StrokeWeight(1);
        foreach (var s in splashes)
        {
            Stroke(190, 220, 255, 200 * s.A);
            Ellipse(s.X, s.Y, s.R * 2, s.R * 2 * Math.Max(0.25f, Sin(pitch)));
        }

        // Rain streaks: two batches of lines.
        StrokeWeight(1);
        Stroke(160, 195, 255, 120);
        DrawLines(light);
        StrokeWeight(1.5f);
        Stroke(200, 225, 255, 190);
        DrawLines(heavy);

        // Lightning: a jagged line and a flash in the cloud.
        foreach (var (bx, bz, top, seed) in bolts)
        {
            StrokeWeight(2);
            Stroke(235, 235, 255, 230);
            float px = bx, pz = bz, py = top;
            var a = view.Project(new PVector(px, py, pz), Width, Height);
            while (py > 0)
            {
                py -= 2;
                px += (Hash(seed * 3 + (int)py) - 0.5f) * 1.2f;
                pz += (Hash(seed * 5 + (int)py) - 0.5f) * 1.2f;
                var b = view.Project(new PVector(px, Math.Max(0, py), pz), Width, Height);
                if (a.Depth > 0.5f && b.Depth > 0.5f) Line(a.X, a.Y, b.X, b.Y);
                a = b;
            }
            clouds.Add(bx, top, bz, Color(255, 255, 255, 200), 9);
        }

        Points(clouds, view);
    }

    void DrawLines(List<(float X0, float Y0, float X1, float Y1)> lines)
    {
        if (lines.Count == 0) return;
        BeginShape(ShapeKind.Lines);
        foreach (var (x0, y0, x1, y1) in lines) { Vertex(x0, y0); Vertex(x1, y1); }
        EndShape();
    }

    static float Hash(int n)
    {
        unchecked
        {
            uint x = (uint)n * 747796405u + 2891336453u;
            x = ((x >> (int)((x >> 28) + 4)) ^ x) * 277803737u;
            return ((x >> 22) ^ x) / 4294967296f;
        }
    }

    /// <summary>A made-up storm (M, or when the radar can't be reached): a spiral band that turns.</summary>
    (float[] Grid, Color[] Tint) Demo()
    {
        var grid = new float[G * G];
        float t = animT * 0.15f;
        var off = Offset();
        for (int r = 0; r < G; r++)
            for (int c = 0; c < G; c++)
            {
                var (wx, wz) = CellPos(c + 0.5f, r + 0.5f, off);
                float x = wx / Window, y = -wz / Window;
                float d = Sqrt(x * x + y * y), a = Atan2(y, x);
                float band = Sin(a * 2 + d * 9 - t * 4) * 0.5f + 0.5f;
                float v = band * Math.Max(0, 1 - d) * (0.6f + 0.8f * Noise(c * 0.08f + t, r * 0.08f));
                grid[r * G + c] = Math.Clamp(v - 0.15f, 0, 1);
            }
        return (grid, null);
    }

    // =====================================================================================
    // Text on screen
    // =====================================================================================
    void Hud(int loaded)
    {
        string where = "the open sea";
        if (countriesReq.Ready)
        {
            var f = countriesReq.Value.FeatureAt(lat, lon);
            if (f != null) where = f.Name;
        }
        float km = 2 * Window * Cell / 256f * 40075f * MathF.Cos(lat * MathF.PI / 180) / (1 << zoomLevel);
        TextFont(font, 22);
        TextAlign(TextAlignH.Left, TextAlignV.Top);
        Fill(235, 240, 255);
        Text(where, 20, 16);
        TextFont(font, 13);
        Fill(170, 185, 215);
        Text($"{Math.Abs(lat):0.0}°{(lat >= 0 ? "N" : "S")} {Math.Abs(lon):0.0}°{(lon >= 0 ? "E" : "W")}  ·  zoom {zoomLevel}  ·  ~{km:N0} km across", 20, 46);
        string when = demo ? "MADE-UP STORM (demo, not real data)"
            : frames.Count > 0 && grids?[shownFrame] != null ? $"radar {DateTimeOffset.FromUnixTimeSeconds(frames[shownFrame].Time).LocalDateTime:HH:mm}  ·  frame {shownFrame + 1}/{frames.Count}"
            : "radar: " + (mapsReq.Done ? $"loading tiles ({loaded}/{frames.Count} frames)" : mapsReq.Status);
        Text(when, 20, 66);
        string wind = windReq == null ? "" : windReq.Ready
            ? $"wind {windKmh:0} km/h from {Compass(windFromDeg)}" + (float.IsNaN(temperature) ? "" : $"  ·  {temperature:0} °C")
            : "wind: " + windReq.Status;
        Text(wind, 20, 86);
        if (paused)
        {
            Fill(255, 210, 120);
            Text("PAUSED", 20, 106);
        }

        // A small compass: where the wind blows to, and north.
        float cx = Width - 60, cy = 60;
        NoFill(); Stroke(255, 255, 255, 60); StrokeWeight(1);
        Circle(cx, cy, 70);
        float north = -Degrees(yaw);
        NoStroke(); Fill(255, 255, 255, 120);
        TextAlign(TextAlignH.Center, TextAlignV.Center);
        Text("N", cx + Sin(Radians(north)) * 44, cy - Cos(Radians(north)) * 44);
        float to = Radians(windFromDeg + 180 + north);
        Stroke(170, 205, 255); StrokeWeight(3);
        Line(cx, cy, cx + Sin(to) * 30, cy - Cos(to) * 30);
        NoStroke(); Fill(255, 255, 255, 120);
        Text("wind", cx, cy + 48);

        TextAlign(TextAlignH.Left, TextAlignV.Bottom);
        Fill(255, 255, 255, 90);
        Text("drag: move · right-drag/Q E R F: turn · wheel/+ -: zoom · arrows: move · 1-6: cities · Space: pause · , .: frames · M: made-up storm", 20, Height - 14);
        Fill(255, 255, 255, 60);
        Text("Radar: RainViewer · Wind: Open-Meteo · Coasts: Natural Earth", 20, Height - 32);
    }

    static string Compass(float deg) => new[] { "N", "NE", "E", "SE", "S", "SW", "W", "NW" }[(int)Math.Round(((deg % 360) + 360) % 360 / 45) % 8];

    // =====================================================================================
    // Input
    // =====================================================================================

    /// <summary>Moves the center by a screen distance: the ground under the mouse follows the mouse.</summary>
    void Move(float dxScreen, float dyScreen)
    {
        // How the screen moves for one cell east and one cell north, near the center: a 2x2 matrix to invert.
        var view = View3D.Orbit(yaw, pitch, 88, new PVector(0, 4, 0), 50);
        var o = view.Project(new PVector(0, 0, 0), Width, Height);
        var e = view.Project(new PVector(1, 0, 0), Width, Height);
        var n = view.Project(new PVector(0, 0, 1), Width, Height);
        float a = e.X - o.X, b = n.X - o.X, c = e.Y - o.Y, d = n.Y - o.Y;
        float det = a * d - b * c;
        if (Math.Abs(det) < 1e-4f) return;
        float east = (d * dxScreen - b * dyScreen) / det, northCells = (-c * dxScreen + a * dyScreen) / det;
        float tx = TileX(lon) - east * Cell / 256f, ty = TileY(lat) + northCells * Cell / 256f;
        int nTiles = 1 << zoomLevel;
        ty = Math.Clamp(ty, 0.5f, nTiles - 0.5f);
        lon = ((LonOf(tx) + 540) % 360) - 180;
        lat = LatOf(ty);
        Retile();
    }

    public override void MouseDragged()
    {
        float dx = MouseX - PMouseX, dy = MouseY - PMouseY;
        if (MouseButton == MouseButtonKind.Right)
        {
            yaw -= dx * 0.008f;
            pitch = Constrain(pitch - dy * 0.008f, 0.2f, 1.5f);
        }
        else Move(dx, dy);
    }

    public override void MouseWheel(float delta) => SetZoom(zoomLevel + (delta > 0 ? -1 : 1));

    void SetZoom(int z)
    {
        z = Math.Clamp(z, MinZoom, MaxZoom);
        if (z == zoomLevel) return;
        Jump(lat, lon, z);
    }

    public override void KeyPressed()
    {
        if (Key >= '1' && Key <= '6') { var p = Places[Key - '1']; Jump(p.Lat, p.Lon, 6); }
        else if (Key == ' ') paused = !paused;
        else if (Key == 'm' || Key == 'M') demo = !demo;
        else if (Key == '+' || Key == '=') SetZoom(zoomLevel + 1);
        else if (Key == '-' || Key == '_') SetZoom(zoomLevel - 1);
        else if (Key == '.') clock = (float)Math.Floor(clock) + 1;
        else if (Key == ',') clock = (float)Math.Floor(clock) - 1;
        else if (Key == 'q' || Key == 'Q') yaw += 0.15f;
        else if (Key == 'e' || Key == 'E') yaw -= 0.15f;
        else if (Key == 'r' || Key == 'R') pitch = Constrain(pitch + 0.1f, 0.2f, 1.5f);
        else if (Key == 'f' || Key == 'F') pitch = Constrain(pitch - 0.1f, 0.2f, 1.5f);
    }
}

// The relief of any country on Earth, as a lit 3D model -- or as contour lines you can
// send to a pen plotter.
//
// Pick a country on the world map. The sketch lays a grid of about 2,000 points over it
// (closer together for small countries, farther apart for big ones), keeps the ones that
// fall inside its outline, and asks Open Topo Data (https://www.opentopodata.org, free and
// keyless) for their heights: 100 points per call, one call a second, each call cached on
// disk for a month. The country appears flat at once, with its real shape, and rises piece
// by piece as the heights arrive.
//
// - T: the terrain, a mesh colored by altitude and lit from the north-west.
// - C: contour lines every N meters (thicker every 5th), computed with marching squares
//   and drawn at their height.
// - S: save the contours as a plotter-ready SVG, seen from above: BeginRaw(path, plotter:
//   true) puts each pen color on its own layer and orders the strokes so the pen barely
//   travels in the air.
//
// Click a country to fly there.  M (or the little map): back to the world.  R: a random
// country.  Drag: turn.  Wheel: zoom.  Up/Down: heights.
public class TerrainAnywhere : Sketch
{
    // ---- settings -----------------------------------------------------------------------
    const string Dataset = "mapzen";             // global, with the sea floor; also srtm90m, aster30m, etopo1...
    const int Target = 2000;                     // about this many heights per country -> ~20-25 calls
    const float W = 60;                          // the country's longest side, in world units
    const string CountriesUrl = "https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_50m_admin_0_countries.geojson";

    // ---- the world map ------------------------------------------------------------------
    Request<GeoMap> countriesReq;
    PGraphics worldMap;
    float mapY = 70;                             // where the big map starts
    GeoFeature hover, country;
    bool picking = true;

    // ---- the chosen country -------------------------------------------------------------
    readonly List<(float[] Lat, float[] Lon)> outline = new();    // its rings, longitudes unwrapped near the date line
    readonly List<bool> holes = new();
    float lat0, lon0, minLat, maxLat, minLon, maxLon;
    float kmX, kmZ;                              // km per degree of longitude / latitude here
    float scale;                                 // world units per km
    int nx, ny;                                  // grid size
    float dLat, dLon;                            // grid step in degrees
    bool[] inside, wanted;                       // in the country / worth asking (inside, or right next to it)
    int[] asked;                                 // grid indices, in the order they're asked for
    float[] height;                              // meters; NaN until it arrives
    long[] arrivedAt;
    Request<JSONObject>[] calls;
    bool[] read;
    int nextCall, arrived, failed;
    long lastCall = -10000;
    float lo, hi;
    bool made;                                   // made-up terrain (offline)

    // ---- view ---------------------------------------------------------------------------
    PFont font;
    bool contours;
    float yaw = -0.5f, pitch = 0.75f, zoom = 1, heightMul = 1, shownEx = -1;
    string saved = "";
    long savedAt;
    float pressX, pressY;

    public override void Setup()
    {
        Size(1000, 640);
        font = CreateFont("Segoe UI", 14);
        countriesReq = RequestGeoJSON(CountriesUrl, cacheFor: TimeSpan.FromDays(365));
    }

    // =====================================================================================
    // Choosing a country
    // =====================================================================================

    /// <summary>
    /// Keeps the part of the country around the click (or its biggest piece) and the islands
    /// near it -- so France is France, not France plus French Guiana -- and lays the grid.
    /// </summary>
    void Choose(GeoFeature f, float clickLat, float clickLon)
    {
        country = f;
        picking = false;
        outline.Clear(); holes.Clear();

        // The main piece: the ring under the click, or the biggest.
        GeoRing main = null; float best = -1;
        foreach (var ring in f.Rings)
        {
            if (ring.IsHole) continue;
            if (InRing(ring.Lat, ring.Lon, clickLat, clickLon)) { main = ring; break; }
            float area = Area(ring);
            if (area > best) { best = area; main = ring; }
        }
        if (main == null) return;
        var (mLat0, mLat1, mLon0, mLon1) = Box(main.Lat, main.Lon);
        float mainLon = (mLon0 + mLon1) / 2;

        // Other pieces close to it come along (shifted a whole turn if they're across the date line).
        float reach = Math.Max(1.5f, 0.4f * Math.Max(mLat1 - mLat0, mLon1 - mLon0));
        foreach (var ring in f.Rings)
        {
            if (ring.IsHole) continue;
            var (a0, a1, o0, o1) = Box(ring.Lat, ring.Lon);
            float shift = 360 * MathF.Round((mainLon - (o0 + o1) / 2) / 360);
            if (a1 < mLat0 - reach || a0 > mLat1 + reach || o1 + shift < mLon0 - reach || o0 + shift > mLon1 + reach) continue;
            var lon = (float[])ring.Lon.Clone();
            for (int i = 0; i < lon.Length; i++) lon[i] += shift;
            outline.Add((ring.Lat, lon)); holes.Add(false);
        }
        // Holes (lakes, enclaves) that fall inside what we kept.
        foreach (var ring in f.Rings)
            if (ring.IsHole && In(ring.Lat[0], ring.Lon[0]))
            {
                outline.Add((ring.Lat, ring.Lon)); holes.Add(true);
            }

        minLat = minLon = float.MaxValue; maxLat = maxLon = float.MinValue;
        for (int k = 0; k < outline.Count; k++)
        {
            if (holes[k]) continue;
            var (a0, a1, o0, o1) = Box(outline[k].Lat, outline[k].Lon);
            minLat = Math.Min(minLat, a0); maxLat = Math.Max(maxLat, a1);
            minLon = Math.Min(minLon, o0); maxLon = Math.Max(maxLon, o1);
        }
        lat0 = (minLat + maxLat) / 2; lon0 = (minLon + maxLon) / 2;
        kmX = 111.32f * MathF.Cos(lat0 * MathF.PI / 180); kmZ = 110.57f;
        float wKm = (maxLon - minLon) * kmX, hKm = (maxLat - minLat) * kmZ;
        scale = W / Math.Max(wKm, hKm);

        // How much of the box is the country? Then the spacing that gives ~Target points inside it.
        int hits = 0;
        for (int i = 0; i < 40; i++)
            for (int j = 0; j < 40; j++)
                if (In(minLat + (maxLat - minLat) * (i + 0.5f) / 40, minLon + (maxLon - minLon) * (j + 0.5f) / 40)) hits++;
        float fraction = Math.Max(hits / 1600f, 0.03f);
        float spacing = Math.Max(0.3f, MathF.Sqrt(fraction * wKm * hKm / Target));
        nx = Math.Clamp((int)MathF.Ceiling(wKm / spacing) + 1, 3, 300);
        ny = Math.Clamp((int)MathF.Ceiling(hKm / spacing) + 1, 3, 300);
        dLon = (maxLon - minLon) / (nx - 1); dLat = (maxLat - minLat) / (ny - 1);

        inside = new bool[nx * ny];
        for (int r = 0; r < ny; r++)
            for (int c = 0; c < nx; c++)
                inside[r * nx + c] = In(minLat + r * dLat, minLon + c * dLon);
        // Also ask for the points just outside the border, so the mesh reaches the coast.
        wanted = new bool[nx * ny];
        var list = new List<int>();
        for (int r = 0; r < ny; r++)
            for (int c = 0; c < nx; c++)
            {
                bool w = false;
                for (int dr = -1; dr <= 1 && !w; dr++)
                    for (int dc = -1; dc <= 1 && !w; dc++)
                    {
                        int rr = r + dr, cc = c + dc;
                        w = rr >= 0 && cc >= 0 && rr < ny && cc < nx && inside[rr * nx + cc];
                    }
                wanted[r * nx + c] = w;
                if (w) list.Add(r * nx + c);
            }
        asked = list.ToArray();
        height = new float[nx * ny];
        Array.Fill(height, float.NaN);
        arrivedAt = new long[nx * ny];
        calls = new Request<JSONObject>[(asked.Length + 99) / 100];
        read = new bool[calls.Length];
        nextCall = 0; arrived = 0; failed = 0; made = false;
        lo = 0; hi = 0;
        segments = null;
        shownEx = -1;
    }

    static float Area(GeoRing ring)
    {
        float a = 0;
        for (int i = 0, j = ring.Count - 1; i < ring.Count; j = i++)
            a += (ring.Lon[j] - ring.Lon[i]) * (ring.Lat[j] + ring.Lat[i]);
        return Math.Abs(a) * MathF.Cos(ring.Lat[0] * MathF.PI / 180);
    }

    static (float, float, float, float) Box(float[] la, float[] lo)
    {
        float a0 = float.MaxValue, a1 = float.MinValue, o0 = float.MaxValue, o1 = float.MinValue;
        for (int i = 0; i < la.Length; i++)
        {
            a0 = Math.Min(a0, la[i]); a1 = Math.Max(a1, la[i]);
            o0 = Math.Min(o0, lo[i]); o1 = Math.Max(o1, lo[i]);
        }
        return (a0, a1, o0, o1);
    }

    static bool InRing(float[] la, float[] lo, float lat, float lon)
    {
        bool inside = false;
        for (int i = 0, j = la.Length - 1; i < la.Length; j = i++)
            if ((la[i] > lat) != (la[j] > lat) && lon < (lo[j] - lo[i]) * (lat - la[i]) / (la[j] - la[i]) + lo[i])
                inside = !inside;
        return inside;
    }

    /// <summary>Inside the kept part of the country (even-odd over its rings, so holes stay out).</summary>
    bool In(float lat, float lon)
    {
        bool inside = false;
        foreach (var (la, lo) in outline)
            if (InRing(la, lo, lat, lon)) inside = !inside;
        return inside;
    }

    // =====================================================================================
    // Loading: one call a second, 100 points each
    // =====================================================================================
    string CallUrl(string locations) => $"https://api.opentopodata.org/v1/{Dataset}?locations={locations}";

    void Load()
    {
        if (country == null || made) return;
        if (nextCall < calls.Length && Millis() - lastCall > 1100)
        {
            var points = new System.Text.StringBuilder();
            for (int k = nextCall * 100; k < Math.Min(asked.Length, nextCall * 100 + 100); k++)
            {
                int i = asked[k];
                float la = minLat + i / nx * dLat, lo2 = minLon + i % nx * dLon;
                lo2 = ((lo2 + 540) % 360) - 180;                 // back to -180..180 for the API
                if (points.Length > 0) points.Append("%7C");     // "|", escaped
                points.Append(la.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture)).Append(',')
                      .Append(lo2.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture));
            }
            calls[nextCall] = RequestJSONObject(CallUrl(points.ToString()), cacheFor: TimeSpan.FromDays(30));
            nextCall++;
            lastCall = Millis();
        }
        for (int k = 0; k < calls.Length; k++)
        {
            var call = calls[k];
            if (call == null || read[k] || !call.Done) continue;
            read[k] = true;
            if (call.Failed) { failed++; continue; }
            if (call.FromCache) lastCall -= 1100;               // cached: no need to wait for the next one
            var results = call.Value.GetJSONArray("results");
            for (int j = 0; results != null && j < results.Size() && k * 100 + j < asked.Length; j++)
            {
                // "elevation" is null where the dataset has no data: count it as sea level.
                float e = results.GetJSONObject(j).GetFloat("elevation", 0);
                int i = asked[k * 100 + j];
                height[i] = e;
                arrivedAt[i] = Millis();
                if (inside[i]) { lo = Math.Min(lo, e); hi = Math.Max(hi, e); }
                arrived++;
            }
        }
        // Offline: after two failed calls, a made-up terrain, clearly labelled.
        if (failed >= 2)
        {
            made = true;
            foreach (int i in asked)
            {
                float x = i % nx / (float)nx, y = i / nx / (float)ny;
                height[i] = 2500 * MathF.Pow(Noise(x * 3, y * 3), 2) + 300 * Noise(x * 14, y * 14);
                arrivedAt[i] = Millis();
                hi = Math.Max(hi, height[i]);
            }
            arrived = asked.Length;
        }
    }

    // =====================================================================================
    // Geometry
    // =====================================================================================

    /// <summary>The height to draw (m): rising from 0 for a second after it arrives; NaN if not asked.</summary>
    float Shown(int i)
    {
        if (!wanted[i]) return float.NaN;
        float h = height[i];
        if (float.IsNaN(h)) return 0;
        float t = Math.Clamp((Millis() - arrivedAt[i]) / 900f, 0, 1);
        h = inside[i] ? h : Math.Max(h, 0);                      // just outside: no sea floor
        return h * (1 - (1 - t) * (1 - t) * (1 - t));
    }

    /// <summary>The automatic exaggeration: the highest peak stands at ~10% of the width (flat countries get more).</summary>
    float Exaggeration()
    {
        float auto = Math.Clamp(0.1f * W / (Math.Max(hi, 300) / 1000 * scale), 1, 120);
        float target = auto * heightMul;
        shownEx = shownEx < 0 ? target : Lerp(shownEx, target, 0.08f);
        return shownEx;
    }

    PVector World(float c, float r, float meters, float ex) =>
        new PVector((minLon + c * dLon - lon0) * kmX * scale, meters / 1000 * scale * ex, (minLat + r * dLat - lat0) * kmZ * scale);

    PVector WorldLatLon(float lat, float lon, float meters, float ex) =>
        new PVector((lon - lon0) * kmX * scale, meters / 1000 * scale * ex, (lat - lat0) * kmZ * scale);

    /// <summary>The drawn height (m) at a fractional grid position, bilinear.</summary>
    float At(float gx, float gy, float[] shown)
    {
        int x0 = Math.Clamp((int)gx, 0, nx - 2), y0 = Math.Clamp((int)gy, 0, ny - 2);
        float fx = Math.Clamp(gx - x0, 0, 1), fy = Math.Clamp(gy - y0, 0, 1);
        float H(int c, int r) { float v = shown[r * nx + c]; return float.IsNaN(v) ? 0 : v; }
        return Lerp(Lerp(H(x0, y0), H(x0 + 1, y0), fx), Lerp(H(x0, y0 + 1), H(x0 + 1, y0 + 1), fx), fy);
    }

    // =====================================================================================
    // Each frame
    // =====================================================================================
    public override void Draw()
    {
        Background(8, 12, 20);
        if (!countriesReq.Ready)
        {
            Loading();
            return;
        }
        if (worldMap == null) BuildWorldMap();
        if (picking) { DrawPicker(); return; }

        Load();
        float ex = Exaggeration();
        var view = View3D.Orbit(yaw, pitch, 72 / zoom, new PVector(0, 2, 0), 45);
        var shown = new float[nx * ny];
        for (int i = 0; i < shown.Length; i++) shown[i] = Shown(i);

        DrawOutline(view, shown, ex, ground: true);
        if (contours) DrawContours(view, shown, ex);
        else DrawMesh(view, shown, ex);
        DrawOutline(view, shown, ex, ground: false);
        DrawPeak(view, shown, ex);
        Hud(ex);
        MiniMap();
    }

    /// <summary>The terrain as triangles, far ones first, each corner colored by height and lit by its slope.</summary>
    void DrawMesh(View3D view, float[] shown, float ex)
    {
        var sx = new float[nx * ny]; var sy = new float[nx * ny]; var depth = new float[nx * ny];
        var col = new Color[nx * ny];
        float stepX = dLon * kmX * scale, stepZ = dLat * kmZ * scale;
        float hScale = scale * ex / 1000;
        var light = new PVector(-0.55f, 0.75f, 0.45f);            // from the north-west, above
        light.Normalize();
        float top = Math.Max(hi, 400);
        for (int i = 0; i < nx * ny; i++)
        {
            if (!wanted[i]) continue;
            int c = i % nx, r = i / nx;
            var (x, y, d) = view.Project(World(c, r, shown[i], ex), Width, Height);
            sx[i] = x; sy[i] = y; depth[i] = d;
            // The slope from the neighbors, in world units -> a normal -> how much light it catches.
            float hl = Neighbor(shown, c - 1, r, shown[i]), hr = Neighbor(shown, c + 1, r, shown[i]);
            float hd = Neighbor(shown, c, r - 1, shown[i]), hu = Neighbor(shown, c, r + 1, shown[i]);
            var n = new PVector(-(hr - hl) * hScale / (2 * stepX), 1, -(hu - hd) * hScale / (2 * stepZ));
            n.Normalize();
            float lit = 0.35f + 0.8f * Math.Max(0, n.X * light.X + n.Y * light.Y + n.Z * light.Z);
            col[i] = float.IsNaN(height[i]) ? Color(38, 52, 72) : Shade(Hypsometric(shown[i], top), lit, inside[i] ? 255 : 150);
        }

        var quads = new List<(float D, int I)>(nx * ny);
        for (int r = 0; r < ny - 1; r++)
            for (int c = 0; c < nx - 1; c++)
            {
                int a = r * nx + c, b = a + 1, e = a + nx, f = e + 1;
                if (!wanted[a] || !wanted[b] || !wanted[e] || !wanted[f]) continue;
                if (!inside[a] && !inside[b] && !inside[e] && !inside[f]) continue;
                if (depth[a] <= 0.5f || depth[b] <= 0.5f || depth[e] <= 0.5f || depth[f] <= 0.5f) continue;
                quads.Add((depth[a] + depth[b] + depth[e] + depth[f], a));
            }
        quads.Sort((p, q) => q.D.CompareTo(p.D));                // far first: near triangles paint over

        NoStroke();
        BeginShape(ShapeKind.Triangles);
        foreach (var (_, a) in quads)
        {
            int b = a + 1, e = a + nx, f = e + 1;
            V(a); V(b); V(f);
            V(a); V(f); V(e);
        }
        EndShape();

        void V(int i) { Fill(col[i]); Vertex(sx[i], sy[i]); }
    }

    float Neighbor(float[] shown, int c, int r, float fallback)
    {
        if (c < 0 || r < 0 || c >= nx || r >= ny) return fallback;
        float v = shown[r * nx + c];
        return float.IsNaN(v) ? fallback : v;
    }

    /// <summary>Altitude colors, like a school atlas: green lowlands, yellow and brown hills, grey rock, snow.</summary>
    Color Hypsometric(float h, float top)
    {
        float k = Math.Clamp(top / 4500, 0.25f, 1);              // a low country still gets the whole range
        (float H, int R, int G, int B)[] stops =
        {
            (0, 60, 130, 85), (250, 105, 160, 90), (700, 190, 185, 110), (1400, 175, 130, 80),
            (2300, 140, 110, 95), (3300, 205, 205, 210), (4500, 250, 250, 255),
        };
        for (int s = 1; s < stops.Length; s++)
        {
            float h1 = stops[s].H * k;
            if (h <= h1 || s == stops.Length - 1)
            {
                float h0 = stops[s - 1].H * k;
                float t = Math.Clamp((h - h0) / Math.Max(1, h1 - h0), 0, 1);
                return Color(Lerp(stops[s - 1].R, stops[s].R, t), Lerp(stops[s - 1].G, stops[s].G, t), Lerp(stops[s - 1].B, stops[s].B, t));
            }
        }
        return Color(255, 255, 255);
    }

    Color Shade(Color c, float lit, float alpha) =>
        Color(Math.Min(255, c.R * lit), Math.Min(255, c.G * lit), Math.Min(255, c.B * lit), alpha);

    /// <summary>The border: on the ground as a faint shadow, and on the surface as a bright line.</summary>
    void DrawOutline(View3D view, float[] shown, float ex, bool ground)
    {
        var segs = new List<(float, float, float, float)>();
        for (int k = 0; k < outline.Count; k++)
        {
            var (la, lo) = outline[k];
            int step = Math.Max(1, la.Length / 1500);
            (float X, float Y, float D) prev = default;
            for (int i = 0; i <= la.Length; i += step)
            {
                int j = Math.Min(i, la.Length - 1);
                float m = ground ? 0 : At((lo[j] - minLon) / dLon, (la[j] - minLat) / dLat, shown) + 15;
                var p = view.Project(WorldLatLon(la[j], lo[j], m, ex), Width, Height);
                if (i > 0 && p.Depth > 0.5f && prev.D > 0.5f) segs.Add((prev.X, prev.Y, p.X, p.Y));
                prev = p;
            }
        }
        StrokeWeight(ground ? 1 : 1.2f);
        if (ground) Stroke(120, 150, 190, 60); else Stroke(255, 255, 255, contours ? 120 : 150);
        BeginShape(ShapeKind.Lines);
        foreach (var (x0, y0, x1, y1) in segs) { Vertex(x0, y0); Vertex(x1, y1); }
        EndShape();
    }

    /// <summary>The highest point: a marker and its height.</summary>
    void DrawPeak(View3D view, float[] shown, float ex)
    {
        int best = -1;
        for (int i = 0; i < nx * ny; i++)
            if (inside[i] && !float.IsNaN(height[i]) && (best < 0 || height[i] > height[best])) best = i;
        if (best < 0 || height[best] <= 0) return;
        var (sx, sy, d) = view.Project(World(best % nx, best / nx, shown[best], ex), Width, Height);
        if (d <= 0) return;
        Stroke(255, 200, 90); StrokeWeight(1.5f);
        Line(sx, sy, sx, sy - 30);
        NoStroke(); Fill(255, 200, 90);
        Triangle(sx - 6, sy - 30, sx + 6, sy - 30, sx, sy - 40);
        TextFont(font, 13);
        TextAlign(TextAlignH.Center, TextAlignV.Bottom);
        Fill(255, 235, 200);
        Text($"{height[best]:N0} m", sx, sy - 44);
    }

    // =====================================================================================
    // Contours
    // =====================================================================================

    /// <summary>Contour spacing: a round number giving ~16 lines over the range (10, 20, 50, 100, 200 m...).</summary>
    float Interval()
    {
        float raw = Math.Max(1, hi) / 16;
        float p = MathF.Pow(10, MathF.Floor(MathF.Log10(raw)));
        return raw / p < 1.5f ? p : raw / p < 3.5f ? 2 * p : raw / p < 7.5f ? 5 * p : 10 * p;
    }

    /// <summary>
    /// Marching squares: for each level, every grid square whose corners straddle it gets a
    /// segment between the edge crossings. Calls <paramref name="segment"/>(level index,
    /// height, start, end) with grid coordinates. Only squares inside the country count.
    /// </summary>
    void MarchingSquares(Action<int, float, (float X, float Y), (float X, float Y)> segment)
    {
        float interval = Interval();
        float H(int c, int r) { int i = r * nx + c; return wanted[i] ? height[i] : float.NaN; }
        int last = (int)MathF.Floor(hi / interval);
        for (int li = 1; li <= last; li++)
        {
            float level = li * interval;
            for (int r = 0; r < ny - 1; r++)
                for (int c = 0; c < nx - 1; c++)
                {
                    int i = r * nx + c;
                    if (!inside[i] && !inside[i + 1] && !inside[i + nx] && !inside[i + nx + 1]) continue;
                    float a = H(c, r), b = H(c + 1, r), d = H(c, r + 1), e = H(c + 1, r + 1);
                    if (float.IsNaN(a) || float.IsNaN(b) || float.IsNaN(d) || float.IsNaN(e)) continue;
                    int code = (a > level ? 8 : 0) | (b > level ? 4 : 0) | (e > level ? 2 : 0) | (d > level ? 1 : 0);
                    if (code == 0 || code == 15) continue;
                    // Where the level crosses each edge: a-b, b-e, d-e, a-d.
                    (float, float) Top() => (c + (level - a) / (b - a), r);
                    (float, float) Right() => (c + 1, r + (level - b) / (e - b));
                    (float, float) Bottom() => (c + (level - d) / (e - d), r + 1);
                    (float, float) Left() => (c, r + (level - a) / (d - a));
                    switch (code)
                    {
                        case 1: case 14: segment(li, level, Left(), Bottom()); break;
                        case 2: case 13: segment(li, level, Bottom(), Right()); break;
                        case 3: case 12: segment(li, level, Left(), Right()); break;
                        case 4: case 11: segment(li, level, Top(), Right()); break;
                        case 6: case 9: segment(li, level, Top(), Bottom()); break;
                        case 7: case 8: segment(li, level, Left(), Top()); break;
                        case 5: segment(li, level, Left(), Top()); segment(li, level, Bottom(), Right()); break;
                        case 10: segment(li, level, Top(), Right()); segment(li, level, Left(), Bottom()); break;
                    }
                }
        }
    }

    // The contour segments only change when new heights arrive: computed once, then reused.
    List<(int Li, float Level, (float X, float Y) P, (float X, float Y) Q)> segments;
    int segmentsFor = -1;

    List<(int Li, float Level, (float X, float Y) P, (float X, float Y) Q)> Segments()
    {
        if (segmentsFor != arrived || segments == null)
        {
            segments = new();
            MarchingSquares((li, level, p, q) => segments.Add((li, level, p, q)));
            segmentsFor = arrived;
        }
        return segments;
    }

    void DrawContours(View3D view, float[] shown, float ex)
    {
        float top = Math.Max(hi, 1);
        foreach (var (li, level, p, q) in Segments())
        {
            float rise = Math.Min(Shown(Nearest(p)) / Math.Max(1, height[Nearest(p)]), 1);   // contours rise with the land
            if (float.IsNaN(rise) || rise < 0) rise = 1;
            var (x0, y0, d0) = view.Project(World(p.X, p.Y, level * rise, ex), Width, Height);
            var (x1, y1, d1) = view.Project(World(q.X, q.Y, level * rise, ex), Width, Height);
            if (d0 <= 0 || d1 <= 0) continue;
            float t = level / top;
            bool index = li % 5 == 0;
            Stroke(Lerp(90, 255, t), Lerp(200, 220, t), Lerp(160, 140, t), index ? 255 : 170);
            StrokeWeight(index ? 2 : 1);
            Line(x0, y0, x1, y1);
        }
    }

    int Nearest((float X, float Y) p) => Math.Clamp((int)MathF.Round(p.Y), 0, ny - 1) * nx + Math.Clamp((int)MathF.Round(p.X), 0, nx - 1);

    // =====================================================================================
    // The plotter SVG: the contours and the border seen from straight above, two pens
    // =====================================================================================
    void SaveSvg()
    {
        string name = string.Concat(country.Name.Where(char.IsLetterOrDigit)).ToLowerInvariant();
        string file = $"contours-{name}.svg";
        float margin = 50;
        float wKm = (maxLon - minLon) * kmX, hKm = (maxLat - minLat) * kmZ;
        float s = Math.Min((Width - 2 * margin) / wKm, (Height - 2 * margin) / hKm);   // pixels per km, north up
        float left = (Width - wKm * s) / 2, topY = (Height - hKm * s) / 2;
        float PX(float lon) => left + (lon - minLon) * kmX * s;
        float PY(float lat) => topY + (maxLat - lat) * kmZ * s;

        BeginRaw(file, plotter: true);
        Background(255);
        NoFill();
        foreach (var (li, level, p, q) in Segments())
        {
            bool index = li % 5 == 0;
            Stroke(index ? Color(120, 60, 20) : Color(0, 0, 0));    // two pens: brown index lines, black the rest
            StrokeWeight(index ? 1.2f : 0.6f);
            Line(PX(minLon + p.X * dLon), PY(minLat + p.Y * dLat), PX(minLon + q.X * dLon), PY(minLat + q.Y * dLat));
        }
        Stroke(0, 0, 0);
        StrokeWeight(1);
        for (int k = 0; k < outline.Count; k++)
        {
            var (la, lo) = outline[k];
            for (int i = 1; i < la.Length; i++) Line(PX(lo[i - 1]), PY(la[i - 1]), PX(lo[i]), PY(la[i]));
        }
        Fill(0);
        TextFont(font, 14);
        TextAlign(TextAlignH.Left, TextAlignV.Top);
        Text($"{country.Name}  ·  contours every {Interval():N0} m", margin, 16);
        EndRaw();
        saved = file;
        savedAt = Millis();
    }

    // =====================================================================================
    // The world map: pick a country
    // =====================================================================================
    void BuildWorldMap()
    {
        worldMap = CreateGraphics(Width, Width / 2);
        worldMap.BeginDraw();
        worldMap.Background(10, 16, 28);
        worldMap.Stroke(255, 255, 255, 18);
        for (int lo = -180; lo <= 180; lo += 30) worldMap.Line((lo + 180) / 360f * Width, 0, (lo + 180) / 360f * Width, Width / 2);
        for (int la = -60; la <= 60; la += 30) worldMap.Line(0, (90 - la) / 180f * Width / 2, Width, (90 - la) / 180f * Width / 2);
        worldMap.Fill(48, 70, 92);
        worldMap.Stroke(110, 140, 170);
        worldMap.StrokeWeight(0.5f);
        foreach (var f in countriesReq.Value.Features) Shape(worldMap, f, Width, Width / 2, 0, 0);
        worldMap.EndDraw();
    }

    /// <summary>A country's outlines, filled, on an equirectangular map of size w x h at (x, y).</summary>
    static void Shape(GraphicsContext g, GeoFeature f, float w, float h, float x, float y)
    {
        foreach (var ring in f.Rings)
        {
            if (ring.IsHole) continue;
            g.BeginShape();
            for (int i = 0; i < ring.Count; i++)
            {
                var (px, py) = Geo.Equirectangular(ring.Lat[i], ring.Lon[i], w, h);
                g.Vertex(x + px, y + py);
            }
            g.EndShape(true);
        }
    }

    void DrawPicker()
    {
        Image(worldMap, 0, mapY);
        hover = MouseY > mapY && MouseY < mapY + Width / 2 ? FeatureUnder(MouseX, MouseY - mapY, Width) : null;
        if (hover != null)
        {
            Fill(255, 200, 90);
            Stroke(255, 240, 200);
            StrokeWeight(1);
            Shape(this, hover, Width, Width / 2, 0, mapY);
        }
        TextFont(font, 22);
        TextAlign(TextAlignH.Left, TextAlignV.Top);
        Fill(235, 240, 255);
        Text(hover?.Name ?? "Pick a country", 20, 16);
        TextFont(font, 13);
        Fill(170, 185, 215);
        Text(hover != null ? "click to see its relief" : "click any country to see its relief · R: a random one", 20, 46);
        TextAlign(TextAlignH.Left, TextAlignV.Bottom);
        Fill(255, 255, 255, 60);
        Text($"Borders: Natural Earth · Elevation: Open Topo Data ({Dataset}) · 1 call/s, 1,000 calls a day: each country is cached for a month", 20, Height - 14);
    }

    GeoFeature FeatureUnder(float x, float y, float w)
    {
        var (la, lo) = Geo.FromEquirectangular(x, y, w, w / 2);
        return countriesReq.Value.FeatureAt(la, lo);
    }

    /// <summary>The world, small, in a corner: the chosen country lit. Click it to go back.</summary>
    void MiniMap()
    {
        float mw = 200, mh = 100, mx = Width - mw - 16, my = 16;
        Tint(255, 255, 255, 200);
        Image(worldMap, mx, my, mw, mh);
        NoTint();
        Fill(255, 200, 90);
        NoStroke();
        Shape(this, country, mw, mh, mx, my);
        NoFill();
        Stroke(255, 255, 255, 60);
        Rect(mx, my, mw, mh, 4);
        Fill(255, 255, 255, 110);
        TextFont(font, 11);
        TextAlign(TextAlignH.Right, TextAlignV.Top);
        Text("M: world map", mx + mw, my + mh + 4);
    }

    void Loading()
    {
        TextFont(font, 16);
        TextAlign(TextAlignH.Center, TextAlignV.Center);
        Fill(170, 185, 215);
        Text("countries: " + countriesReq.Status, Width / 2, Height / 2);
    }

    // =====================================================================================
    // Text on screen
    // =====================================================================================
    void Hud(float ex)
    {
        float wKm = (maxLon - minLon) * kmX, hKm = (maxLat - minLat) * kmZ;
        float spacing = dLon * kmX;
        TextFont(font, 22);
        TextAlign(TextAlignH.Left, TextAlignV.Top);
        Fill(235, 240, 255);
        Text(country.Name, 20, 16);
        TextFont(font, 13);
        Fill(170, 185, 215);
        Text($"~{wKm:N0} x {hKm:N0} km  ·  a height every {spacing:0.#} km  ·  heights x{ex:0.#}", 20, 46);
        if (arrived > 0)
            Text($"up to {hi:N0} m{(contours ? $"  ·  contours every {Interval():N0} m" : "")}", 20, 66);
        if (made)
        {
            Fill(255, 170, 110);
            Text("no connection: MADE-UP terrain (not real data)", 20, 86);
        }
        else if (arrived < asked.Length)
        {
            // Loading: the points that came in, and the call that's out.
            var call = calls[Math.Max(0, nextCall - 1)];
            Fill(255, 255, 255, 30);
            Rect(20, 92, 260, 5, 2);
            Fill(90, 190, 255);
            Rect(20, 92, 260f * arrived / asked.Length, 5, 2);
            Fill(170, 185, 215);
            Text($"heights {arrived:N0} / {asked.Length:N0}  ·  call {nextCall}/{calls.Length}: {call?.Status ?? "..."}", 20, 102);
        }
        if (saved != "" && Millis() - savedAt < 4000)
        {
            Fill(150, 230, 170);
            TextAlign(TextAlignH.Right, TextAlignV.Top);
            Text($"saved {saved} (plotter-ready: 2 pens)", Width - 20, 140);
        }
        TextAlign(TextAlignH.Left, TextAlignV.Bottom);
        Fill(255, 255, 255, 90);
        Text("M: world map · R: random country · T: terrain · C: contours · S: save plotter SVG · drag: turn · wheel: zoom · Up/Down: heights", 20, Height - 14);
        Fill(255, 255, 255, 60);
        Text($"Elevation: Open Topo Data ({Dataset}) · Borders: Natural Earth", 20, Height - 32);
    }

    // =====================================================================================
    // Input
    // =====================================================================================
    public override void MousePressed() { pressX = MouseX; pressY = MouseY; }

    public override void MouseReleased()
    {
        if (Dist(pressX, pressY, MouseX, MouseY) > 5 || !countriesReq.Ready) return;    // a drag, not a click
        if (picking)
        {
            if (MouseY < mapY || MouseY > mapY + Width / 2) return;
            var (la, lo) = Geo.FromEquirectangular(MouseX, MouseY - mapY, Width, Width / 2);
            var f = countriesReq.Value.FeatureAt(la, lo);
            if (f != null) Choose(f, la, lo);
        }
        else if (MouseX > Width - 216 && MouseY < 116) picking = true;
    }

    public override void MouseDragged()
    {
        if (picking) return;
        yaw -= (MouseX - PMouseX) * 0.008f;
        pitch = Constrain(pitch - (MouseY - PMouseY) * 0.008f, 0.1f, 1.5f);
    }

    public override void MouseWheel(float delta) => zoom = Constrain(zoom * (delta > 0 ? 1 / 1.1f : 1.1f), 0.5f, 6);

    public override void KeyPressed()
    {
        if (Key == 'm' || Key == 'M' || Key == '\t') { if (country != null) picking = !picking; }
        else if ((Key == 'r' || Key == 'R') && countriesReq.Ready) RandomCountry();
        else if (picking) return;
        else if (Key == 't' || Key == 'T') contours = false;
        else if (Key == 'c' || Key == 'C') contours = true;
        else if ((Key == 's' || Key == 'S') && arrived > 0) SaveSvg();
        else if (KeyCode == UP) heightMul = Math.Min(4, heightMul * 1.25f);
        else if (KeyCode == DOWN) heightMul = Math.Max(0.25f, heightMul / 1.25f);
    }

    void RandomCountry()
    {
        var all = countriesReq.Value.Features;
        var f = all[(int)Random(all.Count)];
        Choose(f, float.NaN, float.NaN);
    }
}

// A living country: its relief in detail, its weather right now and for the next two days,
// and water that falls as the real rain and runs downhill into rivers and lakes.
//
// Pick a country on the world map. Three free, keyless sources load in the background:
// - the relief: Terrain Tiles on AWS (Mapzen's "terrarium" PNGs), a height in every pixel
//   -- (red * 256 + green + blue / 256) - 32768 meters -- read with img.Pixels. About
//   180 heights along the country's longest side, for its real outline.
// - the weather: Open-Meteo, one call for ~25 points over the country: temperature,
//   clouds, rain and wind now, and hour by hour for 48 hours.
// - the outlines: Natural Earth.
//
// The water is a "virtual pipes" simulation: every cell holds some water and pushes it to
// its four neighbors through pipes, more the steeper the water surface. Rain adds water
// where the forecast says it rains (a lot faster than real life, so you see it), the sun
// takes some back (more where it's hot), and it drains out at the coast and the borders.
// Rivers find the valleys by themselves; lakes fill the basins.
//
// Click the land: drop a lake there.  D: a five-second deluge everywhere.
// L: layer -- relief / temperature / rain.  Space: pause.  , and .: hour back / forward.
// M (or the little map): the world.  R: a random country.  Drag: turn.  Wheel: zoom.
// Up/Down: heights.  W: empty the water.
public class LivingCountry : Sketch
{
    // ---- settings -----------------------------------------------------------------------
    const int Cells = 180;                       // grid points along the country's longest side
    const float W = 60;                          // that side, in world units
    const float RainSpeed = 0.0004f;             // world units of water per second, per mm/h of rain
    const string CountriesUrl = "https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_50m_admin_0_countries.geojson";

    // ---- the world map ------------------------------------------------------------------
    Request<GeoMap> countriesReq;
    PGraphics worldMap;
    float mapY = 70;
    GeoFeature hover, country;
    bool picking = true;

    // ---- the chosen country -------------------------------------------------------------
    readonly List<(float[] Lat, float[] Lon)> outline = new();
    float lat0, lon0, minLat, maxLat, minLon, maxLon, kmX, kmZ, scale, dLat, dLon;
    int nx, ny;
    bool[] inside, drawn;                        // in the country / drawn (inside or touching it)
    float[] meters;                              // terrain height (m), NaN until its tile is in
    long[] arrivedAt;
    int tileZoom, tx0, ty0, tilesW, tilesH;
    Request<PImage>[] tiles;
    bool[] tileRead;
    int heightsIn;
    float hi = 1;

    // ---- the weather --------------------------------------------------------------------
    Request<JSONArray> weatherReq;
    readonly List<(float Lat, float Lon)> stations = new();
    float[][] hourTemp, hourRain, hourCloud;     // [station][hour]
    int[][] hourCode;
    string[] hourTimes;
    int nowHour;                                 // the forecast's index of the current hour
    float hour;                                  // the hour being shown (fractional: it plays)
    float windKmh, windFromDeg;
    bool weatherRead;
    float[] temp, rain, cloud;                   // per grid cell, at the shown hour
    int fieldsForHour = -1;
    float tMin, tMax, rainMax;

    // ---- the water ----------------------------------------------------------------------
    float[] b;                                   // terrain height, world units
    float[] d;                                   // water depth, world units
    float[] fE, fW, fN, fS;                      // flow through each cell's four pipes
    float cs;                                    // cell size, world units
    float deluge;                                // seconds of deluge left

    // ---- view ---------------------------------------------------------------------------
    PFont font;
    int layer;                                   // 0 relief, 1 temperature, 2 rain
    float yaw = -0.5f, pitch = 0.8f, zoom = 1, heightMul = 1, ex = -1;
    float animT;
    bool paused;
    float pressX, pressY;
    float[] sx, sy;                              // each grid point on screen (for clicks)
    readonly PointCloud clouds = new();

    public override void Setup()
    {
        Size(1000, 640);
        font = CreateFont("Segoe UI", 14);
        countriesReq = RequestGeoJSON(CountriesUrl, cacheFor: TimeSpan.FromDays(365));
    }

    // =====================================================================================
    // Choosing a country: its main piece and the islands near it, then a grid over it
    // =====================================================================================
    void Choose(GeoFeature f, float clickLat, float clickLon)
    {
        country = f;
        picking = false;
        outline.Clear();
        GeoRing main = null; float best = -1;
        foreach (var ring in f.Rings)
        {
            if (ring.IsHole) continue;
            if (InRing(ring.Lat, ring.Lon, clickLat, clickLon)) { main = ring; break; }
            float area = Area(ring);
            if (area > best) { best = area; main = ring; }
        }
        if (main == null) return;
        var (mLat0, mLat1, mLon0, mLon1) = Box(main.Lat, main.Lon);
        float mainLon = (mLon0 + mLon1) / 2;
        float reach = Math.Max(1.5f, 0.4f * Math.Max(mLat1 - mLat0, mLon1 - mLon0));
        foreach (var ring in f.Rings)
        {
            var (a0, a1, o0, o1) = Box(ring.Lat, ring.Lon);
            float shift = 360 * MathF.Round((mainLon - (o0 + o1) / 2) / 360);   // across the date line
            if (a1 < mLat0 - reach || a0 > mLat1 + reach || o1 + shift < mLon0 - reach || o0 + shift > mLon1 + reach) continue;
            var lon = (float[])ring.Lon.Clone();
            for (int i = 0; i < lon.Length; i++) lon[i] += shift;
            outline.Add((ring.Lat, lon));
        }

        minLat = minLon = float.MaxValue; maxLat = maxLon = float.MinValue;
        foreach (var (la, lo) in outline)
        {
            var (a0, a1, o0, o1) = Box(la, lo);
            minLat = Math.Min(minLat, a0); maxLat = Math.Max(maxLat, a1);
            minLon = Math.Min(minLon, o0); maxLon = Math.Max(maxLon, o1);
        }
        float padLat = (maxLat - minLat) * 0.03f + 0.02f, padLon = (maxLon - minLon) * 0.03f + 0.02f;
        minLat -= padLat; maxLat += padLat; minLon -= padLon; maxLon += padLon;
        lat0 = (minLat + maxLat) / 2; lon0 = (minLon + maxLon) / 2;
        kmX = 111.32f * MathF.Cos(lat0 * MathF.PI / 180); kmZ = 110.57f;
        float wKm = (maxLon - minLon) * kmX, hKm = (maxLat - minLat) * kmZ;
        scale = W / Math.Max(wKm, hKm);
        float spacing = Math.Max(wKm, hKm) / (Cells - 1);
        nx = Math.Max(3, (int)MathF.Round(wKm / spacing) + 1);
        ny = Math.Max(3, (int)MathF.Round(hKm / spacing) + 1);
        dLon = (maxLon - minLon) / (nx - 1); dLat = (maxLat - minLat) / (ny - 1);
        cs = spacing * scale;

        Mask();
        int n = nx * ny;
        meters = new float[n]; Array.Fill(meters, float.NaN);
        arrivedAt = new long[n];
        b = new float[n]; d = new float[n];
        fE = new float[n]; fW = new float[n]; fN = new float[n]; fS = new float[n];
        temp = new float[n]; rain = new float[n]; cloud = new float[n];
        sx = new float[n]; sy = new float[n];
        heightsIn = 0; hi = 1; ex = -1;
        RequestTiles();
        RequestWeather();
    }

    /// <summary>
    /// Which grid points are inside the country, row by row: where each row crosses the
    /// outline, sorted, every other stretch is inside (much faster than testing each point).
    /// </summary>
    void Mask()
    {
        inside = new bool[nx * ny];
        var xs = new List<float>();
        for (int r = 0; r < ny; r++)
        {
            float lat = minLat + r * dLat;
            xs.Clear();
            foreach (var (la, lo) in outline)
                for (int i = 0, j = la.Length - 1; i < la.Length; j = i++)
                    if ((la[i] > lat) != (la[j] > lat))
                        xs.Add(lo[i] + (lat - la[i]) / (la[j] - la[i]) * (lo[j] - lo[i]));
            xs.Sort();
            for (int k = 0; k + 1 < xs.Count; k += 2)
            {
                int c0 = Math.Max(0, (int)MathF.Ceiling((xs[k] - minLon) / dLon));
                int c1 = Math.Min(nx - 1, (int)MathF.Floor((xs[k + 1] - minLon) / dLon));
                for (int c = c0; c <= c1; c++) inside[r * nx + c] = true;
            }
        }
        drawn = new bool[nx * ny];
        for (int r = 0; r < ny; r++)
            for (int c = 0; c < nx; c++)
                for (int dr = -1; dr <= 1 && !drawn[r * nx + c]; dr++)
                    for (int dc = -1; dc <= 1; dc++)
                    {
                        int rr = r + dr, cc = c + dc;
                        if (rr >= 0 && cc >= 0 && rr < ny && cc < nx && inside[rr * nx + cc]) { drawn[r * nx + c] = true; break; }
                    }
    }

    static float Area(GeoRing ring)
    {
        float a = 0;
        for (int i = 0, j = ring.Count - 1; i < ring.Count; j = i++)
            a += (ring.Lon[j] - ring.Lon[i]) * (ring.Lat[j] + ring.Lat[i]);
        return Math.Abs(a) * MathF.Cos(ring.Lat[0] * MathF.PI / 180);
    }

    static (float, float, float, float) Box(float[] la, float[] lo)
    {
        float a0 = float.MaxValue, a1 = float.MinValue, o0 = float.MaxValue, o1 = float.MinValue;
        for (int i = 0; i < la.Length; i++)
        {
            a0 = Math.Min(a0, la[i]); a1 = Math.Max(a1, la[i]);
            o0 = Math.Min(o0, lo[i]); o1 = Math.Max(o1, lo[i]);
        }
        return (a0, a1, o0, o1);
    }

    static bool InRing(float[] la, float[] lo, float lat, float lon)
    {
        bool inside = false;
        for (int i = 0, j = la.Length - 1; i < la.Length; j = i++)
            if ((la[i] > lat) != (la[j] > lat) && lon < (lo[j] - lo[i]) * (lat - la[i]) / (la[j] - la[i]) + lo[i])
                inside = !inside;
        return inside;
    }

    // =====================================================================================
    // The relief: terrain tiles, Web Mercator like every web map
    // =====================================================================================
    static float TileX(float lon, int z) => (lon + 180) / 360 * (1 << z);
    static float TileY(float lat, int z)
    {
        double r = Math.Clamp(lat, -85, 85) * Math.PI / 180;
        return (float)((1 - Math.Log(Math.Tan(r) + 1 / Math.Cos(r)) / Math.PI) / 2 * (1 << z));
    }

    string TileUrl(int z, int x, int y) => $"https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png";

    void RequestTiles()
    {
        // The deepest zoom whose tiles over the country are 16 or fewer (plenty for 180 points).
        for (tileZoom = 10; tileZoom > 1; tileZoom--)
        {
            tx0 = (int)MathF.Floor(TileX(minLon, tileZoom)); ty0 = (int)MathF.Floor(TileY(maxLat, tileZoom));
            tilesW = (int)MathF.Floor(TileX(maxLon, tileZoom)) - tx0 + 1;
            tilesH = (int)MathF.Floor(TileY(minLat, tileZoom)) - ty0 + 1;
            if (tilesW * tilesH <= 16) break;
        }
        tiles = new Request<PImage>[tilesW * tilesH];
        tileRead = new bool[tiles.Length];
        int n = 1 << tileZoom;
        for (int t = 0; t < tiles.Length; t++)
        {
            int x = ((tx0 + t % tilesW) % n + n) % n, y = ty0 + t / tilesW;
            if (y >= 0 && y < n) tiles[t] = RequestPImage(TileUrl(tileZoom, x, y), cacheFor: TimeSpan.FromDays(90));
        }
    }

    void ReadTiles()
    {
        for (int t = 0; t < tiles.Length; t++)
        {
            if (tileRead[t] || tiles[t] == null || !tiles[t].Done) continue;
            tileRead[t] = true;
            if (!tiles[t].Ready) continue;
            var img = tiles[t].Value;
            img.LoadPixels();
            var px = img.Pixels;
            int size = img.Width;
            float Height(int x, int y)
            {
                var c = px[Math.Clamp(y, 0, size - 1) * size + Math.Clamp(x, 0, size - 1)];
                return c.R * 256f + c.G + c.B / 256f - 32768;              // terrarium encoding
            }
            int tileX = tx0 + t % tilesW, tileY = ty0 + t / tilesW;
            for (int i = 0; i < nx * ny; i++)
            {
                if (!drawn[i]) continue;
                float lat = minLat + i / nx * dLat, lon = minLon + i % nx * dLon;
                float fx = (TileX(lon, tileZoom) - tileX) * size - 0.5f, fy = (TileY(lat, tileZoom) - tileY) * size - 0.5f;
                if (fx < -0.5f || fy < -0.5f || fx >= size - 0.5f || fy >= size - 0.5f) continue;
                int x0 = (int)MathF.Floor(fx), y0 = (int)MathF.Floor(fy);
                float ax = fx - x0, ay = fy - y0;
                float h = Lerp(Lerp(Height(x0, y0), Height(x0 + 1, y0), ax), Lerp(Height(x0, y0 + 1), Height(x0 + 1, y0 + 1), ax), ay);
                meters[i] = inside[i] ? h : Math.Max(h, 0);
                arrivedAt[i] = Millis();
                heightsIn++;
                if (inside[i]) hi = Math.Max(hi, h);
            }
        }
    }

    // =====================================================================================
    // The weather: one call for ~25 points, now and hour by hour
    // =====================================================================================
    void RequestWeather()
    {
        stations.Clear();
        weatherRead = false; hourTemp = null; fieldsForHour = -1;
        for (int i = 0; i < 6; i++)
            for (int j = 0; j < 6; j++)
            {
                float la = minLat + (maxLat - minLat) * (i + 0.5f) / 6, lo = minLon + (maxLon - minLon) * (j + 0.5f) / 6;
                int r = (int)MathF.Round((la - minLat) / dLat), c = (int)MathF.Round((lo - minLon) / dLon);
                if (inside[Math.Clamp(r, 0, ny - 1) * nx + Math.Clamp(c, 0, nx - 1)]) stations.Add((la, lo));
            }
        while (stations.Count < 2) stations.Add((lat0, lon0));    // two or more: the API answers with a list
        var inv = System.Globalization.CultureInfo.InvariantCulture;
        string lats = string.Join(",", stations.Select(s => s.Lat.ToString("0.###", inv)));
        string lons = string.Join(",", stations.Select(s => (((s.Lon + 540) % 360) - 180).ToString("0.###", inv)));
        weatherReq = RequestJSONArray($"https://api.open-meteo.com/v1/forecast?latitude={lats}&longitude={lons}" +
            "&current=temperature_2m,wind_speed_10m,wind_direction_10m&hourly=temperature_2m,precipitation,cloud_cover,weather_code" +
            "&forecast_days=3&timezone=GMT&wind_speed_unit=kmh", cacheFor: TimeSpan.FromMinutes(30));
    }

    void ReadWeather()
    {
        if (weatherRead || weatherReq == null || !weatherReq.Done) return;
        weatherRead = true;
        if (!weatherReq.Ready) return;
        var list = weatherReq.Value;
        int s = Math.Min(list.Size(), stations.Count);
        hourTemp = new float[s][]; hourRain = new float[s][]; hourCloud = new float[s][]; hourCode = new int[s][];
        float wsum = 0, wx = 0, wz = 0;
        for (int k = 0; k < s; k++)
        {
            var o = list.GetJSONObject(k);
            var h = o.GetJSONObject("hourly");
            var times = h.GetJSONArray("time");
            int count = times.Size();
            hourTemp[k] = Floats(h.GetJSONArray("temperature_2m"), count);
            hourRain[k] = Floats(h.GetJSONArray("precipitation"), count);
            hourCloud[k] = Floats(h.GetJSONArray("cloud_cover"), count);
            var codes = h.GetJSONArray("weather_code");
            hourCode[k] = new int[count];
            for (int i = 0; i < count; i++) hourCode[k][i] = codes.GetInt(i);
            if (k == 0)
            {
                hourTimes = new string[count];
                for (int i = 0; i < count; i++) hourTimes[i] = times.GetString(i);
                string now = o.GetJSONObject("current").GetString("time");
                nowHour = Math.Max(0, Array.FindIndex(hourTimes, t => now.Length >= 13 && t.StartsWith(now.Substring(0, 13))));
                hour = nowHour;
            }
            // The wind: the average over the stations, as a vector.
            var cur = o.GetJSONObject("current");
            float sp = cur.GetFloat("wind_speed_10m"), dir = Radians(cur.GetFloat("wind_direction_10m"));
            wx += sp * Sin(dir); wz += sp * Cos(dir); wsum++;
        }
        windKmh = Mag(wx, wz) / Math.Max(1, wsum);
        windFromDeg = (Degrees(Atan2(wx, wz)) + 360) % 360;
    }

    static float[] Floats(JSONArray a, int count)
    {
        var f = new float[count];
        for (int i = 0; i < count && i < a.Size(); i++) f[i] = a.GetFloat(i);
        return f;
    }

    /// <summary>The weather on the grid at the shown hour: each cell weighs the stations by 1 / distance².</summary>
    void Fields()
    {
        int h = (int)hour;
        if (hourTemp == null || h == fieldsForHour) return;
        fieldsForHour = h;
        tMin = float.MaxValue; tMax = float.MinValue; rainMax = 0;
        for (int i = 0; i < nx * ny; i++)
        {
            if (!drawn[i]) continue;
            float la = minLat + i / nx * dLat, lo = minLon + i % nx * dLon;
            float wsum = 0, t = 0, r = 0, c = 0;
            for (int k = 0; k < hourTemp.Length; k++)
            {
                float dx = (lo - stations[k].Lon) * kmX, dz = (la - stations[k].Lat) * kmZ;
                float w = 1 / (dx * dx + dz * dz + 25);
                int hh = Math.Min(h, hourTemp[k].Length - 1);
                t += w * hourTemp[k][hh]; r += w * hourRain[k][hh]; c += w * hourCloud[k][hh];
                wsum += w;
            }
            temp[i] = t / wsum; rain[i] = r / wsum; cloud[i] = c / wsum;
            if (inside[i]) { tMin = Math.Min(tMin, temp[i]); tMax = Math.Max(tMax, temp[i]); rainMax = Math.Max(rainMax, rain[i]); }
        }
    }

    // =====================================================================================
    // The water: virtual pipes
    // =====================================================================================
    void Simulate(float dt)
    {
        const float g = 9.8f, damping = 0.995f;
        int n = nx * ny;
        float area = cs * cs;
        // Sources and sinks: rain, the sun, the sea.
        for (int i = 0; i < n; i++)
        {
            if (!inside[i]) { d[i] = 0; continue; }
            float mmh = (hourTemp != null ? rain[i] : 0) + (deluge > 0 ? 40 : 0);
            d[i] += mmh * RainSpeed * dt;
            float evaporate = (0.0003f + 0.00003f * Math.Max(0, temp[i])) * dt;
            d[i] = Math.Max(0, d[i] - evaporate);
        }
        // Each pipe's flow grows with the difference of water surface across it.
        for (int r = 0; r < ny; r++)
            for (int c = 0; c < nx; c++)
            {
                int i = r * nx + c;
                if (!inside[i]) { fE[i] = fW[i] = fN[i] = fS[i] = 0; continue; }
                float h = b[i] + d[i];
                float Pipe(float f, int j) => j < 0 ? 0 : Math.Max(0, f * damping + dt * g * cs * (h - b[j] - d[j]));
                fE[i] = Pipe(fE[i], c + 1 < nx ? i + 1 : -1);
                fW[i] = Pipe(fW[i], c > 0 ? i - 1 : -1);
                fN[i] = Pipe(fN[i], r + 1 < ny ? i + nx : -1);
                fS[i] = Pipe(fS[i], r > 0 ? i - nx : -1);
                float out1 = (fE[i] + fW[i] + fN[i] + fS[i]) * dt;
                if (out1 > d[i] * area && out1 > 0)
                {
                    float k = d[i] * area / out1;                // never send more than the cell has
                    fE[i] *= k; fW[i] *= k; fN[i] *= k; fS[i] *= k;
                }
            }
        for (int r = 0; r < ny; r++)
            for (int c = 0; c < nx; c++)
            {
                int i = r * nx + c;
                if (!inside[i]) continue;
                float inflow = (c > 0 ? fE[i - 1] : 0) + (c + 1 < nx ? fW[i + 1] : 0) + (r > 0 ? fN[i - nx] : 0) + (r + 1 < ny ? fS[i + nx] : 0);
                float outflow = fE[i] + fW[i] + fN[i] + fS[i];
                d[i] = Math.Max(0, d[i] + dt * (inflow - outflow) / area);
            }
    }

    // =====================================================================================
    // Each frame
    // =====================================================================================
    public override void Draw()
    {
        Background(8, 12, 20);
        if (!countriesReq.Ready) { Centered("countries: " + countriesReq.Status); return; }
        if (worldMap == null) BuildWorldMap();
        if (picking) { DrawPicker(); return; }

        ReadTiles();
        ReadWeather();
        Fields();
        float dt = 1 / 60f;
        if (!paused)
        {
            animT += dt;
            if (hourTemp != null) hour = Math.Min(hour + dt / 4, hourTimes.Length - 1);   // 4 s per forecast hour
            deluge = Math.Max(0, deluge - dt);
            for (int k = 0; k < 3; k++) Simulate(dt);
        }

        // Terrain heights in world units, rising as they arrive; the exaggeration eases in.
        float target = Math.Clamp(0.09f * W / (Math.Max(hi, 300) / 1000 * scale), 1, 120) * heightMul;
        ex = ex < 0 ? target : Lerp(ex, target, 0.08f);
        float k1 = scale * ex / 1000;
        for (int i = 0; i < nx * ny; i++)
        {
            if (!drawn[i]) continue;
            float m = float.IsNaN(meters[i]) ? 0 : meters[i];
            float t = Math.Clamp((Millis() - arrivedAt[i]) / 900f, 0, 1);
            b[i] = m * k1 * (float.IsNaN(meters[i]) ? 0 : 1 - (1 - t) * (1 - t) * (1 - t));
        }

        var view = View3D.Orbit(yaw, pitch, 62 / zoom, new PVector(0, 1.5f, 0), 45);
        DrawLand(view);
        DrawSky(view);
        DrawBorder(view);
        Hud();
        Legend();
        MiniMap();
    }

    PVector World(int i, float y) =>
        new PVector((minLon + i % nx * dLon - lon0) * kmX * scale, y, (minLat + i / nx * dLat - lat0) * kmZ * scale);

    /// <summary>
    /// The terrain and its water, as one batch of triangles. No depth sorting: walking the
    /// grid from the side far from the camera to the near side paints a height field in the
    /// right order; each cell's water is drawn right over its ground.
    /// </summary>
    void DrawLand(View3D view)
    {
        int n = nx * ny;
        var wsx = new float[n]; var wsy = new float[n];
        var ground = new Color[n]; var water = new Color[n];
        var light = new PVector(-0.55f, 0.75f, 0.45f);
        light.Normalize();
        float top = Math.Max(hi, 400);
        for (int i = 0; i < n; i++)
        {
            if (!drawn[i]) continue;
            var p = view.Project(World(i, b[i]), Width, Height);
            sx[i] = p.X; sy[i] = p.Y;
            int c = i % nx, r = i / nx;
            float hl = b[c > 0 ? i - 1 : i], hr = b[c + 1 < nx ? i + 1 : i], hd = b[r > 0 ? i - nx : i], hu = b[r + 1 < ny ? i + nx : i];
            var nrm = new PVector(-(hr - hl) / (2 * cs), 1, -(hu - hd) / (2 * cs));
            nrm.Normalize();
            float lit = 0.35f + 0.8f * Math.Max(0, nrm.X * light.X + nrm.Y * light.Y + nrm.Z * light.Z);
            Color baseColor = float.IsNaN(meters[i]) ? Color(38, 52, 72)
                : layer == 1 && hourTemp != null ? TempColor(temp[i])
                : layer == 2 && hourTemp != null ? RainColor(rain[i], meters[i], top)
                : Hypsometric(meters[i], top);
            ground[i] = Color(Math.Min(255, baseColor.R * lit), Math.Min(255, baseColor.G * lit), Math.Min(255, baseColor.B * lit), inside[i] ? 255 : 120);
            if (d[i] > 0.003f)
            {
                var q = view.Project(World(i, b[i] + d[i]), Width, Height);
                wsx[i] = q.X; wsy[i] = q.Y;
                float deep = Math.Clamp(d[i] / 0.5f, 0, 1);
                float speed = Math.Clamp((fE[i] + fW[i] + fN[i] + fS[i]) / (cs * Math.Max(d[i], 0.02f)) * 0.6f, 0, 1);
                water[i] = Color(Lerp(Lerp(110, 25, deep), 235, speed * 0.6f), Lerp(Lerp(185, 85, deep), 245, speed * 0.6f), Lerp(Lerp(240, 175, deep), 255, speed * 0.6f),
                                 Lerp(120, 225, deep));
            }
            else { wsx[i] = sx[i]; wsy[i] = sy[i]; water[i] = Color(90, 170, 240, 0); }
        }

        // Far to near: which way that is depends on where the camera is.
        var eye = view.Eye;
        bool rowsUp = eye.Z < 0, colsUp = eye.X < 0;       // camera south -> start with the north rows
        NoStroke();
        BeginShape(ShapeKind.Triangles);
        for (int rr = 0; rr < ny - 1; rr++)
        {
            int r = rowsUp ? ny - 2 - rr : rr;
            for (int cc = 0; cc < nx - 1; cc++)
            {
                int c = colsUp ? nx - 2 - cc : cc;
                int a = r * nx + c, e = a + 1, f = a + nx, g = f + 1;
                if (!drawn[a] || !drawn[e] || !drawn[f] || !drawn[g]) continue;
                if (!inside[a] && !inside[e] && !inside[f] && !inside[g]) continue;
                Fill(ground[a]); Vertex(sx[a], sy[a]); Fill(ground[e]); Vertex(sx[e], sy[e]); Fill(ground[g]); Vertex(sx[g], sy[g]);
                Fill(ground[a]); Vertex(sx[a], sy[a]); Fill(ground[g]); Vertex(sx[g], sy[g]); Fill(ground[f]); Vertex(sx[f], sy[f]);
                if (water[a].A + water[e].A + water[f].A + water[g].A == 0) continue;
                Fill(water[a]); Vertex(wsx[a], wsy[a]); Fill(water[e]); Vertex(wsx[e], wsy[e]); Fill(water[g]); Vertex(wsx[g], wsy[g]);
                Fill(water[a]); Vertex(wsx[a], wsy[a]); Fill(water[g]); Vertex(wsx[g], wsy[g]); Fill(water[f]); Vertex(wsx[f], wsy[f]);
            }
        }
        EndShape();
    }

    /// <summary>Clouds where the forecast has them, drifting with the wind; rain under the rainy ones.</summary>
    void DrawSky(View3D view)
    {
        if (hourTemp == null && deluge <= 0) return;
        clouds.Clear();
        float to = Radians(windFromDeg + 180);
        float drift = windKmh / 30f * animT;                     // world units the clouds have moved
        float dx = Sin(to) * drift, dz = Cos(to) * drift;
        float lean = Math.Min(windKmh, 60) / 60f * 0.5f;
        float skyY = Math.Max(hi, 400) / 1000 * scale * ex + 4;
        float spanX = (maxLon - minLon) * kmX * scale, spanZ = (maxLat - minLat) * kmZ * scale;
        var streaks = new List<(float, float, float, float)>();
        int lattice = 52;
        for (int a = 0; a < lattice; a++)
            for (int c = 0; c < lattice; c++)
            {
                // A cloud slot fixed to the air, moved by the wind and wrapped around the country.
                float h1 = Hash(a * 977 + c), h2 = Hash(a * 131 + c * 7 + 3);
                float x = Wrap((c + h1) / lattice * spanX + dx, spanX) - spanX / 2;
                float z = Wrap((a + h2) / lattice * spanZ + dz, spanZ) - spanZ / 2;
                int col = (int)MathF.Round((x / (kmX * scale) + lon0 - minLon) / dLon), row = (int)MathF.Round((z / (kmZ * scale) + lat0 - minLat) / dLat);
                if (col < 0 || row < 0 || col >= nx || row >= ny) continue;
                int i = row * nx + col;
                if (!drawn[i]) continue;
                float cover = deluge > 0 ? 100 : cloud[i];
                if (h1 * 100 > cover) continue;
                float wet = deluge > 0 ? 40 : rain[i];
                float dark = Math.Clamp(wet / 4, 0, 1);
                float y = skyY + h2 * 2;
                clouds.Add(x, y, z, Color(Lerp(235, 120, dark), Lerp(240, 130, dark), Lerp(250, 150, dark), 60 + 90 * dark), 0.9f + 0.9f * h2);
                // Rain: a few streaks per rainy cloud, falling to the ground.
                int drops = wet > 0.1f ? 1 + (int)Math.Min(3, wet / 2) : 0;
                for (int k = 0; k < drops; k++)
                {
                    float ph = Hash(a * 31 + c * 17 + k);
                    float fall = (animT * 0.9f + ph) % 1;
                    float yy = y * (1 - fall);
                    float px = x + (ph - 0.5f) * 1.2f - Sin(to) * lean * (y - yy), pz = z + (Hash(k + c) - 0.5f) * 1.2f - Cos(to) * lean * (y - yy);
                    var p = view.Project(new PVector(px, yy, pz), Width, Height);
                    var q = view.Project(new PVector(px + Sin(to) * lean, yy + 1.2f, pz + Cos(to) * lean), Width, Height);
                    if (p.Depth > 0.5f && q.Depth > 0.5f) streaks.Add((p.X, p.Y, q.X, q.Y));
                }
            }
        StrokeWeight(1);
        Stroke(170, 205, 255, 150);
        BeginShape(ShapeKind.Lines);
        foreach (var (x0, y0, x1, y1) in streaks) { Vertex(x0, y0); Vertex(x1, y1); }
        EndShape();
        Points(clouds, view);
    }

    static float Wrap(float v, float m) => ((v % m) + m) % m;

    void DrawBorder(View3D view)
    {
        var segs = new List<(float, float, float, float)>();
        foreach (var (la, lo) in outline)
        {
            int step = Math.Max(1, la.Length / 1500);
            (float X, float Y, float Depth) prev = default;
            for (int i = 0; i <= la.Length; i += step)
            {
                int j = Math.Min(i, la.Length - 1);
                int c = Math.Clamp((int)MathF.Round((lo[j] - minLon) / dLon), 0, nx - 1), r = Math.Clamp((int)MathF.Round((la[j] - minLat) / dLat), 0, ny - 1);
                float y = b[r * nx + c] + 0.05f;
                var p = view.Project(new PVector((lo[j] - lon0) * kmX * scale, y, (la[j] - lat0) * kmZ * scale), Width, Height);
                if (i > 0 && p.Depth > 0.5f && prev.Depth > 0.5f) segs.Add((prev.X, prev.Y, p.X, p.Y));
                prev = p;
            }
        }
        StrokeWeight(1.2f);
        Stroke(255, 255, 255, 140);
        BeginShape(ShapeKind.Lines);
        foreach (var (x0, y0, x1, y1) in segs) { Vertex(x0, y0); Vertex(x1, y1); }
        EndShape();
    }

    // ---- colors ---------------------------------------------------------------------------
    Color Hypsometric(float h, float top)
    {
        float k = Math.Clamp(top / 4500, 0.25f, 1);
        (float H, int R, int G, int B)[] stops =
        {
            (0, 60, 130, 85), (250, 105, 160, 90), (700, 190, 185, 110), (1400, 175, 130, 80),
            (2300, 140, 110, 95), (3300, 205, 205, 210), (4500, 250, 250, 255),
        };
        return Ramp(stops, h, k);
    }

    Color TempColor(float t)
    {
        (float H, int R, int G, int B)[] stops =
        {
            (-20, 120, 60, 200), (-5, 90, 140, 235), (5, 120, 210, 230), (15, 150, 220, 120),
            (25, 245, 200, 70), (33, 235, 100, 50), (42, 170, 30, 60),
        };
        return Ramp(stops, t, 1);
    }

    Color RainColor(float mmh, float meters, float top)
    {
        var g = Hypsometric(meters, top);
        float gray = (g.R + g.G + g.B) / 3f * 0.6f;
        float k = Math.Clamp(mmh / 8, 0, 1);
        return mmh < 0.05f ? Color(gray, gray, gray) : Color(Lerp(gray, 60, k), Lerp(gray + 30, 120, k), Lerp(gray + 60, 255, k));
    }

    Color Ramp((float H, int R, int G, int B)[] stops, float v, float k)
    {
        for (int s = 1; s < stops.Length; s++)
        {
            float h1 = stops[s].H * k;
            if (v <= h1 || s == stops.Length - 1)
            {
                float h0 = stops[s - 1].H * k;
                float t = Math.Clamp((v - h0) / Math.Max(1e-3f, h1 - h0), 0, 1);
                return Color(Lerp(stops[s - 1].R, stops[s].R, t), Lerp(stops[s - 1].G, stops[s].G, t), Lerp(stops[s - 1].B, stops[s].B, t));
            }
        }
        return Color(255, 255, 255);
    }

    static float Hash(int n)
    {
        unchecked
        {
            uint x = (uint)n * 747796405u + 2891336453u;
            x = ((x >> (int)((x >> 28) + 4)) ^ x) * 277803737u;
            return ((x >> 22) ^ x) / 4294967296f;
        }
    }

    // =====================================================================================
    // The world map
    // =====================================================================================
    void BuildWorldMap()
    {
        worldMap = CreateGraphics(Width, Width / 2);
        worldMap.BeginDraw();
        worldMap.Background(10, 16, 28);
        worldMap.Stroke(255, 255, 255, 18);
        for (int lo = -180; lo <= 180; lo += 30) worldMap.Line((lo + 180) / 360f * Width, 0, (lo + 180) / 360f * Width, Width / 2);
        for (int la = -60; la <= 60; la += 30) worldMap.Line(0, (90 - la) / 180f * Width / 2, Width, (90 - la) / 180f * Width / 2);
        worldMap.Fill(48, 70, 92);
        worldMap.Stroke(110, 140, 170);
        worldMap.StrokeWeight(0.5f);
        foreach (var f in countriesReq.Value.Features) Shape(worldMap, f, Width, Width / 2, 0, 0);
        worldMap.EndDraw();
    }

    static void Shape(GraphicsContext g, GeoFeature f, float w, float h, float x, float y)
    {
        foreach (var ring in f.Rings)
        {
            if (ring.IsHole) continue;
            g.BeginShape();
            for (int i = 0; i < ring.Count; i++)
            {
                var (px, py) = Geo.Equirectangular(ring.Lat[i], ring.Lon[i], w, h);
                g.Vertex(x + px, y + py);
            }
            g.EndShape(true);
        }
    }

    void DrawPicker()
    {
        Image(worldMap, 0, mapY);
        hover = null;
        if (MouseY > mapY && MouseY < mapY + Width / 2)
        {
            var (la, lo) = Geo.FromEquirectangular(MouseX, MouseY - mapY, Width, Width / 2);
            hover = countriesReq.Value.FeatureAt(la, lo);
        }
        if (hover != null)
        {
            Fill(255, 200, 90); Stroke(255, 240, 200); StrokeWeight(1);
            Shape(this, hover, Width, Width / 2, 0, mapY);
        }
        TextFont(font, 22);
        TextAlign(TextAlignH.Left, TextAlignV.Top);
        Fill(235, 240, 255);
        Text(hover?.Name ?? "Pick a country", 20, 16);
        TextFont(font, 13);
        Fill(170, 185, 215);
        Text(hover != null ? "click: its relief, its weather and its water" : "click any country · R: a random one", 20, 46);
        TextAlign(TextAlignH.Left, TextAlignV.Bottom);
        Fill(255, 255, 255, 60);
        Text("Relief: Terrain Tiles on AWS (Mapzen) · Weather: Open-Meteo · Borders: Natural Earth", 20, Height - 14);
    }

    void MiniMap()
    {
        float mw = 200, mh = 100, mx = Width - mw - 16, my = 16;
        Tint(255, 255, 255, 200);
        Image(worldMap, mx, my, mw, mh);
        NoTint();
        Fill(255, 200, 90); NoStroke();
        Shape(this, country, mw, mh, mx, my);
        NoFill(); Stroke(255, 255, 255, 60); StrokeWeight(1);
        Rect(mx, my, mw, mh, 4);
    }

